// Generated content localization — English keys are stable lookup ids.
const dict: Record<string, string> = {
  "p.0": "मेरे स्वर्गीय पिता, इस दिन को किसी और की उम्मीदों के आगे रखने से पहले, मैं इसे आपके हाथों में सौंपता हूँ। मेरे विचारों को सही राह दिखाइए, मेरी भावनाओं को सँभालिए और जो भला है, उस ओर मेरी अगुवाई कीजिए। डर के बजाय, मेरा पहला जवाब विश्वास हो। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जो मुझे समझ आती हैं, और उनके लिए भी जो मैं नहीं समझ पाता। आमीन।",
  "p.1": "प्रभु यीशु, मेरा मन ऐसी चिंताओं से भरा है जिन्हें मैं अकेला सुलझा नहीं सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति मेरी घबराहट से कहीं बड़ी है। मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। मेरे दिल को ऐसा बना दीजिए कि इसमें मसीह की छवि झलकने लगे। आमीन।",
  "p.2": "पवित्र आत्मा, मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मुझे हर अगले कदम के लिए धीरज और साहस दीजिए। मुझे मज़बूत बनाइए पर कठोर नहीं। मुझे अपने वचनों में थामे रखिए, अपनी दया से घेरे रहिए और आशा से भर दीजिए। आमीन।",
  "p.3": "दयालु परमेश्वर, मैं उस दर्द को आपके पास लाता हूँ जिसे मैं मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझ, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। जिसे माफ़ी तुरंत नहीं मिटा पाती, उन ज़ख्मों को आप भर दीजिए। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.4": "दयालु पिता, मैं अपने परिवार और अपनों को आपके हाथों में सौंपता हूँ। हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से ढांप लीजिए। हमारी बातें नरम हों और हमारे रिश्ते मज़बूत हों। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं आपकी आज्ञा मान सकूँ। आमीन।",
  "p.5": "विश्वासयोग्य प्रभु, मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको अर्पित करता हूँ। मुझे सफलता के पीछे भागने के बजाय, पूरी ईमानदारी से काम करना सिखाइए। मेरे लिए लोगों की वाह-वाही से ज़्यादा आपकी सच्चाई मायने रखे। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.6": "प्यारे उद्धारकर्ता, मैं अपने शरीर, मन और आत्मा की हर उस बात को आपके पास लाता हूँ जिसे चंगाई की ज़रूरत है। जो घायल है उसे छुइए, जो कमज़ोर है उसे बल दीजिए, और हर देखभाल करने वाले को बुद्धि दीजिए। जवाब मिलने से पहले ही मुझमें एक उम्मीद जगा दीजिए। जो मैं खुद के लिए नहीं कर सकता, वह आप मेरे जीवन में कीजिए। आमीन।",
  "p.7": "सर्वशक्तिमान परमेश्वर, मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मुझे डर या घमंड में आकर फैसले लेने से बचाइए। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.8": "शांति के राजकुमार, मैं उन आशीषों को देखने के लिए रुकता हूँ जिन्हें मैं अक्सर भागदौड़ में अनदेखा कर देता हूँ। आम पलों में छिपी आपकी नेमतों को देखने के लिए मेरी आँखें खोल दीजिए। शुक्रगुज़ारी को मेरा स्वभाव बना दीजिए। आपकी कृपा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.9": "दया के पिता, मैं अपने जीवन और अपने हर कदम पर आपका साया चाहता हूँ। मुझे दिखने वाले खतरों और छिपे हुए फंदों से बचाइए। मुझे वहीं ले जाइए जहाँ मुझे जाना चाहिए और वहाँ रोक दीजिए जहाँ मुझे नहीं जाना चाहिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.10": "स्वर्गीय पिता, यह दुनिया मुझे मेरी नाकामियों और कमियों से तौलती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपका सच हर उस झूठ से ज़्यादा बुलंद हो जो दुनिया मुझ पर थोपती है। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जो मुझे समझ आती हैं, और उनके लिए भी जो मैं नहीं समझ पाता। आमीन।",
  "p.11": "प्रभु यीशु, मेरे भीतर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मेरे इस दर्द में मेरे साथ बैठिए और जल्दबाज़ी किए बिना मुझे तसल्ली दीजिए। मुझे प्यार के साथ बीती बातों को याद करना और उम्मीद के साथ जीना सिखाइए। मेरे दिल को ऐसा बना दीजिए कि इसमें मसीह की छवि झलकने लगे। आमीन।",
  "p.12": "पवित्र आत्मा, मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन दीजिए, बचने का साफ़ रास्ता दिखाइए, और जीवन को चुनने की शक्ति दीजिए। मुझे महसूस कराइए कि इसी पल आपकी आज्ञा मानना मेरे लिए मुमकिन है। मुझे अपने वचन में थामे रखिए, अपनी दया से मुझे घेर लीजिए, और मुझे आशा से भर दीजिए। आमीन।",
  "p.13": "दयालु परमेश्वर, मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़बरदस्ती करने लगा हूँ जो अभी तैयार नहीं हैं। मुझे अपने समय पर भरोसा करना सिखाइए ताकि मेरे मन में कड़वाहट न आए। इंतज़ार की इन घड़ियों में मेरा विश्वास बढ़ता रहे। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति मेरी शक्ति। आमीन।",
  "p.14": "रहमदिल पिता, मैं इस जीवन को आधे-अधूरे मन से या सोए हुए नहीं गुज़ारना चाहता। मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। मेरी वफ़ादारी के छोटे-छोटे कामों को अपनी महिमा के लिए इस्तेमाल कीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ, और मुझे इतनी हिम्मत दीजिए कि मैं आपकी बात मान सकूँ। आमीन।",
  "p.15": "वफ़ादार प्रभु, दिन ढलते ही मैं उन सारी बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं आज ठीक नहीं कर पाया। मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। कल सुबह मुझे आपकी नई दया मिले। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.16": "प्यारे उद्धारकर्ता, मैं अपने प्रेम, अपनी प्रतिबद्धता और अपने हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे को अपनाना सिखाइए। जो मैं खुद नहीं कर सकता, वो आप मुझमें कार्य कीजिए। आमीन।",
  "p.17": "सर्वशक्तिमान परमेश्वर, मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी वफ़ादार सुरक्षा में सौंपता हूँ। उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए, और उनके जीवन में सही सलाह देने वाले लोग भेजिए। वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। आज मेरा जीवन आपकी आराधना में एक भेंट बन जाए। आमीन।",
  "p.18": "शांति के राजकुमार, अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। हमें दीन, उदार, सच्चा और निडर बनाइए। हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। आपकी दया मेरी हर कमज़ोरी में मुझे सहारा दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.19": "दया के पिता, कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। जहाँ निराशा जम गई है, वहाँ अपनी आशा की फूँक मारिए। मुझे यकीन दिलाइए कि आप अब भी मेरे जीवन की कहानी के अच्छे अध्याय लिख रहे हैं। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.20": "स्वर्गीय पिता, आज मैं पूरी सच्चाई के साथ आपके पास आता हूँ: किसी और की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए, और जो भला है उसकी ओर मेरी अगुवाई कीजिए। यह प्रार्थना सिर्फ शब्दों तक न रहे; डर की जगह विश्वास ही मेरा पहला जवाब हो। आज मेरा जीवन आपकी आराधना में एक भेंट बन जाए। आमीन।",
  "p.21": "प्रभु यीशु, आज मैं पूरी सच्चाई के साथ आपके पास आता हूँ: मेरा मन ऐसी चिंताओं से भरा है जिन्हें मैं अकेला सुलझा नहीं सकता। कृपया मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। यह प्रार्थना सिर्फ शब्दों तक न रहे; मेरा हृदय आपकी शांति में सांस लेना सीखे। आपकी दया मेरी हर कमज़ोरी में मुझे सहारा दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.22": "पवित्र आत्मा, आज मैं पूरी सच्चाई के साथ आपके पास आता हूँ: मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी है। मुझे अगला कदम बढ़ाने के लिए धीरज दीजिए और उसके बाद के कदम के लिए हिम्मत। यह प्रार्थना सिर्फ शब्दों तक न रहे; मुझे मज़बूत बनाइए पर कठोर नहीं। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.23": "दयालु परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके पास आता हूँ: मैं वो चोटें आपके पास लाया हूँ जिन्हें मैं मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाइए। यह प्रार्थना सिर्फ शब्दों तक न रहे; उन घावों को भर दीजिए जिन्हें माफी तुरंत नहीं मिटा पाती। मैं उन बातों पर भी आप पर भरोसा करता हूँ जो मैं समझता हूँ, और उन पर भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.24": "दयालु पिता, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं अपने परिवार और उन सभी को आपके हाथों में सौंपता हूँ जो मेरे दिल के सबसे करीब हैं। प्रभु, हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से ढाँप लीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; हमारी बातचीत में नरमी आए और हमारे रिश्ते मज़बूत हों। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की झलक दिखाई दे। आमीन।",
  "p.25": "विश्वासयोग्य प्रभु, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं अपने हाथों की मेहनत और अपनी ज़िम्मेदारियों का बोझ आपके चरणों में रखता हूँ। प्रभु, मदद कीजिए कि मैं सफलता के पीछे भागने के बजाय, पूरे मन से आपकी सेवा करूँ। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मेरे लिए लोगों की वाह-वाही से बढ़कर मेरी सच्चाई हो। मुझे अपने वचन की बुनियाद पर खड़ा कीजिए, अपनी दया के घेरे में रखिए और मुझे नई उम्मीद से भर दीजिए। आमीन।",
  "p.26": "प्यारे उद्धारकर्ता, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं अपने शरीर, मन और आत्मा की हर उस बात को आपके पास लाता हूँ जिसे चंगाई की ज़रूरत है। प्रभु, मेरे ज़ख्मों को छुएँ, मेरी कमज़ोरी को ताकत दें और मेरी देखभाल करने वालों को बुद्धि दें। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; इससे पहले कि मुझे जवाब मिले, मेरा दिल उम्मीद से भर जाए। आपकी मर्ज़ी ही मेरा सुकून बने और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.27": "सर्वशक्तिमान परमेश्वर, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। प्रभु, मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मुझे डर या घमंड में आकर फैसले लेने से बचाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसे मानने का साहस पा सकूँ। आमीन।",
  "p.28": "शांति के राजकुमार, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं कुछ पल ठहरकर आपकी उन आशीषों को देखना चाहता हूँ जिन्हें मैं अक्सर भाग-दौड़ में भूल जाता हूँ। प्रभु, आम पलों में छिपी अपनी मेहरबानियों को देखने के लिए मेरी आँखें खोल दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; शुक्रगुज़ारी को मेरा स्वभाव बना दीजिए। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.29": "दया के पिता, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं अपने जीवन और आज के हर कदम पर आपका साया माँगता हूँ। प्रभु, मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाए रखिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; जहाँ मुझे जाना चाहिए वहाँ मुझे ले चलिए और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक लीजिए। जो मैं अपने बलबूते नहीं कर सकता, वो आप मुझमें कार्य करके पूरा कीजिए। आमीन।",
  "p.30": "स्वर्गीय पिता, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: यह दुनिया मुझे मेरी नाकामियों या मेरे काम से पहचानने की कोशिश करती है। प्रभु, मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से खरीदा गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; आपका सत्य मेरे जीवन की हर झूठी बात से बड़ा हो। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.31": "प्रभु यीशु, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मेरे मन में ऐसा दुख है जिसे मैं शब्दों में बयां नहीं कर सकता। प्रभु, इस दर्द में मेरे पास बैठिए और मुझे तसल्ली दीजिए, चंगा होने में मुझ पर दबाव न डालिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मुझे पुरानी यादों को प्यार से सहेजना और फिर भी उम्मीद के साथ जीना सिखाइए। आपका अनुग्रह मेरी हर कमज़ोरी में मुझे थाम ले और मुझे शांति की ओर ले चले। आमीन।",
  "p.32": "पवित्र आत्मा, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं उन बातों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। प्रभु, मुझे एक शुद्ध हृदय, बुराई से बचने का रास्ता और सही चुनाव करने की ताकत दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; इसी पल आपकी आज्ञा मानना मेरे लिए मुमकिन कर दीजिए। मुझे धीरज से चलना, दिल से प्रेम करना और आप पर पूरा भरोसा करना सिखाइए। आमीन।",
  "p.33": "अनुग्रहकारी परमेश्वर, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन बातों को जल्दबाज़ी में पूरा करना चाहता हूँ जो अभी तैयार नहीं हैं। प्रभु, मुझे अपने समय पर भरोसा करना सिखाइए ताकि मेरे मन में कड़वाहट न आए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; इस देरी के समय में मेरा विश्वास बढ़ता रहे। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जो मैं समझता हूँ, और उनके लिए भी जो मैं नहीं समझ पाता। आमीन।",
  "p.34": "दयालु पिता, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: मैं नहीं चाहता कि मेरा जीवन यूँ ही बिना किसी मकसद के बीत जाए। प्रभु, मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मेरी छोटी-छोटी वफादारियाँ भी आपके राज्य के लिए मायने रखें। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की झलक दिखाई दे। आमीन।",
  "p.35": "विश्वासयोग्य प्रभु, आज मैं बड़ी ईमानदारी से आपके सामने आता हूँ: दिन ढलते ही मैं उन सब बातों को आपके हाथों में छोड़ता हूँ जिन्हें मैं आज ठीक नहीं कर पाया। प्रभु, मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे दिल को महफूज़ रखिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; आने वाली सुबह मुझे आपकी नई करुणा के दर्शन हों। मुझे अपने वचन में मज़बूत कीजिए, अपनी दया में थामे रखिए और नई उम्मीद से भर दीजिए। आमीन।",
  "p.36": "प्यारे उद्धारकर्ता, मैं आज पूरी ईमानदारी के साथ आपके पास आता हूँ: मैं अपने प्यार, अपनी प्रतिबद्धताओं और उन सभी रिश्तों को आपके हाथों में सौंपता हूँ जिन्हें आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे का साथ चुनना सिखाइए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.37": "सर्वशक्तिमान परमेश्वर, मैं आज सच्चाई के साथ आपके सामने खड़ा हूँ: मैं अपने उन बच्चों और नौजवानों को, जिन्हें मैं बहुत प्यार करता हूँ, आपकी सुरक्षित देखरेख में सौंपता हूँ। उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें भले लोगों की संगति दीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक न रहे; उन्हें ऐसी कृपा दीजिए कि वे आपको गहराई से और करीब से जान सकें। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और मुझमें आपकी आज्ञा मानने की हिम्मत हो। आमीन।",
  "p.38": "शांति के राजकुमार, मैं आज सच्चाई के साथ आपके सामने आता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के प्रति हमारे प्रेम को नया कर दीजिए। हमें नम्र, उदार, सच्चा और निडर बनाइए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; हमारा जीवन ऐसा हो कि यह दुनिया हममें प्रभु यीशु की सुंदरता देख सके। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.39": "दयालु पिता, मैं आज ईमानदारी से आपके सामने अपने मन की बात रखता हूँ: कुछ वादे अब भी बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। जहाँ निराशा ने घर कर लिया है, वहाँ उम्मीद की नई किरण जगा दीजिए। मेरी यह प्रार्थना शब्दों से बढ़कर हो; मुझे विश्वास दिलाइए कि आप अब भी मेरी ज़िंदगी की कहानी में अच्छे अध्याय लिख रहे हैं। जो मैं अपने दम पर नहीं कर सकता, वह मेरे जीवन में कर दिखाइए। आमीन।",
  "p.40": "स्वर्गीय पिता, ज़िंदगी की इस आपाधापी के बीच मुझसे मिलने के लिए आपका धन्यवाद। आज के दिन को किसी और की उम्मीदों पर छोड़ने से पहले, मैं इसे आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मुझे अच्छाई की राह पर ले चलिए। आपकी कृपा से, डरने के बजाय मेरा मन विश्वास से भरा रहे। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और मुझमें आपकी आज्ञा मानने की हिम्मत हो। आमीन।",
  "p.41": "प्रभु यीशु, ज़िंदगी की उलझनों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेले सुलझा नहीं सकता। मेरे भीतर के इस शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। आपकी कृपा से, मेरे दिल को आपकी शांति में चैन मिले। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.42": "पवित्र आत्मा, ज़िंदगी के इस सफर में मेरा साथ देने के लिए धन्यवाद, जहाँ आगे का रास्ता मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मुझे हर अगले कदम के लिए धीरज और साहस दीजिए। आपकी कृपा से, मुझे मज़बूत बनाइए पर कठोर नहीं। जो मैं अपनी ताकत से नहीं कर सकता, वह मेरे जीवन में कर दिखाइए। आमीन।",
  "p.43": "दयालु परमेश्वर, ज़िंदगी की कड़वी सच्चाई के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं आपके पास वह दर्द लेकर आया हूँ जो मुझे चुपचाप अंदर ही अंदर कचोटता रहता है। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ माफ़ करना सिखाइए। आपकी कृपा उन ज़ख्मों को भर दे जिन्हें सिर्फ माफ़ी से नहीं मिटाया जा सकता। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.44": "दयालु पिता, इस भागदौड़ भरी ज़िंदगी में मेरे साथ होने के लिए धन्यवाद। मैं अपने परिवार और अपने प्रियजनों को आपके सामने लाता हूँ। हमारे घर को सब्र, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। आपकी कृपा से हमारी बोली में मिठास और हमारे रिश्तों में मज़बूती बनी रहे। आपकी दया मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह दिखाए। आमीन।",
  "p.45": "सच्चे प्रभु, ज़िंदगी की चुनौतियों के बीच मेरा हाथ थामने के लिए धन्यवाद। मैं अपने हाथों की मेहनत और अपने कंधों का बोझ आपको सौंपता हूँ। अपनी प्रशंसा ढूँढने के बजाय, सच्चाई के साथ काम करने में मेरी मदद कीजिए। आपकी कृपा से, दुनिया की वाहवाही से ज़्यादा मेरे लिए मेरी ईमानदारी मायने रखे। मुझे धीरे चलना, गहरा प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.46": "प्यारे उद्धारकर्ता, इस ज़िंदगी के संघर्षों में मेरे साथ होने के लिए धन्यवाद। मैं अपने शरीर, मन और प्राण की हर वह बात आपके पास लाता हूँ जिसे चंगाई की ज़रूरत है। मेरे ज़ख्मों को छू लीजिए, मेरी कमज़ोरी को ताकत में बदलिए और मेरी देखरेख करने वालों को बुद्धि दीजिए। आपकी कृपा से, प्रार्थना का जवाब मिलने से पहले ही मेरे अंदर उम्मीद जाग उठे। मैं उन बातों में भी आप पर भरोसा रखता हूँ जिन्हें मैं समझ नहीं पाता। आमीन।",
  "p.47": "सर्वशक्तिमान परमेश्वर, ज़िंदगी के मुश्किल मोड़ों पर मेरा साथ देने के लिए धन्यवाद। मुझे सिर्फ जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे दिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। आपकी कृपा मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाए। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.48": "शांति के राजकुमार, रोज़मर्रा की ज़िंदगी के बीच में मुझसे मिलने के लिए आपका धन्यवाद। यहाँ रुककर मैं उन आशीषों को निहारता हूँ जिन्हें मैं अक्सर जल्दबाज़ी में अनदेखा कर देता हूँ। मैं आपसे विनती करता हूँ कि मेरी आँखें उन उपहारों के लिए खोल दीजिए जो इन साधारण पलों में छिपे हैं। अपने अनुग्रह से, शुक्रगुज़ारी को मेरा स्वभाव बना दीजिए, न कि केवल एक पल की भावना। मुझे अपने वचन में जड़ पकड़ने दीजिए, अपनी दया से मुझे घेर लीजिए और मुझे आशा से भर दीजिए। आमीन।",
  "p.49": "दयालु पिता, इस भागदौड़ भरी ज़िंदगी के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने जीवन और आज के अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। मैं प्रार्थना करता हूँ कि आप दिखने वाले खतरों और छिपे हुए फंदों से मेरी रक्षा करें। अपने अनुग्रह से, जहाँ मुझे जाना चाहिए वहाँ मुझे भेजें और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक लें। आपकी मर्ज़ी ही मेरी शांति और आपकी उपस्थिति ही मेरी ताकत बन जाए। आमीन।",
  "p.50": "स्वर्गीय पिता, ज़िंदगी की जद्दोजहद के बीच में मुझसे मिलने के लिए आपका धन्यवाद। यह दुनिया अक्सर मेरी नाकामियों, काम के दबाव या मेरे दुखों से मेरी पहचान बनाने की कोशिश करती है। मैं आपसे विनती करता हूँ कि मुझे याद दिलाते रहें कि मैं आपका हूँ, आपके अनुग्रह ने मुझे छुड़ा लिया है और आपने मुझे अपने प्रेम में थाम रखा है। आपकी कृपा से, आपका सत्य हर झूठी बातों से ज़्यादा गूँजने पाए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.51": "प्रभु यीशु, रोज़मर्रा के जीवन के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मेरे भीतर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मैं आपसे विनती करता हूँ कि आप इस दर्द में मेरे साथ बैठें और मुझे तसल्ली दें; मेरे घावों को भरने में जल्दबाज़ी न करें। अपने अनुग्रह से, मुझे प्यार भरी यादों के साथ थामना और आशा के साथ जीना सिखाइए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.52": "पवित्र आत्मा, जीवन की आपाधापी के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं उन बातों के खिंचाव को महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मैं आपसे विनती करता हूँ कि मुझे एक शुद्ध मन, बुराई से बचने का रास्ता और जीवन को चुनने की शक्ति दें। अपने अनुग्रह से, इसी घड़ी मेरे लिए आपकी आज्ञा मानना मुमकिन कर दीजिए। वह काम मुझमें पूरा कीजिए जिसे मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.53": "अनुग्रहकारी परमेश्वर, मेरी वास्तविक ज़िंदगी के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़ोर लगाने की कोशिश करता हूँ जिनका समय अभी नहीं आया है। मैं आपसे विनती करता हूँ कि बिना कड़वाहट या आलस के मुझे आपके समय पर भरोसा करना सिखाइए। अपने अनुग्रह से, इस देरी के समय में मेरा विश्वास और गहरा कीजिए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.54": "दयालु पिता, इस भागदौड़ भरी ज़िंदगी के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं इस जीवन को बिना मकसद या अधूरी जागृति में नहीं बिताना चाहता। मैं आपसे विनती करता हूँ कि आप मुझे वह भलाई के काम दिखाएं जो आपने आज मेरे लिए तैयार किए हैं। अपनी कृपा से, मेरी वफादारी के इन छोटे-छोटे कामों को अनंत काल के लिए कीमती बना दीजिए। आपका अनुग्रह मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.55": "विश्वासयोग्य प्रभु, इस दिन के अंत में मुझसे मिलने के लिए आपका धन्यवाद। जो बातें आज मैं सुधार नहीं पाया, उन्हें मैं आपके हाथों में सौंपता हूँ। मैं आपसे विनती करता हूँ कि मेरे मन को अपनी शांति से धो दें और सोते समय मेरे हृदय को सुरक्षित रखें। अपने अनुग्रह से, कल सुबह मुझे नई करुणा के साथ उठाएं। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.56": "प्यारे उद्धारकर्ता, जीवन की हकीकत के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने प्रेम, समर्पण और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। अपनी कृपा से, हमें एक-दूसरे को सुनना, क्षमा करना और बार-बार एक-दूसरे का साथ चुनना सिखाइए। जो मैं समझता हूँ और जो नहीं समझ पाता, उन सब बातों के लिए मैं आप पर भरोसा करता हूँ। आमीन।",
  "p.57": "सर्वशक्तिमान परमेश्वर, वास्तविक जीवन के बीच में मुझसे मिलने के लिए आपका धन्यवाद। मैं उन बच्चों और नौजवानों को जिन्हें मैं प्रेम करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। मैं आपसे विनती करता हूँ कि आप उनके दिलों की रक्षा करें, उनके फैसलों में अगुवाई करें और उन्हें सही सलाह देने वाले लोगों से घेर लें। अपने अनुग्रह से, उन्हें खुद आपको गहराई से जानने में मदद करें। मेरे हृदय को ऐसा रूप दें कि वह मसीह के हृदय को प्रतिबिंबित करे। आमीन।",
  "p.58": "शांति के राजकुमार, इस जीवन के बीच में हमसे मिलने के लिए आपका धन्यवाद। आप अपने लोगों को आशीष दें और एक-दूसरे के लिए हमारे प्रेम को नया कर दें। मैं आपसे विनती करता हूँ कि हमें विनम्र, उदार, सच्चा और निडर बनाएं। आपकी कृपा से, हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से मुझे ढांप लीजिए और मुझे आशा से भर दीजिए। आमीन।",
  "p.59": "दयालु पिता, इस जीवन के सफर के बीच में मुझसे मिलने के लिए आपका धन्यवाद। यहाँ कुछ वादे बहुत दूर लगते हैं और कुछ सपने टूटते हुए महसूस होते हैं। मैं आपसे विनती करता हूँ कि जहाँ निराशा घर कर गई है, वहाँ फिर से आशा की फूंक मार दें। अपने अनुग्रह से, मुझे यह विश्वास करने में मदद करें कि आप अब भी मेरे जीवन के अच्छे अध्याय लिख रहे हैं। आपकी मर्ज़ी ही मेरी शांति और आपकी उपस्थिति ही मेरी ताकत बन जाए। आमीन।",
  "p.60": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपके हाथों में सौंपता हूँ: किसी और की उम्मीदों को पूरा करने की सोचने से पहले, मैं आज के इस दिन को आपके हाथों में रखता हूँ। मेरे पास बने रहिए, मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और मुझे भलाई की राह पर ले चलिए। मेरे विचारों, फैसलों और हर बात से यह दिखे कि मेरा पहला जवाब डर नहीं, बल्कि आप पर भरोसा है। मेरे दिल को ऐसा बना दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.61": "प्रभु यीशु, मैं अपनी इस ज़रूरत को आपके चरणों में लाता हूँ: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे करीब आइए, मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी हर डर और घबराहट से कहीं बड़ी है। मेरे विचारों, फैसलों और हर बात से यह झलके कि मेरा दिल आपकी शांति में सुकून पाना सीख रहा है। मुझे अपने वचन में मज़बूत कीजिए, अपनी करुणा से मुझे घेर लीजिए और मुझे नई उम्मीद से भर दीजिए। आमीन।",
  "p.62": "पवित्र आत्मा, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मेरे सामने जो रास्ता है, वह मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मेरे पास बने रहिए और मुझे आज के कदम के लिए धीरज और कल के लिए हिम्मत दीजिए। मेरे विचारों, फैसलों और हर बात से यह दिखे कि आप मुझे अंदर से मज़बूत बना रहे हैं, पर मेरा दिल कठोर न होने पाए। आपकी मरज़ी में ही मुझे शांति मिले और आपकी मौजूदगी ही मेरी ताकत बन जाए। आमीन।",
  "p.63": "दयालु परमेश्वर, मैं अपनी इस ज़रूरत को आपके सामने रखता हूँ: मैं उस दुख को आपके पास लाता हूँ जो मेरे दिल में बार-बार उठता रहता है। मेरे करीब रहिए, मुझे हर कड़वाहट से आज़ाद कीजिए और मुझे बुद्धि, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। मेरे विचारों, फैसलों और हर बात से यह दिखे कि आप उन घावों को भर रहे हैं जिन्हें माफ़ी भी तुरंत नहीं मिटा पाती। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और आपकी आज्ञा मानने का साहस पा सकूँ। आमीन।",
  "p.64": "दयालु पिता, मैं अपनी इस ज़रूरत को आपके चरणों में सौंपता हूँ: मैं अपने परिवार और उन लोगों को जो मुझे बहुत प्रिय हैं, आपके सामने लाता हूँ। मेरे करीब रहिए और हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। मेरे विचारों, फैसलों और हर बात से हमारे शब्दों में कोमलता और हमारे रिश्तों में मज़बूती आए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.65": "विश्वासयोग्य प्रभु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने हाथों की मेहनत और अपनी ज़िम्मेदारियों का बोझ आपके सामने रखता हूँ। मेरे पास रहिए, ताकि मैं सफलता के पीछे भागे बिना पूरी लगन से सेवा कर सकूँ। मेरे विचारों, फैसलों और हर बात से यह दिखे कि मेरे लिए लोगों की तारीफ से ज़्यादा मेरी ईमानदारी मायने रखती है। वह काम मुझमें पूरा कीजिए जिसे मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.66": "प्यारे उद्धारकर्ता, मैं अपनी इस ज़रूरत को आपके पास लाता हूँ: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपको सौंपता हूँ जिन्हें चंगाई की ज़रूरत है। मेरे करीब आइए, मेरे घावों को छुइए, मेरी कमज़ोरियों को ताकत दीजिए और मेरी देखभाल करने वालों को बुद्धि दीजिए। मेरे विचारों, फैसलों और हर बात से यह झलके कि प्रार्थना का उत्तर मिलने से पहले ही मेरा विश्वास बढ़ रहा है। मेरा आज का जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.67": "सर्वशक्तिमान परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। मेरे करीब रहिए और मुझे सिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मेरे विचारों, फैसलों और हर बात में मुझे डर या घमंड में आकर कोई भी निर्णय लेने से बचाइए। मेरी हर कमज़ोरी में आपका अनुग्रह मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.68": "शांति के राजकुमार, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं ठहरकर आपकी उन आशीषों को देखना चाहता हूँ जिन्हें मैं अक्सर भागदौड़ में अनदेखा कर देता हूँ। मेरे पास रहिए और मेरी आँखें खोलिए ताकि मैं रोज़मर्रा की आम चीज़ों में भी आपकी देन देख सकूँ। मेरे विचारों, फैसलों और हर बात से शुक्रगुज़ारी झलके—यह सिर्फ एक अहसास नहीं, बल्कि मेरा स्वभाव बन जाए। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.69": "दया के पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने जीवन और आज के हर कदम पर आपकी सुरक्षा चाहता हूँ। मेरे करीब रहिए और मुझे दिखने वाले खतरों और अनदेखे जालों से बचाकर रखिए। मेरे विचारों, फैसलों और हर बात में मेरी अगुवाई कीजिए, ताकि मैं वहीं जाऊँ जहाँ आप चाहते हैं और वहाँ रुक जाऊँ जहाँ आप मना करें। जो मैं समझता हूँ और जो नहीं समझ पाता, उन दोनों के लिए मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.70": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: यह दुनिया मुझे मेरी नाकामियों, काम या तकलीफों से पहचान देने की कोशिश करती है। मेरे पास बने रहिए और मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से बचाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरे विचारों, फैसलों और हर बात से यह दिखे कि आपका सच हर झूठी बात से ज़्यादा ताकतवर है। मेरे दिल को ऐसा बना दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.71": "प्रभु यीशु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मेरे भीतर ऐसा दुख है जिसे मैं शब्दों में बयां नहीं कर सकता। मेरे करीब आइए, मेरे दर्द में मेरे साथ बैठिए और मुझे बिना किसी जल्दबाज़ी के तसल्ली दीजिए। मेरे विचारों, फैसलों और हर बात से यह दिखे कि मैं प्यार के साथ बीती बातों को याद रख सकता हूँ और फिर भी उम्मीद के साथ जी सकता हूँ। मुझे अपने वचन में मज़बूत कीजिए, अपनी करुणा से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.72": "पवित्र आत्मा, मैं इस ज़रूरत को आपको सौंपता हूँ: मैं उन बातों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मेरे पास रहिए, मेरा हृदय शुद्ध कीजिए, मुझे बचने का रास्ता दिखाइए और जीवन को चुनने की ताकत दीजिए। मेरे विचार, निर्णय और व्यवहार यह दिखा सकें कि इस घड़ी आपकी आज्ञा मानना मुमकिन है। आपकी मर्ज़ी मेरी शांति बन जाए और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.73": "दयालु परमेश्वर, मैं इस ज़रूरत को आपको सौंपता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन बातों के लिए ज़बरदस्ती करने की कोशिश में हूँ जो अभी तैयार नहीं हैं। मेरे पास रहिए और मुझे सिखाए कि बिना निराश या कड़वाहट से भरे आपके समय पर कैसे भरोसा करना है। मेरे विचार और व्यवहार यह दिखा सकें कि इस देरी के समय में मेरा विश्वास और गहरा हो रहा है। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसमें चलने का साहस पा सकूँ। आमीन।",
  "p.74": "दयालु पिता, मैं इस ज़रूरत को आपको समर्पित करता हूँ: मैं इस जीवन को बिना किसी उद्देश्य के यूँ ही नहीं बिताना चाहता। मेरे करीब रहिए और मुझे वह भलाई दिखाइए जो आपने आज मेरे लिए तैयार की है। मेरे विचार और काम यह दिखा सकें कि वफादारी के मेरे छोटे-छोटे कदम आपके राज्य के लिए मायने रखते हैं। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.75": "वफादार प्रभु, मैं इस ज़रूरत को आपको सौंपता हूँ: दिन ढलने पर, मैं उन सब बातों को छोड़ देता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मेरे करीब रहिए, मेरे मन को शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। मेरे विचार और व्यवहार यह दिखा सकें कि कल का सवेरा मेरे लिए नई करुणा लेकर आएगा। जो मैं अपने आप में नहीं कर सकता, वह आप मुझमें कीजिए। आमीन।",
  "p.76": "प्यारे उद्धारकर्ता, मैं इस ज़रूरत को आपको सौंपता हूँ: मैं प्रेम, समर्पण और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। मेरे करीब रहिए और जहाँ तनाव ने हमारे बीच दूरियाँ पैदा कर दी हैं, वहाँ फिर से कोमलता भर दीजिए। मेरे विचार और व्यवहार यह दिखा सकें कि हमने एक-दूसरे की सुनना, माफ करना और फिर से साथ चलना सीख लिया है। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.77": "सर्वशक्तिमान परमेश्वर, मैं इस ज़रूरत को आपको सौंपता हूँ: मैं उन बच्चों और नौजवानों को आपकी वफादार देखभाल में सौंपता हूँ जिन्हें मैं प्यार करता हूँ। मेरे करीब रहिए, उनके मन की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें भले लोगों की संगति में रखिए। मेरे विचार और व्यवहार यह दिखा सकें कि वे आपको व्यक्तिगत और गहरे रूप से जानने पाएँ। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.78": "शांति के राजकुमार, मैं इस ज़रूरत को आपको सौंपता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। मेरे करीब रहिए और हमें विनम्र, उदार, सच्चा और निडर बनाइए। मेरे विचार और व्यवहार यह दिखा सकें कि हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर कर रहा है। मुझे ठहरकर चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.79": "दया के पिता, मैं इस ज़रूरत को आपको सौंपता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थक चुके हैं। मेरे करीब रहिए और जहाँ निराशा घर कर गई है, वहाँ फिर से उम्मीद की फूँक भर दीजिए। मेरे विचार और व्यवहार यह दिखा सकें कि मुझे विश्वास है कि आप अब भी मेरी कहानी के खूबसूरत अध्याय लिख रहे हैं। जो मैं समझता हूँ और जो नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.80": "स्वर्गीय पिता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: किसी और की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। जब आप मेरे विचारों को सही दिशा देते हैं, मेरी भावनाओं को सँभालते हैं, और मुझे भलाई की ओर ले चलते हैं, तो मैं आपकी सहायता स्वीकार करता हूँ। आज डर के बजाय मेरा पहला जवाब विश्वास हो। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.81": "प्रभु यीशु, आप देख रहे हैं कि मैं क्या सह रहा हूँ और यह मेरे लिए कितना बोझिल है: मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपकी मदद माँगता हूँ; मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति किसी भी घबराहट से बड़ी है। आज मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। मुझे ठहरकर चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.82": "पवित्र आत्मा, आप जानते हैं कि मैं क्या लेकर चल रहा हूँ: मेरे सामने की राह मेरी उम्मीद से कहीं ज़्यादा मुश्किल है। मैं आपकी सहायता माँगता हूँ ताकि मैं अपना अगला कदम वफादारी से उठा सकूँ और आने वाले कल के लिए साहस पा सकूँ। आज मुझे मज़बूत बनाइए पर कठोर नहीं। जो मैं समझता हूँ और जो नहीं, उन सब बातों में मैं आप पर भरोसा करता हूँ। आमीन।",
  "p.83": "दयालु परमेश्वर, आप मेरा बोझ देख रहे हैं: मैं आपके पास वह दर्द लाया हूँ जिसे मैं मन ही मन बार-बार दोहराता रहता हूँ। मुझे आपकी सहायता की ज़रूरत है ताकि मैं कड़वाहट से आज़ाद हो सकूँ और बुद्धि, सच्चाई और अनुग्रह के साथ दूसरों को क्षमा कर सकूँ। आज उन ज़ख्मों को भर दीजिए जो सिर्फ क्षमा करने से नहीं भरते। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.84": "दयालु पिता, आप देखते हैं कि मैं किन बोझों को लेकर चल रहा हूँ और आप जानते हैं कि वे मेरे लिए कितने ज़रूरी हैं। मैं अपने परिवार और उन लोगों को जो मुझे जान से प्यारे हैं, आपके चरणों में लाता हूँ। मैं आपकी मदद माँगता हूँ; हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। आज हमारे शब्दों में मिठास और हमारे रिश्तों में मज़बूती दीजिए। मुझे अपने वचन में दृढ़ कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.85": "विश्वासयोग्य प्रभु, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं अपने हाथों की मेहनत और अपने कन्धों के बोझ को आपको सौंपता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ कि मैं अपनी सफलता को अपना परमेश्वर बनाए बिना, पूरी सच्चाई और खराई के साथ सेवा कर सकूँ। आज मेरे लिए लोगों की वाह-वाही से बढ़कर मेरी ईमानदारी मायने रखे। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.86": "प्रेमी उद्धारकर्ता, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरी मदद कीजिए, आप मेरे ज़ख्मों को छुएँ, कमज़ोरियों को ताकत दें और मेरी देखभाल करने वालों को बुद्धि दें। आज, इससे पहले कि मुझे प्रार्थना का उत्तर दिखे, मेरे अंदर आशा भर दीजिए। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं आपकी आज्ञा मान सकूँ। आमीन।",
  "p.87": "सर्वशक्तिमान परमेश्वर, आप देखते हैं कि मैं क्या लेकर चल रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मेरी मदद कीजिए ताकि मैं जान सकूँ कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। आज मुझे उन फैसलों से बचाए रखिए जो केवल डर या घमण्ड में लिए जाते हैं। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.88": "शांति के राजकुमार, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं उन छोटी-छोटी आशीषों को देखने के लिए रुकता हूँ जिन्हें मैं अक्सर भाग-दौड़ में अनदेखा कर देता हूँ। मैं आपकी मदद माँगता हूँ कि आप मेरी आँखों को उन उपहारों के लिए खोलें जो आम पलों में छिपे होते हैं। आज, धन्यवाद करना मेरे लिए केवल एक भावना नहीं बल्कि एक आदत बन जाए। जो मैं अपने आप से नहीं कर सकता, वह आप मुझमें पूरा कीजिए। आमीन।",
  "p.89": "दया के सागर पिता, आप देखते हैं कि मैं क्या लेकर चल रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं आज अपने जीवन और अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। मेरी मदद कीजिए, मुझे हर दिखाई देने वाले खतरे और छिपे हुए फंदों से बचाए रखिए। आज जहाँ मुझे जाना चाहिए, वहाँ मेरी अगुवाई कीजिए और जहाँ नहीं जाना चाहिए, वहाँ मुझे रोक दीजिए। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.90": "स्वर्गीय पिता, आप देखते हैं कि मैं किन बोझों को लेकर चल रहा हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। यह दुनिया मुझे मेरी नाकामियों, मेरे काम या मेरे दुखों से पहचान देने की कोशिश करती है। मैं आपकी इस सच्चाई को थाम लेता हूँ कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आज आपका सत्य हर झूठी बातों से बढ़कर मेरे कानों में गूँजे। आपका अनुग्रह मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की ओर ले चले। आमीन।",
  "p.91": "प्रभु यीशु, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मेरे अंदर ऐसा दर्द है जिसे शब्द बयान नहीं कर सकते। मेरी मदद कीजिए, आप मेरे उस दर्द में मेरे साथ बैठिए और चंगाई के लिए मुझ पर दबाव डाले बिना मुझे तसल्ली दीजिए। आज मुझे प्यार के साथ याद रखना और आशा के साथ जीना सिखाइए। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.92": "पवित्र आत्मा, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं उन खिंचावों को महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करते हैं। मेरी मदद कीजिए, मुझे एक शुद्ध मन और बुराई से बचने का रास्ता दीजिए, और जीवन को चुनने की ताकत दीजिए। आज, इसी पल में, मुझे आपकी आज्ञा मानना संभव लगने लगे। जो मैं समझता हूँ और जो नहीं समझता, उन सब बातों में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.93": "अनुग्रहकारी परमेश्वर, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती पाने की कोशिश कर रहा हूँ जो अभी तैयार नहीं हैं। मेरी मदद कीजिए कि मैं चिड़चिड़ा या हताश हुए बिना आपके सही समय पर भरोसा करना सीखूँ। आज इस इंतज़ार में मेरे विश्वास को और गहरा कीजिए। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.94": "दयालु पिता, आप देखते हैं कि मैं क्या लेकर चल रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। मैं इस जीवन को बिना किसी मकसद के यूँ ही नहीं बिताना चाहता। मेरी मदद कीजिए और मुझे वह भलाई के काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। आज वफ़ादारी के साथ किए गए मेरे छोटे-छोटे काम भी आपके राज्य के लिए मायने रखें। मुझे अपने वचन में दृढ़ कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.95": "विश्वासयोग्य प्रभु, आप देखते हैं कि मैं क्या लेकर चल रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है। इस दिन के अंत में, मैं उन सब बातों को आपके हाथों में छोड़ देता हूँ जिन्हें मैं ठीक नहीं कर सकता। मेरी मदद कीजिए, सोते समय मेरे मन को अपनी शांति से धो दीजिए और मेरे हृदय को सुरक्षित रखिए। आज की रात बीतने पर कल सुबह आपकी नई दया मुझे मिले। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.96": "प्यारे उद्धारकर्ता, जो बोझ मैं उठाए हुए हूँ, आप उसे देखते हैं और जानते हैं कि वह मेरे लिए कितना ज़रूरी है: मैं अपने प्रेम, अपनी प्रतिबद्धताओं और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप हमारे बीच फिर से वही कोमलता ला रहे हैं जहाँ तनाव की वजह से कड़वाहट आ गई थी। आज हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे का साथ देना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहस दीजिए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.97": "सर्वशक्तिमान परमेश्वर, आप मेरा बोझ देखते हैं और जानते हैं कि यह क्यों मायने रखता है: मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। मैं आपकी मदद माँगता हूँ कि आप उनके दिलों की रक्षा करें, उनके फैसलों में उनकी अगुवाई करें और उन्हें समझदार लोगों का साथ दें। आज, उन्हें आपको व्यक्तिगत रूप से और गहराई से जानने में मदद कीजिए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.98": "शांति के राजकुमार, आप मेरा बोझ देखते हैं और जानते हैं कि यह क्यों मायने रखता है: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। मैं आपकी मदद माँगता हूँ कि आप हमें विनम्र, उदार, सच्चा और निडर बनाएँ। आज हमारा जीवन ऐसा हो कि यह पूरी दुनिया के सामने प्रभु यीशु की सुंदरता को ज़ाहिर करे। जो मैं अपने आप से नहीं कर सकता, वह मुझमें होकर पूरा कीजिए। आमीन।",
  "p.99": "दयालु पिता, आप मेरा बोझ देखते हैं और जानते हैं कि यह क्यों मायने रखता है: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। मैं आपकी सहायता माँगता हूँ कि जहाँ निराशा घर कर गई है, वहाँ आप फिर से आशा फूँक दें। आज, मुझे यह विश्वास करने में मदद कीजिए कि आप अब भी मेरे जीवन की कहानी में अच्छे अध्याय लिख रहे हैं। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.100": "स्वर्गीय पिता, आज के दिन को किसी और की उम्मीदों पर सौंपने से पहले, मैं इसे आपके हाथों में रखता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और जो भला है, उसकी ओर मेरी अगुवाई कीजिए। मुश्किल में मेरा पहला कदम डर नहीं, बल्कि विश्वास हो। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.101": "प्रभु यीशु, मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेला सुलझा नहीं सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी हर घबराहट से कहीं बढ़कर है। मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। जो मैं अपने आप से नहीं कर सकता, वह मुझमें होकर पूरा कीजिए। आमीन।",
  "p.102": "पवित्र आत्मा, मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा कठिन लग रहा है। मुझे अगले कदम के लिए धीरज दीजिए और उसके बाद के कदम के लिए हिम्मत। मुझे मज़बूत बनाइए पर कठोर नहीं। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.103": "दयालु परमेश्वर, मैं उस दर्द को आपके पास लाता हूँ जिसे मैं मन ही मन बार-बार दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और बुद्धि, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। जिसे माफ़ी तुरंत नहीं मिटा पाती, उस घाव को आप भर दीजिए। आपकी कृपा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की ओर ले जाए। आमीन।",
  "p.104": "दयालु पिता, मैं अपने परिवार और उन लोगों को जो मेरे दिल के सबसे करीब हैं, आपके सामने लाता हूँ। हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाल लीजिए। हमारे शब्दों में नम्रता हो और हमारे रिश्ते मज़बूत बने रहें। मुझे धैर्य से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.105": "विश्वासयोग्य प्रभु, मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको अर्पित करता हूँ। सफलता के पीछे भागने के बजाय, पूरी ईमानदारी से आपकी सेवा करने में मेरी मदद कीजिए। मेरे लिए लोगों की वाहवाही से ज़्यादा आपका नाम ज़रूरी हो। जो बातें मैं समझता हूँ और जो नहीं समझता, उन सबमें मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.106": "प्यारे उद्धारकर्ता, मैं अपने शरीर, मन और प्राण की उन सभी बातों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जो घायल है उसे छुएँ, जो कमज़ोर है उसे बल दें और मेरी देखभाल करने वालों को बुद्धि दें। दुआ का जवाब मिलने से पहले ही मेरे अंदर आशा जगा दीजिए। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.107": "सर्वशक्तिमान परमेश्वर, मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। मुझे दिखाइए कि क्या चुनना है, क्या छोड़ना है और कब इंतज़ार करना है। मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाइए। मुझे अपने वचनों में थामे रखिए, अपनी दया से घेरे रखिए और आशा से भर दीजिए। आमीन।",
  "p.108": "शांति के राजकुमार, मैं उन मेहरबानियों पर ध्यान देने के लिए रुकता हूँ जिन्हें मैं अक्सर अनदेखा कर देता हूँ। आम पलों में छिपे आशीषों को देखने के लिए मेरी आँखें खोल दीजिए। धन्यवाद को मेरे मन का मिजाज नहीं, बल्कि मेरी आदत बना दीजिए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.109": "दया के पिता, मैं अपने जीवन पर और आज मेरे हर कदम पर आपका साया माँगता हूँ। मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाइए। जहाँ मुझे जाना चाहिए वहाँ मुझे ले चलिए और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक दीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहस दीजिए कि मैं आपकी आज्ञा मान सकूँ। आमीन।",
  "p.110": "स्वर्गीय पिता, यह दुनिया बार-बार मुझे मेरी नाकामियों, मेरे काम या मेरे दुखों से पहचानने की कोशिश करती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपका सत्य हर उस झूठी पहचान से बढ़कर हो जो दुनिया मुझ पर लगाती है। आज मुझे किसी ऐसे के लिए आशीष बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.111": "प्रभु यीशु, मेरे भीतर एक ऐसा दुख है जिसे शब्द पूरी तरह बयान नहीं कर सकते। इस दर्द में मेरे साथ बैठिए और मुझे ढाढ़स दीजिए, मेरे घाव भरने में जल्दबाजी न कीजिए। मुझे सिखाया जाए कि कैसे मैं बीते दिनों को प्यार से याद भी रखूँ और उम्मीद के साथ जीऊँ भी। मेरे भीतर वो काम कीजिए जिसे मैं खुद नहीं कर सकता। आमीन।",
  "p.112": "पवित्र आत्मा, मैं उन बातों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन दीजिए, बचने का एक साफ रास्ता दिखाइए और जीवन को चुनने का बल दीजिए। इस घड़ी में मेरे लिए आपकी बात मानना मुमकिन बना दीजिए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.113": "अनुग्रहकारी परमेश्वर, मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करना चाहता हूँ जो अभी तैयार नहीं हैं। मुझे सिखाए कि मैं मायूस या कड़वा हुए बिना आपके सही समय पर भरोसा कर सकूँ। इस इंतज़ार के दौरान मेरे विश्वास को और गहरा कर दीजिए। आपकी दया मेरी हर कमज़ोरी में मुझे थामे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.114": "दयालु पिता, मैं इस जीवन को यूँ ही सोते-जागते नहीं बिताना चाहता। मुझे वो नेक काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। वफ़ादारी के मेरे छोटे-छोटे कामों को अनंत काल के लिए मायने रखने वाला बना दीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.115": "विश्वासयोग्य प्रभु, आज का दिन खत्म होते ही, मैं उन बातों को आपके हाथ में छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे दिल की हिफाज़त कीजिए। कल का दिन मेरे लिए आपकी नई करुणा लेकर आए। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनके लिए भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.116": "प्यारे उद्धारकर्ता, मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। हमें एक-दूसरे की सुनना, माफ करना और बार-बार एक-दूसरे को चुनना सिखाइए। मेरे दिल को ऐसा बना दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.117": "सर्वशक्तिमान परमेश्वर, मैं उन बच्चों और नौजवानों को आपकी विश्वासयोग्य देखरेख में सौंपता हूँ जिनसे मैं प्रेम करता हूँ। उनके मन की रक्षा कीजिए, उनके फैसलों में उनका मार्गदर्शन कीजिए और उन्हें भले लोगों की संगति दीजिए। उन्हें आपकी व्यक्तिगत और गहरी पहचान पाने में मदद कीजिए। मुझे अपने वचन में मज़बूत कीजिए, अपनी दया से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.118": "शांति के राजकुमार, अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। हमें विनम्र, उदार, सच्चा और निडर बनाइए। हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.119": "दया के पिता, कुछ वादे अब बहुत दूर लगते हैं और कुछ सपने मानो थक गए हैं। जहाँ निराशा जम गई है, उन कोनों में फिर से उम्मीद की फूँक मार दीजिए। यह विश्वास करने में मेरी मदद कीजिए कि आप अब भी मेरे जीवन के अच्छे अध्याय लिख रहे हैं। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहस दीजिए कि मैं आपकी आज्ञा मान सकूँ। आमीन।",
  "p.120": "स्वर्गीय पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: इससे पहले कि मैं आज के दिन को दूसरों की उम्मीदों के हवाले करूँ, मैं इसे आपके हाथों में सौंप देता हूँ। कृपया मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मुझे उस ओर ले चलिए जो भला है। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; प्रभु, डरने के बजाय मेरा पहला चुनाव विश्वास हो। मुझे अपने वचन की नींव पर खड़ा कीजिए, अपनी दया से घेरे रखिए और मुझे आशा से भर दीजिए। आमीन।",
  "p.121": "प्रभु यीशु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मेरा मन ऐसी चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। कृपया मेरे भीतर के इस शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बढ़कर है। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। आपकी इच्छा ही मेरी शांति और आपकी उपस्थिति ही मेरी ताकत बन जाए। आमीन।",
  "p.122": "पवित्र आत्मा, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मेरे सामने का रास्ता मेरी सोच से कहीं ज़्यादा मुश्किल लग रहा है। कृपया मुझे हर एक कदम वफ़ादारी से उठाने की हिम्मत और अगले कदम के लिए साहस दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मुझे मज़बूत बनाइए पर मेरे दिल को कठोर न होने दीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसका पालन करने की हिम्मत जुटा सकूँ। आमीन।",
  "p.123": "दयालु परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं वह दर्द आपके पास लाता हूँ जिसे मैं अपने अंदर बार-बार दोहराता रहता हूँ। कृपया मुझे कड़वाहट से आज़ाद कीजिए और मुझे समझदारी, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; जो ज़ख्म माफ़ करने के बाद भी रह गए हैं, उन्हें अपनी छुअन से चंगा कीजिए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.124": "दयालु पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने परिवार और उन लोगों को जो मेरे दिल के सबसे करीब हैं, आपके सामने लाता हूँ। कृपया हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से सँभाल लीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; हमारी बातचीत में नरमी हो और हमारे आपसी रिश्ते मज़बूत हों। जो काम मैं खुद नहीं कर सकता, उसे आप मेरे जीवन में पूरा कीजिए। आमीन।",
  "p.125": "वफ़ादार प्रभु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने हाथों की मेहनत और अपनी ज़िम्मेदारियों का बोझ आपके चरणों में रखता हूँ। कृपया मेरी मदद कीजिए कि मैं सफलता को अपना देवता बनाए बिना, अपना हर काम पूरी मेहनत और लगन से करूँ। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मेरे लिए लोगों की वाहवाही से बढ़कर मेरी सच्चाई और ईमानदारी मायने रखे। आज मेरा जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.126": "प्यारे उद्धारकर्ता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने शरीर, मन और आत्मा की उन कमियों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। प्रभु, जो घायल है उसे छुएँ, जो कमज़ोर है उसे बल दें और मेरी देखभाल करने वालों को बुद्धि दें। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; चंगाई मिलने से पहले ही मेरे अंदर एक नई उम्मीद जग जाए। आपकी कृपा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.127": "सर्वशक्तिमान परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। कृपया मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मुझे डर या घमंड में आकर फैसले लेने से बचाइए। मुझे धीरज से चलना, दिल से प्यार करना और आप पर पूरा भरोसा करना सिखाइए। आमीन।",
  "p.128": "शांति के राजकुमार, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं कुछ पल रुककर उन आशीषों को याद करना चाहता हूँ जिन्हें मैं अक्सर अनदेखा कर देता हूँ। कृपया मेरी आँखें खोलिए ताकि मैं रोज़मर्रा के छोटे पलों में आपकी दी हुई आशीषों को देख सकूँ। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मेरा शुक्रगुज़ार होना केवल मेरे मिज़ाज पर निर्भर न हो, बल्कि यह मेरी आदत बन जाए। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.129": "दया के पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने जीवन पर और अपने हर एक कदम पर आपकी सुरक्षा माँगता हूँ। कृपया मुझे दिखने वाले खतरों और छिपे हुए फंदों से बचाकर रखिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; जहाँ मुझे जाना चाहिए वहाँ मुझे भेजें और जहाँ मुझे नहीं जाना चाहिए वहाँ मुझे रोक दें। मेरे हृदय को ऐसा रूप दीजिए कि मुझमें मसीह की छवि दिखाई दे। आमीन।",
  "p.130": "स्वर्गीय पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: यह दुनिया मुझे मेरी नाकामियों, मेरे काम या मेरे दुखों से पहचानने की कोशिश करती है। कृपया मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; आपकी सच्चाई हर झूठी पहचान से कहीं ज़्यादा ऊँची हो। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेरे रखिए और मुझे आशा से भर दीजिए। आमीन।",
  "p.131": "प्रभु यीशु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मेरे अंदर एक ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। कृपया इस दर्द में मेरे साथ बैठिए और चंगाई के लिए मुझ पर दबाव डाले बिना मुझे तसल्ली दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; मुझे प्यार भरी यादों के साथ सुध लेना और फिर भी एक नई आशा के साथ जीना सिखाइए। आपकी इच्छा ही मेरी शांति और आपकी मौजूदगी ही मेरी ताकत बन जाए। आमीन।",
  "p.132": "पवित्र आत्मा, मैं आज पूरी ईमानदारी से आपके सामने आता हूँ: मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। कृपया मुझे एक शुद्ध हृदय दीजिए, मुश्किलों से निकलने का रास्ता दिखाइए और जीवन को चुनने की सामर्थ्य दीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; मुझे ऐसा अनुग्रह दीजिए कि इसी पल मेरे लिए आपकी आज्ञा मानना मुमकिन हो जाए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और मुझमें इतनी हिम्मत भर दीजिए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.133": "दयालु परमेश्वर, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को पाने के लिए जल्दबाज़ी करने की कोशिश कर रहा हूँ जो अभी तैयार नहीं हैं। कृपया मुझे अपने समय पर भरोसा करना सिखाइए ताकि मेरे मन में कड़वाहट न आए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; इंतज़ार की इस घड़ी में मेरे भीतर एक शांत विश्वास पैदा कीजिए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.134": "दयालु पिता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं इस जीवन को बिना किसी उद्देश्य के यूँ ही नहीं बिताना चाहता। कृपया मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; वफ़ादारी के साथ किए गए मेरे छोटे-छोटे कामों को अपनी महिमा के लिए इस्तेमाल कीजिए। मेरे जीवन में वो काम कीजिए जो मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.135": "विश्वासयोग्य प्रभु, मैं आज पूरी सच्चाई के साथ आपके सामने आता हूँ: जैसे ही यह दिन खत्म हो रहा है, मैं उन सारी बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। कृपया मेरे मन को अपनी शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; आने वाली सुबह मुझे आपकी नई दया के साथ मिले। आज का मेरा पूरा जीवन आपकी एक शांत आराधना बन जाए। आमीन।",
  "p.136": "प्यारे उद्धारकर्ता, मैं आज पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने प्यार, अपने वादों और हर उस रिश्ते को आपके सामने रखता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे को अपनाना सिखाइए। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और शांति की राह पर ले चले। आमीन।",
  "p.137": "सर्वशक्तिमान परमेश्वर, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं इन बच्चों और नौजवानों को, जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। कृपया उनके मन की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें सही राह दिखाने वाले लोगों से घेर लीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; उन्हें आपको व्यक्तिगत रूप से और गहराई से जानने में मदद कीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.138": "शांति के राजकुमार, मैं आज सच्चाई के साथ आपके सामने आता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। कृपया हमें विनम्र, उदार, सच्चा और निडर बनाइए। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; हमारा जीवन इस दुनिया के सामने प्रभु यीशु की सुंदरता को प्रकट करे। जो बातें मैं समझता हूँ और जो नहीं समझता, उन सबके लिए मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.139": "दया के पिता, मैं आज पूरी ईमानदारी से आपके सामने आता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थका रहे हैं। कृपया मेरी उन जगहों पर नई आशा भर दीजिए जहाँ निराशा ने घर कर लिया है। मेरी यह प्रार्थना सिर्फ शब्दों तक ही न रहे; मेरा यह विश्वास मज़बूत कीजिए कि आप आज भी मेरे जीवन में कुछ अच्छा रच रहे हैं। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.140": "स्वर्गीय पिता, इस साधारण जीवन के बीच मुझसे मिलने के लिए आपका धन्यवाद। दुनिया की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। मेरी विनती है कि आप मेरे विचारों को सही दिशा दें, मेरी भावनाओं को सँभालें और जो भला है उसकी ओर मेरी अगुवाई करें। आपकी कृपा से, किसी भी परिस्थिति में मेरा पहला जवाब डर नहीं बल्कि विश्वास हो। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.141": "प्रभु यीशु, इस भागदौड़ भरे जीवन के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपसे विनती करता हूँ कि मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। अपनी कृपा से मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। जो मैं समझता हूँ और जो नहीं समझता, उन दोनों के लिए मैं आप पर भरोसा करता हूँ। आमीन।",
  "p.142": "पवित्र आत्मा, इस जीवन के संघर्षों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मैं आपसे विनती करता हूँ कि मुझे हर अगले कदम के लिए धीरज और हिम्मत दीजिए। अपनी दया से मुझे मज़बूत बनाइए, पर कठोर नहीं। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.143": "दयालु परमेश्वर, इस असल ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं वो दर्द आपके सामने लाता हूँ जिसे मैं मन ही मन बार-बार याद करता रहता हूँ। मुझे हर कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ माफ़ करना सिखाइए। अपनी कृपा से उस ज़ख्म को भर दीजिए जिसे माफ़ी तुरंत नहीं मिटा पाती। मुझे अपने वचन में मज़बूत कीजिए, अपनी करुणा से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.144": "हे दयालु पिता, रोज़मर्रा की ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। आज मैं अपने परिवार और उन लोगों को आपके सामने लाता हूँ जो मेरे दिल के सबसे करीब हैं। मैं आपसे विनती करता हूँ कि हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से भर दीजिए। अपने अनुग्रह से हमारी बातों में नम्रता और हमारे रिश्तों में मज़बूती दीजिए। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति मेरी ताकत बन जाए। आमीन।",
  "p.145": "हे विश्वासयोग्य प्रभु, जीवन की भागदौड़ के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने हाथों की मेहनत और कंधों के बोझ को आपके चरणों में रखता हूँ। प्रभु, बिना किसी दिखावे के पूरी लगन से सेवा करने में मेरी मदद कीजिए। आपका अनुग्रह मुझ पर हो ताकि मेरे लिए लोगों की वाह-वाही से ज़्यादा मेरी ईमानदारी मायने रखे। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी आज्ञा मानने की हिम्मत रखूँ। आमीन।",
  "p.146": "मेरे प्यारे उद्धारकर्ता, इस साधारण जीवन के बीच मुझसे मिलने के लिए धन्यवाद। मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। प्रभु, जो घायल है उसे छुएं, जो कमज़ोर है उसे बल दें और मेरी देखभाल करने वालों को बुद्धि दें। आपकी कृपा से, उत्तर मिलने से पहले ही मेरे अंदर आशा जाग उठे। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.147": "हे सर्वशक्तिमान परमेश्वर, वास्तविक जीवन की चुनौतियों के बीच मुझसे मिलने के लिए धन्यवाद। मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे सिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। अपने अनुग्रह से मुझे ऐसे फैसलों से बचाइए जो सिर्फ डर या घमंड में लिए गए हों। प्रभु, वो काम मेरे जीवन में कीजिए जो मैं खुद नहीं कर सकता। आमीन।",
  "p.148": "हे शांति के राजकुमार, जीवन की हलचल के बीच मुझसे मिलने के लिए धन्यवाद। मैं कुछ पल रुककर आपकी उन रहमतों को देखना चाहता हूँ जिन्हें मैं अक्सर अनदेखा कर देता हूँ। प्रभु, मेरी आँखें खोलिए ताकि मैं रोज़ के साधारण पलों में छिपी आपकी आशीषों को देख सकूँ। आपकी कृपा से, धन्यवाद करना मेरी आदत बन जाए, न कि सिर्फ एक एहसास। आज मेरा जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.149": "हे दया के पिता, मेरी भागदौड़ भरी ज़िंदगी में मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने जीवन और आज के हर कदम पर आपकी सुरक्षा माँगता हूँ। मुझे सामने दिखने वाले खतरों और गुप्त फंदों से बचाइए। अपने अनुग्रह से मुझे वहीं ले जाइए जहाँ मुझे जाना चाहिए और वहाँ रोक लीजिए जहाँ मुझे नहीं जाना चाहिए। आपकी कृपा मेरी हर कमज़ोरी में मेरा सहारा बने और मुझे शांति की राह पर ले चले। आमीन।",
  "p.150": "हे स्वर्गीय पिता, इस जीवन के उतार-चढ़ाव में मुझसे मिलने के लिए धन्यवाद। यह दुनिया अक्सर मुझे मेरी नाकामियों और तकलीफों से पहचानना चाहती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। प्रभु, आपका सच हर झूठी बातों से कहीं ऊँचा सुनाई दे। मुझे धीरे चलना, गहरा प्रेम करना और आप पर पूरा भरोसा करना सिखाइए। आमीन।",
  "p.151": "हे प्रभु यीशु, मेरे इस कठिन जीवन के बीच मुझसे मिलने के लिए धन्यवाद। मेरे दिल में ऐसा दुख है जिसे शब्दों में बयान करना मुश्किल है। प्रभु, इस दर्द में मेरे साथ बैठिए और मेरे घावों को भरने में जल्दबाजी न करके मुझे सुकून दीजिए। अपनी कृपा से मुझे यादों को संजोना और फिर भी उम्मीद के साथ जीना सिखाइए। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.152": "हे पवित्र आत्मा, मेरी कमज़ोरियों के बीच मुझसे मिलने के लिए आपका धन्यवाद। जब मैं उन चीज़ों की ओर खिंचता हूँ जो मेरी आत्मा को कमज़ोर करती हैं, तो मुझे एक शुद्ध मन और उनसे बचने का रास्ता दीजिए। मुझे जीवन को चुनने की शक्ति दीजिए। अपने अनुग्रह से आज्ञा मानना मेरे लिए मुमकिन बनाइए। मेरे हृदय को ऐसा रूप दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.153": "हे कृपालु परमेश्वर, जीवन के इस सफ़र में मुझसे मिलने के लिए धन्यवाद। मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करने की कोशिश करता हूँ जिनका समय अभी नहीं आया है। मुझे अपने समय पर भरोसा करना सिखाइए ताकि मैं कड़वाहट से भर न जाऊँ। इस देरी के समय में मेरा विश्वास मज़बूत कीजिए। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.154": "हे दयालु पिता, रोज़मर्रा की ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं इस जीवन को यूँ ही सोए हुए या बिना किसी मकसद के नहीं गुज़ारना चाहता। मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। आपकी कृपा से, मेरी छोटी-छोटी वफादारियाँ अनंत काल के लिए मायने रखें। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति मेरी ताकत बन जाए। आमीन।",
  "p.155": "हे विश्वासयोग्य प्रभु, इस दिन के अंत में मुझसे मिलने के लिए आपका धन्यवाद। अब जबकि यह दिन बीत रहा है, मैं उन सब बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं ठीक नहीं कर सकता। सोते समय मेरे मन को शांति दीजिए और मेरे हृदय को सुरक्षित रखिए। आपकी कृपा से, कल सुबह मुझ पर आपकी नई करुणा हो। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी आज्ञा मानने की हिम्मत रखूँ। आमीन।",
  "p.156": "प्यारे उद्धारकर्ता, असल ज़िंदगी के उतार-चढ़ाव के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने प्रेम, अपनी प्रतिबद्धताओं और उन सभी रिश्तों को आपके हाथों में सौंपता हूँ जिन्हें आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। अपने अनुग्रह से हमें एक-दूसरे की बात सुनना, माफ करना और फिर से एक-दूसरे का साथ चुनना सिखाइए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.157": "सर्वशक्तिमान परमेश्वर, इस साधारण जीवन के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी वफ़ादार सुरक्षा में सौंपता हूँ। उनके मनों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें समझदार लोगों का साथ दीजिए। अपने अनुग्रह से उन्हें ऐसा मन दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। जो मैं अपने आप से नहीं कर सकता, वह आप मेरे जीवन में पूरा कीजिए। आमीन।",
  "p.158": "शांति के राजकुमार, रोज़मर्रा के जीवन के बीच मेरे करीब आने के लिए धन्यवाद। अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को फिर से नया कर दीजिए। हमें नम्र, उदार, सच्चा और साहसी बनाइए। आपकी कृपा हम पर हो, ताकि हमारा जीवन इस दुनिया के सामने प्रभु यीशु की सुंदरता को ज़ाहिर कर सके। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.159": "दयालु पिता, इस भागदौड़ भरी ज़िंदगी के बीच मेरा साथ देने के लिए धन्यवाद, जहाँ कई बार वादे बहुत दूर और सपने थके हुए से लगते हैं। जहाँ निराशा ने घर कर लिया है, वहाँ अपनी आशा की नई फूँक भर दीजिए। अपने अनुग्रह से मुझे यह भरोसा दिलाइए कि आप अब भी मेरे जीवन की कहानी के अच्छे अध्याय लिख रहे हैं। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.160": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: इससे पहले कि मैं दुनिया की उम्मीदों के नीचे दब जाऊँ, मैं अपना यह दिन आपके हाथों में रखता हूँ। मेरे पास रहिए, मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और जो भला है उसकी ओर मेरी अगुवाई कीजिए। मेरे सोच-विचार और फैसलों से यह ज़ाहिर हो कि मेरी पहली प्रतिक्रिया डर नहीं बल्कि आप पर विश्वास है। जो मैं अपने दम पर नहीं कर सकता, वह आप मुझमें पूरा कीजिए। आमीन।",
  "p.161": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे करीब आइए, मेरे अंदर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति किसी भी घबराहट से कहीं बड़ी है। मेरे हृदय को आपकी शांति में सुकून पाना सिखाइए। आज मेरा जीवन आपकी आराधना में एक पवित्र और शांत भेंट बन जाए। आमीन।",
  "p.162": "पवित्र आत्मा, मैं यह ज़रूरत आपको सौंपता हूँ: आगे का रास्ता मेरी सोच से कहीं ज़्यादा भारी लग रहा है। मेरे पास रहिए, मुझे अगला वफ़ादारी का कदम उठाने का धीरज दीजिए और उसके बाद वाले कदम के लिए हिम्मत। मुझे मज़बूत बनाइए पर मेरे दिल को कठोर न होने दीजिए। आपका अनुग्रह मेरी हर कमज़ोरी में मुझे सहारा दे और मुझे शांति की राह दिखाए। आमीन।",
  "p.163": "दयालु परमेश्वर, मैं इस ज़रूरत को आपके सामने लाता हूँ: मैं वह दर्द आपको सौंपता हूँ जिसे मैं मन ही मन बार-बार दोहराता रहता हूँ। मेरे करीब आइए, मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ माफ करना सिखाइए। उन घावों को भर दीजिए जो माफी के बाद भी रह गए हैं। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.164": "दयालु पिता, मैं इस ज़रूरत को आपको सौंपता हूँ: मैं अपने परिवार और उन लोगों को जो मेरे दिल के सबसे करीब हैं, आपके सामने लाता हूँ। हमारे घर को सब्र, ईमानदारी, सुरक्षा और प्रेम से ढँक लीजिए। हमारी बातों में कोमलता हो और हमारे रिश्ते मज़बूत बने रहें। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सबके लिए मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.165": "वफ़ादार प्रभु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने हाथों की मेहनत और अपनी ज़िम्मेदारियों का बोझ आपके चरणों में रखता हूँ। मेरे पास रहिए, ताकि मैं सफलता के पीछे भागने के बजाय पूरे दिल से बेहतरीन काम कर सकूँ। दुनिया की वाह-वाही से ज़्यादा मेरी ईमानदारी और सच्चाई मायने रखे। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.166": "प्यारे उद्धारकर्ता, मैं यह ज़रूरत आपको सौंपता हूँ: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरे करीब आइए, मेरे ज़ख्मों को छुइए, मेरी कमज़ोरी को ताकत दीजिए और इलाज करने वालों को बुद्धि दीजिए। प्रार्थना का उत्तर मिलने से पहले ही मेरे मन में उम्मीद जगा दीजिए। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.167": "सर्वशक्तिमान परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। मेरे पास रहकर मुझे दिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मुझे ऐसे फैसलों से बचाइए जो सिर्फ डर या घमंड में लिए गए हों। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.168": "शांति के राजकुमार, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन दयाओं पर ध्यान देने के लिए रुकता हूँ जिन्हें मैं अक्सर भाग-दौड़ में अनदेखा कर देता हूँ। मेरे करीब रहिए और मेरी आँखों को उन आशीषों के लिए खोल दीजिए जो रोज़मर्रा के साधारण पलों में छिपी रहती हैं। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि धन्यवाद करना मेरा स्वभाव बन गया है, न कि केवल एक पल की भावना। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और इतना साहस दीजिए कि उसका पालन कर सकूँ। आमीन।",
  "p.169": "दयालु पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने जीवन और आज के मेरे हर कदम पर आपकी सुरक्षा और साया माँगता हूँ। मेरे करीब रहिए और हर दिखने वाले खतरे और छिपे हुए फंदों से मेरी रक्षा कीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि आप ही मुझे सही राह पर ले जाते हैं और गलत रास्तों से रोकते हैं। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.170": "स्वर्गीय पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: यह दुनिया मुझे मेरी नाकामियों, मेरे कामों या मेरे दुखों से पहचानने की कोशिश करती रहती है। मेरे करीब रहिए और मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि आपका सत्य हर झूठी पहचान से कहीं ज़्यादा सामर्थी है। मुझमें वो काम कीजिए जो मैं अपने आप नहीं कर सकता। आमीन।",
  "p.171": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरे भीतर ऐसा दुख है जिसे शब्द पूरी तरह बयां नहीं कर सकते। मेरे करीब रहिए, मेरे इस दर्द में मेरे साथ बैठिए और मुझे तसल्ली दीजिए, मेरे घावों को भरने में जल्दबाज़ी न कीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मैं प्यार के साथ बीती बातों को याद करना और फिर भी आशा के साथ जीना सीख सकूँ। आज मेरा पूरा दिन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.172": "पवित्र आत्मा, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन चीज़ों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मेरे करीब रहिए और मुझे एक शुद्ध मन, बुराई से बचने का रास्ता और जीवन को चुनने की ताकत दीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि आपकी आज्ञा मानना इसी पल मुमकिन है। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.173": "दयालु परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़ोर लगाने की कोशिश करता हूँ जो अभी तैयार नहीं हैं। मेरे करीब रहिए और मुझे चिड़चिड़े हुए बिना आपके सही समय पर भरोसा करना सिखाइए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि इस देरी के बीच भी मेरा विश्वास बढ़ता जा रहा है। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.174": "दयालु पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं इस जीवन को बिना किसी मकसद के बस यूँ ही नहीं बिताना चाहता। मेरे करीब रहिए और मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मेरी छोटी-सी वफादारी भी आपके राज्य के लिए बहुत मायने रखती है। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जो मैं समझता हूँ, और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.175": "विश्वासयोग्य प्रभु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: इस दिन के अंत में, मैं उन सब बातों को छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मेरे करीब रहिए, मेरे मन को शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि आने वाला कल मेरे लिए आपकी नई दया लेकर आए। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के स्वभाव को झलका सके। आमीन।",
  "p.176": "प्यारे उद्धारकर्ता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके पास लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। मेरे करीब रहिए और जहाँ तनाव के कारण कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि हम एक-दूसरे की सुनना, माफ करना और बार-बार एक-दूसरे का साथ चुनना सीखें। मुझे अपने वचन में जड़ पकड़ने दीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.177": "सर्वशक्तिमान परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन बच्चों और नौजवानों को आपकी देखरेख में सौंपता हूँ जिनसे मैं प्रेम करता हूँ। मेरे करीब रहिए, उनके मन की रक्षा कीजिए, उनके सही फैसलों में मदद कीजिए और उन्हें नेक लोगों की संगति में रखिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि वे आपको व्यक्तिगत रूप से और गहराई से जान पाएँ। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.178": "शांति के राजकुमार, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को ताज़ा कीजिए। मेरे करीब रहिए और हमें विनम्र, उदार, सच्चा और निडर बनाइए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और इतना साहस दीजिए कि उसका पालन कर सकूँ। आमीन।",
  "p.179": "दयालु पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: कुछ वादे अब बहुत दूर लगते हैं और कुछ सपने मानो टूट रहे हैं। मेरे करीब रहिए और जहाँ निराशा ने घर कर लिया है, वहाँ फिर से आशा की फूँक भर दीजिए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मुझे यह यकीन है कि आप अब भी मेरे जीवन की एक सुंदर कहानी लिख रहे हैं। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.180": "स्वर्गीय पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। किसी और की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मेरे विचारों को सही दिशा देते हैं, मेरी भावनाओं को सँभालते हैं और मुझे भलाई की राह पर ले चलते हैं। आज, डर के बजाय मेरा पहला जवाब विश्वास हो। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.181": "प्रभु यीशु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपकी मदद स्वीकार करता हूँ क्योंकि आप मेरे भीतर के शोर को शांत करते हैं और मुझे याद दिलाते हैं कि आपकी मौजूदगी मेरी घबराहट से कहीं ज़्यादा मज़बूत है। आज, मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और मुझमें आपकी आज्ञा मानने की हिम्मत हो। आमीन।",
  "p.182": "पवित्र आत्मा, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। आगे का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे विश्वास का अगला कदम बढ़ाने की हिम्मत और उसके आगे के लिए हौसला देते हैं। आज, मुझे मज़बूत बनाइए पर मेरे दिल को कठोर न होने दीजिए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.183": "दयालु परमेश्वर, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं वह पुरानी चोट आपके पास लाता हूँ जिसे मैं अपने मन में बार-बार दोहराता रहता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे कड़वाहट से आज़ाद करते हैं और मुझे समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाते हैं। आज, उस दर्द को भर दीजिए जो केवल माफ़ कर देने से तुरंत नहीं मिटता। जो मैं खुद में नहीं कर सकता, वह आप मेरे अंदर पूरा कीजिए। आमीन।",
  "p.184": "दयालु पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं अपने परिवार और अपने प्रियजनों को आपके सामने लाता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से सँभालते हैं। आज, हमारे बोल मीठे हों और हमारे रिश्ते मज़बूत हों। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.185": "विश्वासयोग्य प्रभु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं अपने हाथों की मेहनत और अपने कंधों का बोझ आपको सौंपता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे सफलता को पूजने के बजाय पूरी लगन से सेवा करना सिखाते हैं। आज, दुनिया की वाह-वाही से ज़्यादा मेरी सच्चाई और ईमानदारी मायने रखे। हर कमज़ोरी में मुझे आपका अनुग्रह मिले और आप मुझे शांति की राह पर ले चलें। आमीन।",
  "p.186": "प्यारे उद्धारकर्ता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मेरे घावों को छूते हैं, कमज़ोरी में बल देते हैं और सेवा करने वालों को बुद्धि देते हैं। आज, जवाब मिलने से पहले ही मेरे अंदर उम्मीद जगा दीजिए। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.187": "सर्वशक्तिमान परमेश्वर, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मुझे केवल जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे सही चुनाव करना और ज़रूरत पड़ने पर इंतज़ार करना सिखाते हैं। आज, मुझे डर या घमंड में आकर फैसले लेने से बचाइए। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.188": "शांति के राजकुमार, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं उन आशीषों को देखने के लिए रुकता हूँ जिन्हें मैं अक्सर भाग-दौड़ में अनदेखा कर देता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप साधारण पलों में छिपी आशीषों के लिए मेरी आँखें खोलते हैं। आज, धन्यवाद करना मेरा स्वभाव बन जाए, केवल एक भावना नहीं। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के हृदय की झलक दे सके। आमीन।",
  "p.189": "दया के पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मैं अपने जीवन और अपने हर कदम पर आपका साया माँगता हूँ। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाते हैं। आज, मुझे वहीं भेजिए जहाँ मुझे जाना चाहिए और मुझे वहाँ जाने से रोक लीजिए जहाँ मेरा जाना ठीक नहीं है। मुझे अपने वचन में थामे रखिए, अपनी करुणा से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.190": "स्वर्गीय पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। यह दुनिया मुझे मेरी नाकामियों और काम के आधार पर पहचानने की कोशिश करती है, पर मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे याद दिलाते हैं कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आज, आपकी सच्चाई हर झूठी पहचान से ज़्यादा ऊँची सुनाई दे। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.191": "प्रभु यीशु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं। मेरे भीतर एक ऐसा दुख है जिसे शब्द पूरी तरह बयाँ नहीं कर सकते। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप इस दर्द में मेरे साथ बैठते हैं और चंगाई में जल्दबाजी किए बिना मुझे दिलासा देते हैं। आज, मुझे प्यार के साथ यादें सँजोना और उम्मीद के साथ जीना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और मुझमें आपकी आज्ञा मानने की हिम्मत हो। आमीन।",
  "p.192": "पवित्र आत्मा, आप देख रहे हैं कि मैं अपने दिल पर क्या बोझ लेकर चल रहा हूँ और आप जानते हैं कि यह मेरे लिए क्यों मायने रखता है। मैं उस खिंचाव को महसूस कर रहा हूँ जो मेरी रूह को कमज़ोर करता है। मैं आपकी सहायता स्वीकार करता हूँ क्योंकि आप मुझे एक शुद्ध मन, परीक्षा से बचने का रास्ता और जीवन को चुनने का बल देते हैं। आज, इसी घड़ी में, मेरी मदद कीजिए कि मैं आपकी आज्ञा मानना मुमकिन समझूँ। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.193": "अनुग्रहकारी परमेश्वर, आप देख रहे हैं कि मैं क्या बोझ उठा रहा हूँ और आप इसकी अहमियत जानते हैं। मैं इंतज़ार करते-करते थक गया हूँ और मेरा मन उन बातों के लिए ज़बरदस्ती करने को ललचाता है जो अभी तैयार नहीं हैं। मैं आपकी मदद माँगता हूँ; मुझे आप पर और आपके सही समय पर भरोसा करना सिखाइए ताकि मैं निराश या कड़वाहट से न भरूँ। आज इस इंतज़ार के बीच मुझमें एक शांत विश्वास जगाइए। मेरे भीतर वो काम कीजिए जो मैं खुद नहीं कर सकता। आमीन।",
  "p.194": "दयालु पिता, आप जानते हैं कि मैं किन हालातों से गुज़र रहा हूँ और आप समझते हैं कि ये मेरे लिए क्यों ज़रूरी हैं। मैं इस ज़िंदगी को बस यूँ ही अधूरी चेतना में नहीं बिताना चाहता। मैं आपकी सहायता स्वीकार करता हूँ; मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। आज, वफादारी के मेरे इन छोटे-छोटे कामों को अनंत काल के लिए फलदायी बनाइए। आज मेरा जीवन आपकी इबादत के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.195": "विश्वासयोग्य प्रभु, आप जानते हैं कि मैं क्या बोझ लेकर चल रहा हूँ। आज का दिन खत्म होते समय, मैं उन बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मैं आपकी मदद माँगता हूँ कि आप मेरे मन को अपनी शांति से धो दें और सोते समय मेरे दिल को महफूज़ रखें। आज दुआ करता हूँ कि कल सुबह मुझे आपकी नई करुणा मिले। आपका अनुग्रह मेरी हर कमज़ोरी में मेरा सहारा बने और मुझे शांति की राह पर ले चले। आमीन।",
  "p.196": "प्यारे उद्धारकर्ता, आप देख रहे हैं कि मैं किन परिस्थितियों से गुज़र रहा हूँ। मैं अपने प्रेम, अपनी प्रतिबद्धताओं और उन सभी रिश्तों को आपके पास लाता हूँ जिन्हें आपके स्पर्श की ज़रूरत है। मैं आपकी सहायता माँगता हूँ; जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। आज हमें एक-दूसरे की बात सुनना, माफ़ करना और फिर से एक-दूसरे को अपनाना सिखाइए। मुझे धीरज से चलना, गहराई से प्रेम करना और आप पर पूरा भरोसा करना सिखाइए। आमीन।",
  "p.197": "सर्वशक्तिमान परमेश्वर, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ। मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। मैं आपकी सहायता माँगता हूँ कि आप उनके मनों की रक्षा करें, उनके फैसलों में अगुवाई करें और उन्हें समझदार लोगों का साथ दें। आज उन्हें यह अनुग्रह दीजिए कि वे आपको व्यक्तिगत और गहरे रूप से जान सकें। जो बातें मैं समझता हूँ और जो नहीं समझ पाता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.198": "शांति के राजकुमार, आप देख रहे हैं कि आज मैं किन बातों को लेकर बोझिल हूँ। अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। मैं आपकी मदद माँगता हूँ कि आप हमें नम्र, उदार, सच्चा और निडर बनाएँ। आज हमारा जीवन ऐसा हो कि यह दुनिया हम में प्रभु यीशु की सुंदरता को देख सके। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के हृदय की झलक बन जाए। आमीन।",
  "p.199": "दया के पिता, आप देख रहे हैं कि मैं क्या सह रहा हूँ और यह मेरे लिए क्यों मायने रखता है। कभी-कभी आपके वादे बहुत दूर लगते हैं और कुछ सपने थके हुए से महसूस होते हैं। मैं आपकी सहायता माँगता हूँ; जहाँ निराशा ने घर कर लिया है, वहाँ फिर से उम्मीद की साँस भर दीजिए। आज मुझे यह विश्वास दिलाइए कि आप अब भी मेरे जीवन की कहानी में अच्छे अध्याय लिख रहे हैं। मुझे अपने वचन में मज़बूत कीजिए, अपनी करुणा से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.200": "स्वर्गीय पिता, इससे पहले कि मैं आज के दिन को लोगों की उम्मीदों के हवाले करूँ, मैं इसे आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मुझे भलाई की राह पर ले चलिए। डरने के बजाय मेरा पहला कदम विश्वास का हो। जो बातें मैं समझता हूँ और जो नहीं समझ पाता, उन दोनों में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.201": "प्रभु यीशु, मेरा मन ऐसी चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी मेरी हर घबराहट से कहीं ज़्यादा बड़ी है। मेरे दिल को आपकी शांति में साँस लेना सिखाइए। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह के स्वभाव की झलक दिखे। आमीन।",
  "p.202": "पवित्र आत्मा, मेरे सामने की राह मेरी उम्मीद से कहीं ज़्यादा कठिन है। मुझे अगला वफादारी भरा कदम उठाने का धीरज दीजिए और उसके बाद के कदम के लिए साहस। मुझे मज़बूत बनाइए पर मेरे दिल को कठोर मत होने दीजिए। मुझे अपने वचन की नींव पर मज़बूती से खड़ा कीजिए, अपनी दया से ढँक लीजिए और आशा से सराबोर कर दीजिए। आमीन।",
  "p.203": "अनुग्रहकारी परमेश्वर, मैं वो चोट आपके पास लाया हूँ जिसे मैं बार-बार अकेले में याद करता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। उन ज़ख्मों को भर दीजिए जिन्हें सिर्फ माफ़ी तुरंत नहीं मिटा पाती। आपकी इच्छा मेरी शांति बन जाए और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.204": "दयालु पिता, मैं अपने परिवार और उन लोगों को जो मेरे दिल के सबसे करीब हैं, आपके चरणों में लाता हूँ। हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से सँभाल लीजिए। हमारी बातों में कोमलता और हमारे रिश्तों में मज़बूती भर दीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ, और मुझे इतना साहस दीजिए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.205": "विश्वासयोग्य प्रभु, मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको सौंपता हूँ। सफलता को खुदा बनाने के बजाय, अपना काम पूरी लगन से करने में मेरी मदद कीजिए। मेरे लिए लोगों की वाह-वाही से बढ़कर आपकी सच्चाई मायने रखे। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.206": "प्रेमी उद्धारकर्ता, मैं अपने शरीर, मन और प्राण की उन कमज़ोरियों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जहाँ चोट है उसे छू लीजिए, जो कमज़ोर है उसे बल दीजिए और मेरी देखभाल करने वालों को बुद्धि दीजिए। प्रार्थना का उत्तर मिलने से पहले ही मेरे अंदर एक नई उम्मीद जगा दीजिए। जो मैं अपने आप से नहीं कर सकता, वह आप मेरे जीवन में कर दीजिए। आमीन।",
  "p.207": "सर्वशक्तिमान परमेश्वर, मुझे केवल जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे राह दिखाइए कि क्या चुनना है, किसे मना करना है और कब रुकना है। मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाइए। आज मेरा पूरा जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.208": "शांति के राजकुमार, मैं उन आशीषों को देखने के लिए ठहरता हूँ जिन्हें अक्सर भागदौड़ में भूल जाता हूँ। मेरी आँखें खोल दीजिए ताकि मैं मामूली पलों में छिपे आपके वरदानों को देख सकूँ। शुक्रगुज़ारी मेरा स्वभाव बन जाए। आपकी कृपा मेरी हर कमज़ोरी में मुझे थामे रखे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.209": "दया के पिता, मैं अपने जीवन और आज के हर कदम पर आपका साया माँगता हूँ। मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाकर रखिए। जहाँ मुझे जाना चाहिए, वहीं मुझे ले चलिए और जहाँ नहीं जाना चाहिए, वहाँ मुझे रोक लीजिए। मुझे धीरज से चलना, दिल खोलकर प्यार करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.210": "स्वर्गीय पिता, यह दुनिया बार-बार मुझे मेरी नाकामियों और दुखों से पहचानने की कोशिश करती है। मुझे याद दिलाते रहिए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपका सत्य हर उस झूठी बात से बड़ा हो जो मेरे बारे में कही जाती है। मैं उन बातों में भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनमें भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.211": "प्रभु यीशु, मेरे भीतर ऐसा दुख है जिसे बयाँ करने के लिए शब्द कम पड़ रहे हैं। इस दर्द में मेरे साथ बैठिए और मुझे तसल्ली दीजिए, चंगा करने में कोई जल्दबाज़ी न कीजिए। मुझे प्यार से याद करना और फिर भी उम्मीद के साथ जीना सिखाइए। मेरे हृदय को ऐसा रूप दीजिए कि मुझमें आपकी छवि दिखाई दे। आमीन।",
  "p.212": "पवित्र आत्मा, मैं उन खिंचावों को महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करते हैं। मुझे एक शुद्ध मन दीजिए, बुराई से बचने का रास्ता और सही जीवन चुनने का बल दीजिए। इस घड़ी में मेरे लिए आपकी इच्छा पूरी करना मुमकिन कर दीजिए। मुझे अपने वचनों में दृढ़ कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.213": "अनुग्रहकारी परमेश्वर, मैं इंतज़ार करते-करते थक गया हूँ और उन बातों के लिए ज़बरदस्ती करने लगा हूँ जिनका समय अभी नहीं आया। मुझे बिना किसी कड़वाहट के आपके सही समय पर भरोसा करना सिखाइए। इस इंतज़ार में मेरा विश्वास बढ़ता जाए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.214": "दयालु पिता, मैं इस जीवन को यूँ ही नींद में नहीं गुज़ारना चाहता। मुझे वह भलाई के काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। मेरी वफ़ादारी के छोटे-छोटे कामों का गहरा असर होने पाए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ, और मुझे इतना साहस दीजिए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.215": "विश्वासयोग्य प्रभु, आज के दिन के अंत में, मैं उन सब बातों को छोड़ता हूँ जिन्हें मैं ठीक नहीं कर सकता। मेरे मन को शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। आने वाला कल मेरे लिए नई दया लेकर आए। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.216": "प्यारे उद्धारकर्ता, मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हम एक-दूसरे के प्रति कठोर हो गए हैं, वहाँ फिर से वही कोमलता भर दीजिए। हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे का साथ निभाना सिखाइए। जो मैं अपने आप से नहीं कर सकता, वह आप मेरे जीवन में पूरा कीजिए। आमीन।",
  "p.217": "सर्वशक्तिमान परमेश्वर, मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। उनके मन की रक्षा कीजिए, उनके फ़ैसलों में उनकी अगुवाई कीजिए और उन्हें सही सलाह देने वाले लोगों के बीच रखिए। उन्हें ऐसी कृपा दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.218": "शांति के राजकुमार, अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। हमें विनम्र, उदार, सच्चा और साहसी बनाइए। हमारा जीवन ऐसा हो कि यह दुनिया हमारे ज़रिए प्रभु यीशु की सुंदरता को देख सके। आपकी अनुग्रह भरी मदद मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.219": "दयालु पिता, कभी-कभी आपके वादे बहुत दूर लगते हैं और सपने थके हुए से महसूस होते हैं। जहाँ निराशा घर कर गई है, वहाँ फिर से उम्मीद की नई फूँक भर दीजिए। मुझ पर कृपा कीजिए ताकि मैं विश्वास रखूँ कि आप अब भी मेरे जीवन की एक सुंदर कहानी लिख रहे हैं। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.220": "स्वर्गीय पिता, आज मैं पूरी ईमानदारी के साथ आपके सामने आता हूँ: इससे पहले कि मैं दुनिया की उम्मीदों के नीचे दबूँ, मैं अपना यह दिन आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और जो भला है उसकी ओर मेरी अगुवाई कीजिए। यह प्रार्थना सिर्फ शब्दों तक ही न रहे; मेरी हर बात में डर की जगह विश्वास पहले दिखाई दे। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.221": "प्रभु यीशु, मैं सच्चे मन से आपके सामने आता हूँ: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेला नहीं सुलझा सकता। मेरे भीतर के इस शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी मेरी किसी भी घबराहट से कहीं बड़ी है। मेरी यह प्रार्थना सिर्फ़ बोल भर न रहे, बल्कि मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। आपकी अनुग्रह मेरी हर कमज़ोरी में मुझे थाम ले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.222": "पवित्र आत्मा, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मेरे आगे का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मुझे हर अगला कदम बढ़ाने की ताकत दीजिए और उसके बाद के लिए हिम्मत। यह प्रार्थना मेरे जीवन का हिस्सा बन जाए; मुझे मज़बूत बनाइए पर मेरे दिल को कठोर मत होने दीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.223": "दयालु परमेश्वर, मैं आज बड़ी ईमानदारी से आपके पास आता हूँ: मैं वो दर्द आपके पास लाया हूँ जिसे मैं बार-बार याद करता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाइए। यह प्रार्थना सिर्फ़ शब्दों तक न रहे; उन घावों को भी भर दीजिए जो माफ़ करने के तुरंत बाद नहीं भरते। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.224": "दयालु पिता, मैं आज पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने परिवार और अपने दिल के करीब रहने वाले लोगों को आपके आगे रखता हूँ। हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाल लीजिए। यह प्रार्थना हमारे जीवन में सच हो जाए; हमारी बातें मधुर हों और हमारे रिश्ते मज़बूत बनें। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.225": "विश्वासयोग्य प्रभु, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपके चरणों में रखता हूँ। मुझे ऐसी कृपा दीजिए कि मैं सफलता का लालच किए बिना अपनी ज़िम्मेदारियों को पूरी खूबी से निभा सकूँ। यह प्रार्थना मेरी रूह में बस जाए; मेरे लिए लोगों की वाह-वाही से ज़्यादा मेरा ईमान मायने रखे। मुझे अपने वचन की गहराई में थामे रखिए, अपनी दया से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.226": "प्यारे उद्धारकर्ता, मैं आज पूरी सच्चाई के साथ आपके पास आता हूँ: मैं अपने शरीर, मन और प्राण की हर उस जगह को आपके पास लाता हूँ जिसे चंगाई की ज़रूरत है। जो घायल है उसे छू लीजिए, जो कमज़ोर है उसे बल दीजिए और मेरा इलाज करने वालों को बुद्धि दीजिए। यह प्रार्थना सिर्फ़ शब्द न रह जाए; प्रार्थना का जवाब दिखने से पहले ही मेरे अंदर नई उम्मीद जगा दीजिए। आपकी मर्ज़ी मेरी शांति बन जाए और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.227": "सर्वशक्तिमान परमेश्वर, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मुझे सिर्फ़ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे राह दिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। यह प्रार्थना मेरे जीवन का आधार बन जाए; मुझे ऐसे फ़ैसलों से बचाइए जो सिर्फ़ डर या घमंड में लिए गए हों। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और इतना साहस दीजिए कि उसका पालन कर सकूँ। आमीन।",
  "p.228": "शांति के राजकुमार, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं उन रहमतों को देखने के लिए रुकता हूँ जिन्हें मैं अक्सर जल्दबाजी में अनदेखा कर देता हूँ। कृपया मेरी आँखें खोलें ताकि मैं रोज़मर्रा के पलों में छिपी आपकी आशीषों को देख सकूँ। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; धन्यवाद करना मेरा स्वभाव बन जाए, महज़ एक एहसास नहीं। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाएँ जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.229": "दया के पिता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं अपने जीवन और आज के अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। कृपया मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाए रखें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; मुझे वहाँ ले जाएँ जहाँ मुझे जाना चाहिए और मुझे वहाँ रोक लें जहाँ मुझे नहीं जाना चाहिए। जो मैं अपने दम पर नहीं कर सकता, वह आप मेरे जीवन में पूरा करें। आमीन।",
  "p.230": "स्वर्गीय पिता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: यह दुनिया मुझे मेरी असफलताओं, मेरे काम या मेरे दुखों से पहचानने की कोशिश करती है। कृपया मुझे याद दिलाएँ कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; आपका सत्य हर झूठी पहचान से कहीं ऊँचा सुनाई दे। मेरा आज का जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.231": "प्रभु यीशु, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मेरे भीतर ऐसा दुख है जिसे शब्द पूरी तरह बयाँ नहीं कर सकते। कृपया इस पीड़ा के बीच मेरे साथ बैठें और बिना किसी जल्दबाजी के मेरे ज़ख्मों को सुकून दें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; मुझे प्यार भरी यादों के साथ और उम्मीद के सहारे जीना सिखाएँ। आपकी कृपा मेरी हर कमज़ोरी में मुझे सहारा दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.232": "पवित्र आत्मा, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं उन बातों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। कृपया मुझे एक शुद्ध हृदय, बुराई से बचने का रास्ता और जीवन को चुनने की ताकत दें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; इस घड़ी में आपकी आज्ञा मानना मेरे लिए मुमकिन बना दें। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाएँ। आमीन।",
  "p.233": "अनुग्रहकारी परमेश्वर, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करने की कोशिश कर रहा हूँ जिनका समय अभी नहीं आया है। कृपया मुझे आप पर और आपके समय पर भरोसा करना सिखाएँ, ताकि मैं उदास या कड़वाहट से न भर जाऊँ। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; इंतज़ार के इन पलों में मेरा विश्वास और गहरा हो। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.234": "दयालु पिता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं इस जीवन को यूँ ही सोते-जागते नहीं बिताना चाहता। कृपया मुझे वह भलाई के काम दिखाएँ जो आपने आज मेरे लिए तैयार किए हैं। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; वफादारी के मेरे छोटे-छोटे काम अनंत काल के लिए मायने रखें। मेरे हृदय को ऐसा रूप दें कि वह मसीह के हृदय की झलक बन जाए। आमीन।",
  "p.235": "विश्वासयोग्य प्रभु, मैं आज सच्चाई के साथ आपके सामने आता हूँ: इस दिन के अंत में, मैं उन बातों को आपके हाथों में छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। कृपया मेरे मन को शांति से भर दें और सोते समय मेरे हृदय की रक्षा करें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; आने वाली सुबह मुझे आपकी नई दया के साथ मिले। मुझे अपने वचनों में थामे रखें, अपनी करुणा से घेरे रखें और उम्मीद से भर दें। आमीन।",
  "p.236": "प्यारे उद्धारकर्ता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; हमें एक-दूसरे को सुनना, माफ करना और बार-बार एक-दूसरे को अपनाना सिखाएँ। आपकी इच्छा ही मेरी शांति और आपकी उपस्थिति ही मेरी ताकत बन जाए। आमीन।",
  "p.237": "सर्वशक्तिमान परमेश्वर, मैं आज सच्चाई के साथ आपके सामने आता हूँ: मैं अपने प्रिय बच्चों और नौजवानों को आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। कृपया उनके दिलों की रक्षा करें, उनके फैसलों में उनका मार्गदर्शन करें और उन्हें नेक लोगों की संगति दें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; उन्हें आपकी व्यक्तिगत और गहरी पहचान पाने में मदद करें। मुझे अपने इतना करीब रखें कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाएँ कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.238": "शांति के राजकुमार, मैं आज सच्चाई के साथ आपके सामने आता हूँ: अपने लोगों को आशीष दें और एक-दूसरे के लिए हमारे प्रेम को नया कर दें। कृपया हमें विनम्र, उदार, सच्चा और निडर बनाएँ। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाएँ जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.239": "दया के पिता, मैं आज सच्चाई के साथ आपके सामने आता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थके हुए से लगते हैं। जहाँ मायूसी ने घर कर लिया है, वहाँ अपनी उम्मीद की रूह फूँक दें। मेरी यह प्रार्थना सिर्फ शब्दों तक ही सीमित न रहे; मुझे यह यकीन दिलाएँ कि आप अब भी मेरे जीवन की एक खूबसूरत कहानी लिख रहे हैं। जो मैं अपने दम पर नहीं कर सकता, वह आप मेरे जीवन में पूरा करें। आमीन।",
  "p.240": "स्वर्गीय पिता, ज़िंदगी की इस आपाधापी के बीच मुझसे मिलने के लिए आपका धन्यवाद। आज के दिन को किसी और की उम्मीदों के हवाले करने से पहले मैं इसे आपके हाथों में सौंपता हूँ। आपसे विनती है कि आप मेरे विचारों को सही दिशा दें, मेरी भावनाओं को संभालें और मुझे उस ओर ले चलें जो भला है। आपके अनुग्रह से, डरने के बजाय मेरा मन आप पर भरोसा करना सीखे। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और इतना साहस दीजिए कि मैं उस पर चल सकूँ। आमीन।",
  "p.241": "प्रभु यीशु, रोज़ाना के जीवन की इन मुश्किलों में मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मेरा मन ऐसी चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपसे प्रार्थना करता हूँ कि आप मेरे भीतर के शोर को शांत करें और मुझे याद दिलाएं कि आपकी उपस्थिति हर घबराहट से कहीं बड़ी है। आपकी कृपा से, मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.242": "पवित्र आत्मा, जीवन की इन राहों पर मुझसे मिलने के लिए आपका धन्यवाद, जहाँ आगे का रास्ता मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मैं आपसे विनती करता हूँ कि मुझे अगले क़दम के लिए धीरज दें और उसके बाद वाले क़दम के लिए हिम्मत दें। आपके अनुग्रह से, मुझे मज़बूत बनाइए पर मेरे दिल को कठोर न होने दीजिए। जो मैं अपने दम पर नहीं कर सकता, वह आप मेरे जीवन में पूरा कीजिए। आमीन।",
  "p.243": "दयालु परमेश्वर, जीवन के इस सफ़र में मुझसे मिलने के लिए आपका धन्यवाद। मैं वह पुराना दर्द आपके पास लाता हूँ जिसे मैं आज भी मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। आपकी कृपा से, उन ज़ख्मों को भर दीजिए जिन्हें माफ़ी तुरंत नहीं मिटा पाती। आज मेरा जीवन आपकी आराधना में एक भेंट की तरह हो। आमीन।",
  "p.244": "दयालु पिता, इस भागदौड़ भरी ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने परिवार और उन लोगों को जो मेरे दिल के सबसे करीब हैं, आपके सामने लाता हूँ। आपसे प्रार्थना है कि आप हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाले रखें। आपकी कृपा से, हमारी बातचीत में कोमलता हो और हमारे रिश्ते मज़बूत बनें। आपकी करुणा मेरी हर कमज़ोरी में मुझे सहारा दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.245": "वफ़ादार प्रभु, ज़िंदगी की इस जद्दोजहद में मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको सौंपता हूँ। आपसे विनती है कि मैं सफलता को अपना परमेश्वर बनाए बिना, पूरी लगन से अपनी सेवाएँ दे सकूँ। आपकी कृपा से, मेरे लिए वाह-वाही से ज़्यादा मेरी ईमानदारी मायने रखे। मुझे रुकना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.246": "प्यारे उद्धारकर्ता, असल ज़िंदगी के इन पलों में मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जो घायल है उसे छू लें, जो कमज़ोर है उसे बल दें और मेरी देखभाल करने वालों को बुद्धि दें। आपके अनुग्रह से, जवाब मिलने से पहले ही मेरे भीतर आशा जग जाए। मैं उन बातों में भी आप पर भरोसा रखता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.247": "सर्वशक्तिमान परमेश्वर, जीवन के इस मोड़ पर मुझसे मिलने के लिए आपका धन्यवाद। मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। आपकी कृपा से, मुझे ऐसे फ़ैसले लेने से बचाइए जो केवल डर या घमंड में लिए गए हों। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.248": "शांति के राजकुमार, जीवन की इस दौड़-धूप में मुझसे मिलने के लिए आपका धन्यवाद। मैं उन रहमतों को देखने के लिए रुकता हूँ जिन्हें अक्सर मैं नज़रअंदाज़ कर देता हूँ। मेरी आँखें खोलिए ताकि मैं रोज़ाना के साधारण पलों में छिपी आपकी आशीषों को देख सकूँ। आपके अनुग्रह से, धन्यवाद करना मेरी आदत बन जाए। मुझे अपने वचन में जड़ पकड़ने दें, अपनी दया से घेर लें और आशा से भर दें। आमीन।",
  "p.249": "दया के पिता, ज़िंदगी की हकीकत के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने जीवन और आज के अपने हर क़दम पर आपकी सुरक्षा माँगता हूँ। मुझे दिखने वाले खतरों और छिपे हुए फंदों से बचाए रखिए। अपनी कृपा से मुझे वहीं भेजिए जहाँ मुझे जाना चाहिए और वहाँ से रोक लीजिए जहाँ मेरा जाना ठीक नहीं। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.250": "स्वर्गीय पिता, जीवन की इन चुनौतियों के बीच मुझसे मिलने के लिए आपका धन्यवाद। यह दुनिया मुझे मेरी असफलताओं, मेरे कामों या मेरे दुखों से पहचानने की कोशिश करती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपकी कृपा से, आपका सच हर झूठी बातों से कहीं ज़्यादा बुलंद हो। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उस पर चलने का साहस पा सकूँ। आमीन।",
  "p.251": "प्रभु यीशु, ज़िंदगी के इन मुश्किल रास्तों पर मुझसे मिलने के लिए आपका धन्यवाद। मेरे भीतर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। आपसे विनती है कि मेरे इस दर्द में मेरे साथ बैठें और मुझे तसल्ली दें। आपके अनुग्रह से, मुझे अपनों को प्यार से याद रखना और फिर भी उम्मीद के साथ जीना सिखाइए। आज मुझे किसी ऐसे के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.252": "पवित्र आत्मा, मेरी साधारण ज़िंदगी के बीच आकर मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं उन चीज़ों का खिंचाव महसूस करता हूँ जो मेरी रूह को कमज़ोर कर देती हैं। मैं आपसे विनती करता हूँ कि मुझे एक शुद्ध मन दें, मुश्किलों से निकलने का साफ रास्ता दिखाएँ और जीवन को चुनने की हिम्मत दें। आपके अनुग्रह से, मेरे लिए इसी पल आपकी आज्ञा मानना मुमकिन कर दीजिए। जो मैं खुद नहीं कर सकता, वह आप मेरे अंदर पूरा कीजिए। आमीन।",
  "p.253": "दयालु परमेश्वर, मेरी असल ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद, जहाँ मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों में ज़बरदस्ती करने की कोशिश करता हूँ जो अभी तैयार नहीं हैं। मैं आपसे विनती करता हूँ कि मुझे अपने समय पर भरोसा करना सिखाएँ, ताकि न तो मैं सुस्त पड़ूँ और न ही मेरे मन में कड़वाहट आए। आपके अनुग्रह से, इस देरी के समय में मेरा विश्वास बढ़ता रहे। आज मेरा जीवन आपकी इबादत के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.254": "कृपालु पिता, मेरी असल ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद। मैं इस जीवन को यूँ ही अधूरी नींद में या बिना किसी मकसद के नहीं गुज़ारना चाहता। मैं आपसे विनती करता हूँ कि मुझे वे भले काम दिखाएँ जो आपने आज मेरे लिए पहले से ठहराए हैं। आपके अनुग्रह से, वफादारी के मेरे इन छोटे-छोटे कामों को अनंत काल के लिए कीमती बना दीजिए। आपकी दया मेरी हर कमज़ोरी में मुझे सँभाले और आपकी शांति की ओर ले जाए। आमीन।",
  "p.255": "विश्वासयोग्य प्रभु, मेरी भागदौड़ भरी ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद। आज का दिन खत्म होते समय, मैं उन सब बातों को आपके हाथों में छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मैं आपसे विनती करता हूँ कि मेरे मन को अपनी शांति से धो दें और सोते समय मेरे दिल की रक्षा करें। आपके अनुग्रह से, कल का दिन मेरे लिए नई दया लेकर आए। मुझे धीरज से चलना, गहराई से प्यार करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.256": "प्यारे उद्धारकर्ता, मेरी असल ज़िंदगी की सच्चाइयों के बीच मुझसे मिलने के लिए धन्यवाद। मैं अपने प्रेम, अपनी प्रतिबद्धताओं और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। आपके अनुग्रह से, हमें एक-दूसरे की बात सुनना, माफ़ करना और फिर से एक-दूसरे को चुनना सिखाएँ। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.257": "सर्वशक्तिमान परमेश्वर, मेरी असल ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद। मैं उन बच्चों और नौजवानों को, जिनसे मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। मैं आपसे प्रार्थना करता हूँ कि आप उनके दिलों की रक्षा करें, उनके फैसलों में उनकी अगुवाई करें और उन्हें बुद्धिमान लोगों का साथ दें। आपके अनुग्रह से, वे आपको व्यक्तिगत और गहरे रूप से जान सकें। मेरे हृदय को ऐसा रूप दें कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.258": "शांति के राजकुमार, मेरी ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद। आप अपने लोगों को आशीष दें और एक-दूसरे के लिए हमारे प्यार को नया कर दें। मैं आपसे विनती करता हूँ कि हमें विनम्र, उदार, सच्चा और निडर बनाएँ। आपके अनुग्रह से, हमारा जीवन ऐसा हो कि यह दुनिया यीशु की खूबसूरती को देख सके। मुझे अपने वचन में मज़बूत करें, अपनी दया से घेरे रखें और अपनी आशा से भर दें। आमीन।",
  "p.259": "दया के पिता, मेरी असल ज़िंदगी के बीच मुझसे मिलने के लिए धन्यवाद, जहाँ कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थक चुके हैं। मैं आपसे विनती करता हूँ कि जहाँ निराशा घर कर गई है, वहाँ फिर से उम्मीद की नई रूह फूँक दें। आपके अनुग्रह से, मुझे यह विश्वास करने में मदद दें कि आप अब भी मेरे जीवन की एक सुंदर कहानी लिख रहे हैं। आपकी मरज़ी ही मेरा सुकून बने और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.260": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपके हाथों में सौंपता हूँ: इससे पहले कि मैं आज के दिन को दूसरों की उम्मीदों के हवाले करूँ, मैं इसे आपके चरणों में रखता हूँ। मेरे पास रहिए, मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और मुझे भलाई की राह पर ले चलिए। मेरे विचार और मेरे फैसले यह गवाह दें कि मेरा पहला जवाब डर नहीं, बल्कि आप पर विश्वास है। मेरे दिल को ऐसा बना दीजिए कि उसमें मसीह का स्वभाव झलके। आमीन।",
  "p.261": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेले हल नहीं कर सकता। मेरे पास रहिए, मेरे अंदर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। मेरे मन को आपकी शांति में साँस लेना सिखाइए। मुझे अपने वचन में मज़बूत करें, अपनी दया से घेरे रखें और आशा से भर दें। आमीन।",
  "p.262": "पवित्र आत्मा, मैं अपनी इस ज़रूरत को आपके सामने रखता हूँ: मेरे आगे का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मेरे पास रहिए और मुझे हर अगला कदम वफादारी से उठाने का हौसला और हिम्मत दीजिए। मुझे ऐसा बल दें कि मैं मज़बूत तो बनूँ, पर मेरा दिल कठोर न हो जाए। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.263": "दयालु परमेश्वर, मैं अपनी इस ज़रूरत को आपके चरणों में लाता हूँ: उस दुख को जो मैं मन ही मन बार-बार महसूस करता हूँ, आपको सौंपता हूँ। मेरे करीब रहें, मुझे हर कड़वाहट से आज़ाद करें और मुझे समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाएँ। जिसे माफी तुरंत नहीं मिटा पाती, उसे आप अपनी चंगाई से भर दें। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ, और मुझे इतनी हिम्मत दें कि मैं आपकी आज्ञा मान सकूँ। आमीन।",
  "p.264": "दयालु पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने परिवार और अपने दिल के करीब रहने वाले लोगों को आपके चरणों में लाता हूँ। मेरे पास रहिए और हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि हमारे शब्द कोमल और हमारे रिश्ते मज़बूत बनें। आज मुझे किसी ऐसे इंसान के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.265": "वफादार प्रभु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको अर्पण करता हूँ। मेरे करीब रहिए और सफलता के पीछे भागने के बजाय, पूरी ईमानदारी और लगन के साथ काम करने में मेरी मदद कीजिए। मेरे विचारों, फैसलों और व्यवहार से यह दिखाई दे कि मेरे लिए लोगों की वाह-वाही से ज़्यादा आपकी सच्चाई मायने रखती है। वह काम मुझमें पूरा कीजिए जिसे मैं अपने बलबूते नहीं कर सकता। आमीन।",
  "p.266": "प्यारे उद्धारकर्ता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरे करीब रहिए; मेरे घावों को छुइए, मेरी कमज़ोरी को ताकत दीजिए और मेरी देखभाल करने वालों को बुद्धि दीजिए। मेरे विचार और व्यवहार ऐसे हों कि जवाब मिलने से पहले ही मेरे अंदर एक उम्मीद जाग जाए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.267": "सर्वशक्तिमान परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मुझे सिर्फ जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मेरे करीब रहिए और मुझे सिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मेरे विचार और फैसले ऐसे हों कि मैं डर या घमंड में आकर कोई कदम न उठाऊँ। आपकी कृपा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.268": "शांति के राजकुमार, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं उन छोटी-छोटी मेहरबानियों को पहचानने के लिए रुकता हूँ जिन्हें मैं अक्सर अनदेखा कर देता हूँ। मेरे पास रहिए और मेरी आँखें खोलिए ताकि मैं रोज़मर्रा की बातों में छिपे आपके आशीषों को देख सकूँ। मेरे विचार और व्यवहार ऐसे हों कि शुक्रगुज़ारी मेरा स्वभाव बन जाए। मुझे धीरे चलना, गहरा प्रेम करना और आप पर पूरा भरोसा करना सिखाइए। आमीन।",
  "p.269": "दयालु पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने जीवन और अपने हर कदम के लिए आपकी सुरक्षा माँगता हूँ। मेरे करीब रहिए और मुझे दिखने वाले खतरों और अनदेखे जालों से बचाइए। मेरे विचार और चुनाव ऐसे हों कि मैं वहीं जाऊँ जहाँ आप चाहते हैं और वहाँ रुक जाऊँ जहाँ आप नहीं चाहते। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.270": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: यह दुनिया मुझे मेरी नाकामियों, काम और दुखों से तौलती है। मेरे करीब रहिए और मुझे याद दिलाइए कि मैं आपका हूँ, जिसे आपने अपने अनुग्रह से छुड़ाया है और अपने प्रेम में थामे रखा है। मेरे विचार और व्यवहार ऐसे हों कि आपका सत्य हर झूठी बातों पर भारी पड़े। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.271": "प्रभु यीशु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मेरे अंदर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मेरे करीब रहिए, मेरे दर्द में मेरे साथ बैठिए और बिना किसी जल्दबाज़ी के मुझे तसल्ली दीजिए। मेरे विचार और व्यवहार ऐसे हों कि मैं प्रेम के साथ बीते कल को याद रखूँ और उम्मीद के साथ जी सकूँ। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.272": "पवित्र आत्मा, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मेरे पास रहिए और मुझे एक शुद्ध मन, बुराई से बचने का रास्ता और सही चुनाव करने की ताकत दीजिए। मेरे विचार और व्यवहार ऐसे हों कि इसी पल आपकी आज्ञा मानना मेरे लिए मुमकिन हो जाए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.273": "दयालु परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करना चाहता हूँ जिनका समय अभी नहीं आया। मेरे पास रहिए और मुझे कड़वाहट के बिना आपके समय पर भरोसा करना सिखाइए। मेरे विचार और व्यवहार ऐसे हों कि इस इंतज़ार के समय में मेरा विश्वास और बढ़े। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसका पालन करने का साहस रखूँ। आमीन।",
  "p.274": "दयालु पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं इस जीवन को यूँ ही बिना किसी मकसद के नहीं गुज़ारना चाहता। मेरे करीब रहिए और मुझे वह भलाई के काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। मेरे विचार और चुनाव ऐसे हों कि मेरी छोटी सी वफादारी भी आपके राज्य के लिए मायने रखे। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.275": "वफादार प्रभु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: दिन ढलते ही, मैं उन बातों को आपको सौंप देता हूँ जिन्हें मैं आज ठीक नहीं कर पाया। मेरे पास रहिए, मेरे मन को शांति से भर दीजिए और सोते समय मेरे दिल की हिफाज़त कीजिए। मेरी प्रार्थना है कि कल सुबह मुझे आपकी नई करुणा के दर्शन हों। वह काम मुझमें पूरा कीजिए जिसे मैं अपने बलबूते नहीं कर सकता। आमीन।",
  "p.276": "प्यारे उद्धारकर्ता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं अपने प्रेम, प्रतिबद्धता और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। मेरे करीब रहिए और जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसा हो जो हमें एक-दूसरे की सुनना, माफ करना और बार-बार एक-दूसरे का साथ चुनना सिखाए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.277": "सर्वशक्तिमान परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं उन बच्चों और नौजवानों को आपकी वफ़ादार देखभाल में रखता हूँ जिन्हें मैं प्यार करता हूँ। मेरे करीब रहिए, उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनका मार्गदर्शन कीजिए और उन्हें समझदार लोगों की संगति में रखिए। मेरे विचार, चुनाव और व्यवहार ऐसे हों जो उन्हें आपको व्यक्तिगत रूप से और गहराई से जानने में मदद करें। आपकी करुणा मेरी हर कमज़ोरी में मुझे मिले और मुझे शांति की ओर ले जाए। आमीन।",
  "p.278": "शांति के राजकुमार, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। मेरे करीब रहिए और हमें विनम्र, उदार, सच्चा और साहसी बनाइए। मेरे विचार, चुनाव और व्यवहार ऐसे हों जिससे हमारा जीवन इस दुनिया के सामने प्रभु यीशु की सुंदरता को ज़ाहिर कर सके। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.279": "दया के पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। मेरे करीब रहिए और जहाँ निराशा ने घर कर लिया है, वहाँ आशा की नई फूँक भर दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसे हों जो मुझे यह विश्वास करने में मदद दें कि आप अब भी मेरी कहानी के अच्छे अध्याय लिख रहे हैं। जो मैं समझता हूँ और जो नहीं समझता, उन सब बातों में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.280": "स्वर्गीय पिता, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे मेरे लिए क्यों मायने रखते हैं: किसी और की उम्मीदों पर खरा उतरने की कोशिश करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। आप मेरी मदद कीजिए ताकि मेरे विचार व्यवस्थित रहें, मेरी भावनाएँ स्थिर हों और आप मुझे अच्छाई की राह पर ले चलें। आज मेरा पहला जवाब डर नहीं, बल्कि विश्वास हो। आपकी करुणा मेरी हर कमज़ोरी में मुझे मिले और मुझे शांति की ओर ले जाए। आमीन।",
  "p.281": "प्रभु यीशु, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपसे सहायता माँगता हूँ; मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी मेरे हर डर से कहीं बड़ी है। आज मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.282": "पवित्र आत्मा, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मुझे सँभालिए ताकि मैं वफ़ादारी के साथ अगला कदम उठा सकूँ और उसके बाद के कदम के लिए भी हिम्मत जुटा सकूँ। आज मुझे कठोर बनाए बिना मज़बूत बनाइए। जो मैं समझता हूँ और जो नहीं समझता, उन सब बातों में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.283": "दयालु परमेश्वर, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मैं वह दर्द आपके पास लाता हूँ जिसे मैं बार-बार मन में दोहराता रहता हूँ। मेरी मदद कीजिए ताकि मैं हर कड़वाहट से आज़ाद हो सकूँ और बुद्धि, सच्चाई और अनुग्रह के साथ दूसरों को क्षमा करना सीखूँ। आज उन ज़ख्मों को भर दीजिए जिन्हें क्षमा तुरंत नहीं मिटा पाती। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.284": "दयालु पिता, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मैं अपने परिवार और अपने करीबियों को आपके सामने लाता हूँ। हमारी मदद कीजिए और हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से ढाँप लीजिए। आज हमारे शब्दों में कोमलता और हमारे रिश्तों में मज़बूती हो। मुझे अपने वचन में दृढ़ कीजिए, अपनी करुणा से घेरे रखिए और आशा से भर दीजिए। आमीन।",
  "p.285": "वफ़ादार प्रभु, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मैं अपने हाथों की मेहनत और अपने कंधों का बोझ आपको अर्पित करता हूँ। मेरी मदद कीजिए कि मैं सफलता को अपना देवता बनाए बिना, पूरे मन से श्रेष्ठ सेवा कर सकूँ। आज मेरे लिए लोगों की वाह-वाही से ज़्यादा मेरा खरापन मायने रखे। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.286": "प्यारे उद्धारकर्ता, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मैं अपने शरीर, मन और प्राण की उन जगहों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरी मदद कीजिए, मेरे ज़ख्मों को छुइए, मेरी कमज़ोरी को ताकत दीजिए और मेरी देखरेख करने वालों को बुद्धि दीजिए। आज जवाब मिलने से पहले ही मेरे अंदर आशा जाग उठे। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी आज्ञा मानने का साहस पा सकूँ। आमीन।",
  "p.287": "सर्वशक्तिमान परमेश्वर, आप देखते हैं कि मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे क्यों मायने रखते हैं: मुझे सिर्फ जानकारी नहीं, बल्कि पवित्र बुद्धि की ज़रूरत है। मेरी मदद कीजिए और मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। आज मुझे डर या घमंड में आकर फैसले लेने से बचाइए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.288": "शांति के राजकुमार, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं उन दयाओं पर ध्यान देने के लिए ठहरता हूँ जिन्हें मैं अक्सर भाग-दौड़ में नज़रअंदाज़ कर देता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मेरी आँखें उन उपहारों के लिए खोलते हैं जो आम पलों में छिपे होते हैं। आज, धन्यवाद को मेरा स्वभाव बना दीजिए, न कि केवल एक भावना। मुझमें वो कार्य कीजिए जो मैं स्वयं नहीं कर सकता। आमीन।",
  "p.289": "दयालु पिता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं अपने जीवन और आज के मेरे हर कदम पर आपकी सुरक्षा मांगता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मुझे दिखाई देने वाले खतरों और छिपे हुए फंदों से बचाते हैं। आज, मुझे वहीं भेजें जहाँ मुझे जाना चाहिए और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक लीजिए। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.290": "स्वर्गीय पिता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: यह संसार मुझे मेरी असफलताओं, मेरे काम या मेरे दुखों से पहचानने की कोशिश करता रहता है। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मुझे याद दिलाते हैं कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आज, आपका सत्य हर झूठी पहचान से बढ़कर हो। आपकी कृपा मेरी हर कमजोरी में मुझे थामे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.291": "प्रभु यीशु, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मेरे भीतर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मेरे दर्द में मेरे साथ बैठते हैं और मेरे घावों को भरने में जल्दबाजी किए बिना मुझे तसल्ली देते हैं। आज, मुझे प्रेम के साथ याद करना और फिर भी आशा के साथ जीना सिखाइए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.292": "पवित्र आत्मा, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं उन खिंचावों को महसूस करता हूँ जो मेरी आत्मा को कमजोर करते हैं। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मुझे एक शुद्ध हृदय, बुराई से बचने का मार्ग और जीवन को चुनने का बल देते हैं। आज, मुझे इसी पल में आपकी आज्ञा मानना संभव लगे। मैं उन बातों में भी आप पर भरोसा करता हूँ जो मैं समझता हूँ और उनमें भी जो मैं नहीं समझता। आमीन।",
  "p.293": "दयालु परमेश्वर, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करने की कोशिश में हूँ जो अभी तैयार नहीं हैं। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मुझे बिना निराश या कड़वाहट भरे हुए, आपके समय पर भरोसा करना सिखाते हैं। आज, इस देरी के समय में मेरे भीतर एक शांत विश्वास को बढ़ने दीजिए। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के हृदय जैसा बन जाए। आमीन।",
  "p.294": "दयालु पिता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं इस जीवन को आधे-अधूरे मन से या सोते हुए नहीं बिताना चाहता। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मुझे उन भले कामों को दिखाते हैं जो आपने आज मेरे लिए तैयार किए हैं। आज, वफ़ादारी के मेरे छोटे-छोटे कामों को अनंत काल के लिए फलदायी बनाइए। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.295": "विश्वासयोग्य प्रभु, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: जैसे यह दिन समाप्त हो रहा है, मैं उन सब बातों को छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप मेरे मन को शांति से भर देते हैं और सोते समय मेरे हृदय की रक्षा करते हैं। कल का दिन नई दया के साथ मेरा स्वागत करे। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति ही मेरा बल। आमीन।",
  "p.296": "प्यारे उद्धारकर्ता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप उन रिश्तों में कोमलता फिर से लाते हैं जहाँ तनाव ने कड़वाहट भर दी है। आज, हमें एक-दूसरे को सुनना, क्षमा करना और फिर से चुनना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.297": "सर्वशक्तिमान परमेश्वर, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: मैं उन बच्चों और युवाओं को आपकी विश्वासयोग्य देखभाल में सौंपता हूँ जिनसे मैं प्रेम करता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप उनके हृदयों की रक्षा करते हैं, उनके निर्णयों में मार्गदर्शन करते हैं और उन्हें भली सलाह देने वालों से घेरते हैं। आज, उन्हें आपको व्यक्तिगत रूप से और गहराई से जानने में मदद कीजिए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.298": "शांति के राजकुमार, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप हमें विनम्र, उदार, सच्चा और साहसी बनाते हैं। आज, हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को प्रकट करे। मुझमें वो कार्य कीजिए जो मैं स्वयं नहीं कर सकता। आमीन।",
  "p.299": "दयालु पिता, आप जानते हैं कि मैं किस बोझ तले दबा हूँ और यह मेरे लिए क्यों मायने रखता है: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थक चुके हैं। मैं आपकी सहायता को स्वीकार करता हूँ क्योंकि आप उन जगहों पर आशा की फूँक मारते हैं जहाँ निराशा घर कर गई है। आज, मुझे यह विश्वास करने में मदद कीजिए कि आप अब भी मेरे जीवन के अच्छे अध्याय लिख रहे हैं। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.300": "स्वर्गीय पिता, आज के दिन को किसी और की उम्मीदों में बांधने से पहले, मैं इसे आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मेरा हाथ पकड़कर मुझे भलाई की ओर ले चलिए। मुश्किल घड़ी में डर के बजाय मेरा पहला जवाब आप पर भरोसा हो। मुझे किसी ऐसे व्यक्ति के लिए आशीष बनाइए जिसे आज आपकी दया की ज़रूरत है। आमीन।",
  "p.301": "प्रभु यीशु, मेरा मन ऐसी चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी हर घबराहट से कहीं बड़ी है। मेरे दिल को आपकी शांति में चैन से सांस लेना सिखाइए। जो मैं खुद के लिए नहीं कर सकता, वो आप मेरे जीवन में कीजिए। आमीन।",
  "p.302": "पवित्र आत्मा, मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मुझे हर अगले कदम के लिए धीरज दीजिए और उसके बाद आने वाले कल के लिए हिम्मत। मुझे मज़बूत बनाइए पर मेरा दिल कठोर न होने पाए। आज मेरा पूरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.303": "दयालु परमेश्वर, मैं वो पुरानी चोटें आपके पास लाया हूँ जिन्हें मैं मन ही मन बार-बार याद करता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाइए। जिन ज़ख्मों को माफ़ी तुरंत नहीं भर पाती, उन्हें आप अपनी मरहम से ठीक कीजिए। आपकी कृपा मेरी हर कमज़ोरी में मेरे साथ रहे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.304": "दयालु पिता, मैं अपने परिवार और उन लोगों को आपकी गोद में सौंपता हूँ जो मेरे दिल के सबसे करीब हैं। हमारे घर को सब्र, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। हमारी बातें नरम हों और हमारे रिश्ते अटूट बनें। मुझे धीरज से चलना, दिल खोलकर प्यार करना और पूरी तरह से आप पर भरोसा करना सिखाइए। आमीन।",
  "p.305": "विश्वासयोग्य प्रभु, मैं अपने हाथों की मेहनत और अपने कंधों का बोझ आपको समर्पित करता हूँ। मुझे पूरी लगन से काम करने में मदद कीजिए, पर मैं सफलता को अपना खुदा न बना बैठूँ। मेरे लिए लोगों की वाह-वाही से ज़्यादा आपकी नज़रों में खरा उतरना मायने रखे। मैं उन बातों में भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उन पर भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.306": "प्यारे उद्धारकर्ता, मैं अपने शरीर, मन और आत्मा की उन दरारों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरे ज़ख्मों को छुइए, मेरी कमज़ोरियों को ताकत दीजिए और मेरी देखभाल करने वालों को अपनी बुद्धि से चलाइए। जवाब मिलने से पहले ही मेरे भीतर एक नई उम्मीद जगा दीजिए। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि नज़र आए। आमीन।",
  "p.307": "सर्वशक्तिमान परमेश्वर, मुझे सिर्फ जानकारी की नहीं, बल्कि आपकी आसमानी बुद्धि की ज़रूरत है। मुझे राह दिखाइए कि क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाइए। मुझे अपने वचनों में थामे रखिए, अपनी करुणा से घेरे रखिए और उम्मीद से लबरेज़ कर दीजिए। आमीन।",
  "p.308": "शांति के राजकुमार, मैं आज कुछ पल ठहरकर आपकी उन रहमतों को देखना चाहता हूँ जिन्हें मैं अक्सर भागदौड़ में भूल जाता हूँ। मेरी आँखें खोलिए ताकि मैं रोज़मर्रा की छोटी चीज़ों में छिपे आपके तोहफ़ों को पहचान सकूँ। शुक्रगुज़ारी मेरे स्वभाव का हिस्सा बन जाए। आपकी इच्छा ही मेरी शांति हो और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.309": "दया के पिता, मैं अपने जीवन और आज के अपने हर कदम पर आपका साया माँगता हूँ। मुझे सामने दिखने वाले खतरों और छिपकर बिछाए गए जालों से बचाकर रखिए। जहाँ मुझे जाना चाहिए, वहाँ मेरी अगुवाई कीजिए और जहाँ नहीं जाना चाहिए, वहाँ मेरे कदम रोक लीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी आज्ञा मानने की हिम्मत रखूँ। आमीन।",
  "p.310": "स्वर्गीय पिता, यह दुनिया बार-बार मेरी नाकामियों और मेरे बीते हुए कल से मुझे पहचान देने की कोशिश करती है। पर आप मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से खरीदा गया हूँ और आपके प्यार में सुरक्षित हूँ। आपका सच हर उस झूठी पहचान से कहीं ऊँचा हो जो मुझ पर थौंपी जाती है। मुझे आज किसी के लिए आशीष का ज़रिया बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.311": "प्रभु यीशु, मेरे भीतर ऐसा दर्द है जिसे शब्द पूरी तरह बयान नहीं कर सकते। मेरे इस दुख में मेरे पास बैठिए और मुझे चंगा करने में कोई जल्दबाज़ी किए बिना मुझे तसल्ली दीजिए। मुझे प्यार के साथ यादें संजोना और फिर भी उम्मीद के साथ जीना सिखाइए। वो काम आप मेरे भीतर कीजिए जो मैं खुद से कभी नहीं कर सकता। आमीन।",
  "p.312": "पवित्र आत्मा, मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन दीजिए, प्रलोभन से बचने का रास्ता दिखाइए और जीवन को चुनने की शक्ति दीजिए। इस घड़ी में मेरे लिए आपकी आज्ञा मानना मुमकिन बना दीजिए। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.313": "दयालु परमेश्वर, मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़बरदस्ती करने की कोशिश करता हूँ जिनका समय अभी नहीं आया। मुझे सिखाएं कि कैसे मैं बेचैन या कड़वाहट से भरे बिना आपके समय पर भरोसा करूँ। इस देरी के समय में मेरे विश्वास को और गहरा कीजिए। आपकी अनुग्रह मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.314": "दयालु पिता, मैं इस जीवन को बिना सोचे-समझे या आधी नींद में नहीं गुज़ारना चाहता। मुझे वो भले काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। वफ़ादारी से किए गए मेरे छोटे-छोटे काम अनंत काल के लिए मायने रखें। मुझे धीरे चलना, गहराई से प्रेम करना और पूरी तरह से आप पर भरोसा करना सिखाइए। आमीन।",
  "p.315": "विश्वासयोग्य प्रभु, इस दिन के अंत में, मैं उन सब बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं आज ठीक नहीं कर पाया। मेरे मन को अपनी शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। कल का दिन मेरे लिए नई दया लेकर आए। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सबमें मैं आप पर भरोसा करता हूँ। आमीन।",
  "p.316": "प्यारे उद्धारकर्ता, मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। हमें एक-दूसरे की बात सुनना, माफ़ करना और बार-बार एक-दूसरे को चुनना सिखाइए। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.317": "सर्वशक्तिमान परमेश्वर, मैं उन बच्चों और नौजवानों को आपकी देखरेख में सौंपता हूँ जिनसे मैं प्रेम करता हूँ। उनके मन की रक्षा कीजिए, उनके निर्णयों में उनका मार्गदर्शन कीजिए और उन्हें नेक लोगों की संगति दीजिए। उन्हें ऐसी कृपा दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेरे रखिए और अपनी आशा से भर दीजिए। आमीन।",
  "p.318": "शांति के राजकुमार, अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। हमें नम्र, उदार, सच्चा और साहसी बनाइए। हमारा जीवन इस दुनिया के सामने प्रभु यीशु की सुंदरता को ज़ाहिर करे। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.319": "दया के पिता, कुछ वायदे अभी बहुत दूर लगते हैं और कुछ सपने टूटते हुए महसूस होते हैं। जहाँ निराशा ने घर कर लिया है, वहाँ आशा की नई फूँक मार दीजिए। मुझे यह विश्वास करने में मदद कीजिए कि आप अब भी मेरे जीवन की कहानी में अच्छे अध्याय लिख रहे हैं। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.320": "स्वर्गीय पिता, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: दूसरों की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और मुझे भलाई की राह पर ले चलिए। यह प्रार्थना सिर्फ शब्दों तक न रहे, बल्कि डर के बजाय विश्वास ही मेरा पहला जवाब हो। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेरे रखिए और अपनी आशा से भर दीजिए। आमीन।",
  "p.321": "प्रभु यीशु, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेला सुलझा नहीं सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति मेरी घबराहट से कहीं बड़ी है। यह प्रार्थना सिर्फ शब्दों तक न रहे; मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.322": "पवित्र आत्मा, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा मुश्किल लग रहा है। मुझे अगले कदम के लिए धीरज दीजिए और उससे अगले कदम के लिए हिम्मत। यह प्रार्थना सिर्फ शब्दों तक न रहे; मुझे मज़बूत बनाइए पर कठोर नहीं। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.323": "दयालु परमेश्वर, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: मैं वो चोट आपके सामने लाता हूँ जिसे मैं मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाइए। यह प्रार्थना सिर्फ शब्दों तक न रहे; जो ज़ख्म माफ़ी माँगने से तुरंत नहीं भरते, उन्हें आप चंगा कीजिए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.324": "दयालु पिता, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं अपने परिवार और अपने दिल के करीब लोगों को आपके हाथों में सौंपता हूँ। पिता, हमारे घर को धीरज, सच्चाई, सुरक्षा और प्रेम से भर दीजिए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; हमारे बोलों में मिठास भर दीजिए और हमारे रिश्तों को मजबूत बनाइए। जो मैं खुद की ताकत से नहीं कर सकता, वो आप मेरे जीवन में कीजिए। आमीन।",
  "p.325": "विश्वासयोग्य प्रभु, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं अपने हाथों की मेहनत और अपनी जिम्मेदारियों के बोझ को आपके चरणों में रखता हूँ। प्रभु, मुझे यह सिखाएं कि मैं सफलता के पीछे भागे बिना अपनी जिम्मेदारियों को पूरी खूबी के साथ निभा सकूँ। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; मेरे लिए लोगों की वाहवाही से ज्यादा मेरी सच्चाई और ईमानदारी मायने रखे। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.326": "प्यारे उद्धारकर्ता, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की जरूरत है। पिता, जहाँ घाव हैं उन्हें छुएं, जो कमजोर है उसे बल दें, और मेरी देख-रेख करने वालों को बुद्धि और समझ दें। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; जवाब मिलने से पहले ही मेरे अंदर एक नई उम्मीद जाग उठे। आपकी कृपा मेरी हर कमजोरी में मुझे संभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.327": "सर्वशक्तिमान परमेश्वर, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मुझे केवल जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की जरूरत है। प्रभु, मुझे दिखाएं कि मुझे क्या चुनना है, किसे मना करना है और कब इंतजार करना है। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाए रखना। मुझे धीरज से चलना, दिल से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.328": "शांति के राजकुमार, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं उन आशीषों को देखने के लिए रुकता हूँ जिन्हें मैं अक्सर जल्दबाजी में अनदेखा कर देता हूँ। प्रभु, मेरी आँखें खोलिए ताकि मैं रोजमर्रा के पलों में छिपे आपके तोहफों को देख सकूँ। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; शुक्रिया कहना मेरा स्वभाव बन जाए, न कि केवल एक एहसास। चाहे मैं हालात समझूँ या न समझूँ, मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.329": "दया के पिता, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं अपने जीवन और अपने हर कदम पर आपकी सुरक्षा मांगता हूँ। प्रभु, मुझे सामने दिखने वाले खतरों और छिपे हुए फंदों से बचाए रखिए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; जहाँ मुझे जाना चाहिए वहाँ आप मुझे ले चलिए और जहाँ जाना सही नहीं वहाँ मुझे रोक लीजिए। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.330": "स्वर्गीय पिता, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: यह दुनिया मुझे मेरी नाकामियों, मेरे काम या मेरे दुखों से पहचानने की कोशिश करती है। पिता, मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; आपका सच हर झूठी बातों से ज्यादा गूँजता रहे। मुझे अपने वचन में गहराई से जोड़िए, अपनी दया से घेर लीजिए और उम्मीद से भर दीजिए। आमीन।",
  "p.331": "प्रभु यीशु, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मेरे अंदर एक ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। प्रभु, इस दर्द में मेरे साथ बैठिए और मेरे घावों को भरने में जल्दबाजी किए बिना मुझे तसल्ली दीजिए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; मुझे प्रेम के साथ याद करना और फिर भी उम्मीद के साथ जीना सिखाइए। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.332": "पवित्र आत्मा, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं उन चीजों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमजोर करती हैं। प्रभु, मुझे एक शुद्ध मन दीजिए, बुराई से बचने का रास्ता दिखाइए और जीवन को चुनने की ताकत दीजिए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; आज इसी पल में आपकी आज्ञा मानना मेरे लिए मुमकिन हो जाए। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज सुन सकूँ और इतना निडर बनाइए कि मैं उस पर चल सकूँ। आमीन।",
  "p.333": "दयालु परमेश्वर, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं इंतजार करते-करते थक गया हूँ और उन चीजों को जबरदस्ती हासिल करने की कोशिश कर रहा हूँ जिनका अभी समय नहीं आया। प्रभु, मुझे कड़वाहट या आलस में डूबे बिना आपके समय पर भरोसा करना सिखाइए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; इस देरी के समय में मेरा विश्वास बढ़ता रहे। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की जरूरत है। आमीन।",
  "p.334": "दयालु पिता, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: मैं अपनी जिंदगी को यूं ही सोते हुए नहीं बिताना चाहता। पिता, मुझे वो भले काम दिखाएं जो आपने आज मेरे लिए ठहराए हैं। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; मेरी वफादारी के छोटे-छोटे काम भी आपके राज्य के लिए मायने रखें। जो मैं खुद से नहीं कर सकता, वो आप मुझमें होकर कीजिए। आमीन।",
  "p.335": "विश्वासयोग्य प्रभु, आज मैं पूरी ईमानदारी से आपके सामने आता हूँ: इस दिन के अंत में, मैं उन सब बातों को आपके हाथों में छोड़ता हूँ जिन्हें मैं ठीक नहीं कर सकता। प्रभु, मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे हृदय को सुरक्षित रखिए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; कल की सुबह मेरे लिए आपकी नई दया लेकर आए। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.336": "प्यारे उद्धारकर्ता, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने रखता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ कृपया फिर से कोमलता भर दीजिए। मेरी यह प्रार्थना केवल शब्दों तक सीमित न रहे; हमें एक-दूसरे की सुनना, माफ करना और बार-बार एक-दूसरे का साथ चुनना सिखाइए। आपकी दया मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.337": "सर्वशक्तिमान परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं उन बच्चों और नौजवानों को आपकी वफ़ादार सुरक्षा में सौंपता हूँ जिनसे मैं प्रेम करता हूँ। उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उनके जीवन को भले मार्गदर्शकों से भर दीजिए। मेरी यह प्रार्थना सिर्फ शब्दों तक न रहे; उन्हें ऐसा अनुग्रह दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। मुझे सिखाना कि मैं धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सीख सकूँ। आमीन।",
  "p.338": "शांति के राजकुमार, आज मैं सच्चाई के साथ आपके सामने आता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। हमें विनम्र, उदार, सच्चा और निडर बनाइए। मेरी यह प्रार्थना केवल शब्द बनकर न रह जाए; हमारा जीवन इस संसार के सामने प्रभु यीशु की सुंदरता को प्रकट करे। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझ पाता, उन सब में मैं आप ही पर भरोसा रखता हूँ। आमीन।",
  "p.339": "दयालु पिता, आज मैं पूरी ईमानदारी के साथ आपके पास आता हूँ: कुछ वादे अब बहुत दूर लगते हैं और कुछ सपने मानो थक गए हैं। जहाँ निराशा ने घर कर लिया है, वहाँ आशा की नई किरण जगा दीजिए। मेरी यह प्रार्थना शब्दों से बढ़कर हो; मुझे यह विश्वास करने में मदद कीजिए कि आप आज भी मेरे जीवन में भलाई के नए अध्याय लिख रहे हैं। मेरे हृदय को ऐसा रूप दीजिए कि मुझमें मसीह की छवि दिखाई दे। आमीन।",
  "p.340": "स्वर्गीय पिता, जीवन की आपाधापी के बीच मुझसे मिलने के लिए आपका धन्यवाद। किसी और की उम्मीदों को पूरा करने से पहले, मैं आज के दिन को आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए और मुझे भलाई की राह पर ले चलिए। आपके अनुग्रह से, डर के बजाय विश्वास मेरा पहला उत्तर हो। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.341": "प्रभु यीशु, जीवन की असल मुश्किलों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरा मन ऐसी चिंताओं से घिरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे भीतर के इस शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। अपने अनुग्रह से मेरे हृदय को आपकी शांति में साँस लेना सिखाइए। मैं उन बातों में भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.342": "पवित्र आत्मा, जीवन की हकीकतों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरे सामने का रास्ता मेरी सोच से कहीं ज़्यादा मुश्किल लग रहा है। मुझे अगले हर कदम के लिए धीरज और साहस दीजिए। अपने अनुग्रह से मुझे मज़बूत बनाइए, पर कठोर नहीं। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के हृदय जैसा बन जाए। आमीन।",
  "p.343": "दयालु परमेश्वर, जीवन के संघर्षों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं वो चोटें आपके पास लाया हूँ जो मैं मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ दूसरों को माफ करना सिखाइए। आपकी दया उन घावों को भर दे जिन्हें माफी तुरंत नहीं मिटा पाती। मुझे अपने वचनों में दृढ़ कीजिए, मुझे अपनी करुणा से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.344": "दयालु पिता, जीवन के उतार-चढ़ावों के बीच मुझसे मिलने के लिए धन्यवाद। मैं अपने परिवार और अपनों को आपके हाथों में सौंपता हूँ। हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाल लीजिए। अपने अनुग्रह से हमारी बातों में नरमी और हमारे रिश्तों में मज़बूती लाइए। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति मेरी सामर्थ्य हो। आमीन।",
  "p.345": "वफ़ादार प्रभु, जीवन की इस भागदौड़ के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपके चरणों में रखता हूँ। मुझे सफलता का मोह रखे बिना, पूरी ईमानदारी से सेवा करना सिखाइए। आपके अनुग्रह से, मेरे लिए वाह-वाही से ज़्यादा मेरा चरित्र और सच्चाई मायने रखे। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ, और मुझे इतना साहसी बनाइए कि मैं उसकी आज्ञा मान सकूँ। आमीन।",
  "p.346": "प्यारे उद्धारकर्ता, जीवन की हकीकतों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जो घायल है उसे छू लीजिए, जो कमज़ोर है उसे बल दीजिए और हर सेवा करने वाले को बुद्धि दीजिए। अपने अनुग्रह से, प्रार्थना का उत्तर मिलने से पहले ही मेरे अंदर आशा जगा दीजिए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.347": "सर्वशक्तिमान परमेश्वर, जीवन के बीचों-बीच मुझसे मिलने के लिए आपका धन्यवाद। मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। अपने अनुग्रह से मुझे डर या घमंड में आकर फैसले लेने से बचाइए। वह काम मेरे जीवन में कीजिए, जो मैं अपने आप नहीं कर सकता। आमीन।",
  "p.348": "शांति के राजकुमार, इस रोज़मर्रा की ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं रुककर उन रहमतों को देख पा रहा हूँ जिन्हें मैं अक्सर भाग-दौड़ में भूल जाता हूँ। मैं आपसे बिनती करता हूँ कि आम पलों में छिपे तोहफ़ों को देखने के लिए मेरी आँखें खोल दीजिए। अपने अनुग्रह से, शुक्रगुज़ारी को मेरे लिए सिर्फ एक एहसास नहीं, बल्कि एक आदत बना दीजिए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.349": "दयालु पिता, इस असली ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं अपने जीवन और अपने हर कदम पर आपकी सुरक्षा की माँग करता हूँ। मुझे दिखने वाले खतरों और छिपे हुए जालों से बचाए रखिए। अपने अनुग्रह से, मुझे वहीं ले चलिए जहाँ मुझे जाना चाहिए और मुझे वहाँ जाने से रोक लीजिए जहाँ मुझे नहीं जाना चाहिए। आपकी कृपा मेरी हर कमज़ोरी में मुझसे मिले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.350": "स्वर्गीय पिता, इस जीवन की उलझनों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ यह दुनिया मुझे मेरी नाकामियों या दुखों से पहचानने की कोशिश करती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। अपनी कृपा से, अपने सच को हर झूठी पहचान से कहीं ज़्यादा ऊँचा कर दीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह से आप पर भरोसा करना सिखाइए। आमीन।",
  "p.351": "प्रभु यीशु, इस ज़िंदगी के संघर्षों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मेरे भीतर ऐसा दुख है जिसे शब्दों में पूरी तरह बयां नहीं किया जा सकता। मैं आपसे प्रार्थना करता हूँ कि इस दर्द में मेरे साथ बैठें और मुझे तसल्ली दें। अपने अनुग्रह से, मुझे पुरानी यादों को प्यार से सहेजने और एक नई उम्मीद में जीना सिखाइए। मैं उन बातों में भी आप पर भरोसा करता हूँ जो मेरी समझ में आती हैं और उनमें भी जिन्हें मैं नहीं समझ पा रहा। आमीन।",
  "p.352": "पवित्र आत्मा, इस जीवन की हकीकतों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं उन चीज़ों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन और बुराई से बचने का रास्ता दीजिए, और जीवन को चुनने की हिम्मत दीजिए। अपने अनुग्रह से, मुझे इसी पल आपकी आज्ञा मानना मुमकिन लगने लगे। मेरे दिल को ऐसा बनाइए कि उसमें मसीह की छवि नज़र आए। आमीन।",
  "p.353": "अनुग्रहकारी परमेश्वर, जीवन के इस मोड़ पर मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को जल्दबाज़ी में हासिल करना चाहता हूँ जिनका समय अभी नहीं आया। मुझे बिना किसी कड़वाहट के आपके समय पर भरोसा करना सिखाइए। अपने अनुग्रह से, इस देरी के समय में मेरे भीतर एक शांत विश्वास पैदा कीजिए। मुझे अपने वचनों में थामे रखिए, अपनी दया से घेरे रहिए और मुझे उम्मीद से भर दीजिए। आमीन।",
  "p.354": "दयालु पिता, इस साधारण जीवन में मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मैं अपनी ज़िंदगी को बिना किसी मकसद के यूँ ही नहीं बिताना चाहता। आज के लिए आपने जो भले काम मेरे लिए तैयार किए हैं, उन्हें मुझे दिखाइए। अपने अनुग्रह से, वफ़ादारी के मेरे इन छोटे-छोटे कामों को हमेशा रहने वाली एक बड़ी आशीष बना दीजिए। आपकी इच्छा ही मेरी शांति बन जाए और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.355": "वफ़ादार प्रभु, आज का दिन ढलते हुए मुझसे मिलने के लिए आपका धन्यवाद। जो बातें आज मैं ठीक नहीं कर पाया, उन्हें अब मैं आपके हाथों में छोड़ता हूँ। मेरे मन को अपनी शांति से भर दीजिए और सोते समय मेरे दिल की हिफ़ाज़त कीजिए। अपने अनुग्रह से, आने वाले कल में मुझे फिर से नई दया का अनुभव कराइए। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी बात मानने की हिम्मत जुटा सकूँ। आमीन।",
  "p.356": "प्यारे उद्धारकर्ता, इस असल ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने प्रेम और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। अपने अनुग्रह से, हमें एक-दूसरे की बात सुनना, माफ करना और फिर से एक-दूसरे का साथ चुनना सिखाइए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.357": "सर्वशक्तिमान परमेश्वर, इस जीवन की गहमागहमी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं उन बच्चों और नौजवानों को आपकी वफ़ादार देखरेख में सौंपता हूँ जिनसे मैं प्यार करता हूँ। उनके दिलों की रक्षा कीजिए, उनके रास्तों में उनकी अगुवाई कीजिए और उन्हें समझदार लोगों का साथ दीजिए। अपने अनुग्रह से, उन्हें खुद को गहराई से जानने में मदद कीजिए। मेरे भीतर वह कार्य कीजिए जो मैं खुद नहीं कर सकता। आमीन।",
  "p.358": "शांति के राजकुमार, इस जीवन के बीच मुझसे मिलने के लिए आपका धन्यवाद। अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को ताज़ा कर दीजिए। हमें विनम्र, उदार, सच्चा और निडर बनाइए। अपने अनुग्रह से, हमारे जीवन के ज़रिए दुनिया प्रभु यीशु की सुंदरता को देख सके। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.359": "दयालु पिता, इस ज़िंदगी की हकीकतों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ कुछ वादे अब बहुत दूर और कुछ सपने थके हुए से लगते हैं। जहाँ निराशा ने घर कर लिया है, वहाँ अपनी उम्मीद की साँस फूँक दीजिए। अपने अनुग्रह से, मुझे यह यकीन दिलाइए कि आप अब भी मेरे जीवन की कहानी में अच्छे अध्याय लिख रहे हैं। आपकी कृपा मेरी हर कमज़ोरी में मुझे सँभाले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.360": "स्वर्गीय पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: किसी और की उम्मीदों को पूरा करने से पहले, मैं आज के दिन को आपके हाथों में रखता हूँ। मेरे पास बने रहिए क्योंकि आप मेरे विचारों को सही दिशा देते हैं, मेरी भावनाओं को संभालते हैं और मुझे अच्छाई की राह पर ले चलते हैं। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मेरी पहली प्रतिक्रिया डर नहीं बल्कि विश्वास है। वह काम मुझमें कीजिए जिसे मैं अपने आप नहीं कर सकता। आमीन।",
  "p.361": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे पास रहिए, मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति किसी भी घबराहट से कहीं बढ़कर है। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मेरा दिल आपकी शांति में सांस लेना सीख रहा है। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.362": "पवित्र आत्मा, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरे सामने का रास्ता मेरी सोच से कहीं ज़्यादा मुश्किल लग रहा है। मेरे पास रहिए और मुझे अगले विश्वासयोग्य कदम के लिए धीरज और उसके बाद के सफर के लिए हिम्मत दीजिए। मेरे विचार, चुनाव और व्यवहार मुझे मज़बूत तो बनाएँ, पर दिल को कठोर न होने दें। आपकी अनुग्रह मेरी हर कमज़ोरी में मुझे सँभाले और शांति की राह दिखाए। आमीन।",
  "p.363": "दयालु परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं वह दर्द आपके पास लाता हूँ जिसे मैं मन ही मन बार-बार दोहराता रहता हूँ। मेरे निकट रहिए और मुझे कड़वाहट से आज़ाद कीजिए। मुझे बुद्धिमानी, सच्चाई और अनुग्रह के साथ दूसरों को क्षमा करना सिखाइए। मेरे विचार, चुनाव और व्यवहार से वो घाव भी भर जाएँ जिन्हें क्षमा तुरंत नहीं मिटा पाती। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.364": "दयालु पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने परिवार और अपने प्रियजनों को आपके सामने लाता हूँ। हमारे साथ रहिए और हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। मेरे विचार, चुनाव और व्यवहार हमारे शब्दों में नम्रता लाएँ और हमारे रिश्तों को मज़बूत बनाएँ। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.365": "विश्वासयोग्य प्रभु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने हाथों की मेहनत और अपने कंधों का बोझ आपको अर्पित करता हूँ। मेरे पास रहिए और बिना किसी नाम या सफलता के मोह के, मुझे पूरी निष्ठा से सेवा करना सिखाइए। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि मेरे लिए लोगों की वाहवाही से ज़्यादा मेरा चरित्र और ईमानदारी मायने रखती है। मेरे दिल को वैसा ही बना दीजिए जैसा मसीह का हृदय है। आमीन।",
  "p.366": "प्यारे उद्धारकर्ता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मेरे निकट रहिए और मेरे ज़ख्मों को छुइए, मेरी कमज़ोरी को ताक़त दीजिए और मेरी देखभाल करने वालों को बुद्धि दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसी उम्मीद जगाएँ जो जवाब मिलने से पहले ही मुझमें काम करने लगे। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.367": "सर्वशक्तिमान परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मुझे केवल जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मेरे पास रहिए और मुझे सिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मेरे विचार, चुनाव और व्यवहार मुझे ऐसे फ़ैसलों से बचाएँ जो सिर्फ डर या घमंड में लिए गए हों। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.368": "शांति के राजकुमार, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं एक पल ठहरकर उन आशीषों को देखना चाहता हूँ जिन्हें मैं अक्सर भागदौड़ में भूल जाता हूँ। मेरे निकट रहिए और मेरी आँखें खोलिए ताकि मैं रोज़मर्रा के पलों में छिपे आपके उपहारों को देख सकूँ। मेरे विचार, चुनाव और व्यवहार धन्यवाद को केवल एक भावना नहीं, बल्कि मेरी आदत बना दें। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसका पालन करने की हिम्मत रख सकूँ। आमीन।",
  "p.369": "दया के पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने जीवन और आज के अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। मेरे पास रहिए और मुझे दिखने वाले खतरों और छिपे हुए जालों से बचाइए। मेरे विचार, चुनाव और व्यवहार मुझे वहीं ले जाएँ जहाँ मुझे जाना चाहिए और वहाँ रोक दें जहाँ मुझे नहीं जाना चाहिए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.370": "स्वर्गीय पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: यह दुनिया मुझे मेरी नाकामियों, काम और दुखों से पहचान देने की कोशिश करती रहती है। मेरे पास रहिए और मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से खरीदा हुआ और आपके प्रेम में सुरक्षित हूँ। मेरे विचार, चुनाव और व्यवहार यह दिखा सकें कि आपका सत्य हर झूठी पहचान से कहीं बड़ा है। वह काम मुझमें कीजिए जिसे मैं अपने आप नहीं कर सकता। आमीन।",
  "p.371": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरे भीतर एक ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मेरे करीब रहिए, मेरे दर्द में मेरे साथ बैठिए और मुझे दिलासा दीजिए—बिना मुझे चंगा होने के लिए जल्दबाज़ी किए। मेरे विचार, चुनाव और व्यवहार मुझे यह सिखाएँ कि मैं कैसे प्रेम के साथ पुरानी यादों को सँजोते हुए भी उम्मीद के साथ जी सकूँ। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.372": "पवित्र आत्मा, मैं अपनी इस ज़रूरत को आपके चरणों में रखता हूँ: मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मेरे करीब रहिए और मुझे एक शुद्ध मन, बचने का एक साफ़ रास्ता और जीवन को चुनने की शक्ति दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसे हों कि इस घड़ी में मेरे लिए आपकी आज्ञा मानना मुमकिन हो जाए। आपका अनुग्रह मेरी हर कमज़ोरी में मुझे थाम ले और मुझे शांति की ओर ले चले। आमीन।",
  "p.373": "दयालु परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़ोर-ज़बरदस्ती करने की कोशिश में हूँ जिनके लिए अभी समय सही नहीं है। मेरे पास रहिए और मुझे सिखाए कि बिना मन छोटा किए या कड़वाहट पालने के मैं आपके समय पर भरोसा कर सकूँ। मेरे विचारों और फैसलों से ऐसा गहरा विश्वास झलके जो इंतज़ार की घड़ियों में भी शांत रहता है। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.374": "हे दयालु पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं इस जीवन को यूँ ही खोया-खोया या आधा-अधूरा जागते हुए नहीं बिताना चाहता। मेरे करीब रहिए और मुझे वह भलाई दिखाइए जो आपने आज के दिन मेरे लिए तैयार की है। मेरे विचार और काम ऐसे हों कि वफ़ादारी के मेरे छोटे-छोटे काम भी हमेशा के लिए मायने रखें। जो मैं समझता हूँ और जो नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.375": "वफ़ादार प्रभु, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: दिन ढलने पर मैं उन बातों को छोड़ देता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मेरे पास रहिए, मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे दिल की हिफाज़त कीजिए। मेरे विचार और चुनाव ऐसे हों कि कल का दिन मेरे लिए नई दया लेकर आए। मेरे हृदय को ऐसा रूप दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.376": "प्यारे उद्धारकर्ता, मैं अपनी इस ज़रूरत को आपके हाथ में देता हूँ: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके पास लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। मेरे करीब रहिए और जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। मेरे विचार और व्यवहार ऐसे हों कि हम एक-दूसरे की सुनना, माफ़ करना और बार-बार एक-दूसरे का साथ चुनना सीखें। मुझे अपने वचन में मज़बूत कीजिए, अपनी दया से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.377": "सर्वशक्तिमान परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं उन बच्चों और नौजवानों को आपकी देखरेख में रखता हूँ जिनसे मैं प्रेम करता हूँ। मेरे पास रहिए, उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें समझदार लोगों का साथ दीजिए। मेरे विचार और काम ऐसे हों कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.378": "शांति के राजकुमार, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। मेरे करीब रहिए और हमें विनम्र, उदार, सच्चा और निडर बनाइए। हमारे विचार और काम ऐसे हों कि हमारा जीवन इस दुनिया के सामने प्रभु यीशु की महिमा को प्रकट करे। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि उस पर चल सकूँ। आमीन।",
  "p.379": "दया के पिता, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थके हुए से लगते हैं। मेरे पास रहिए और जहाँ निराशा घर कर गई है, वहाँ फिर से उम्मीद जगा दीजिए। मेरे विचार और चुनाव ऐसे हों कि मुझे यह विश्वास बना रहे कि आप अब भी मेरे जीवन की एक अच्छी कहानी लिख रहे हैं। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.380": "स्वर्गीय पिता, आप जानते हैं कि मुझ पर क्या बोझ है और यह मेरे लिए क्यों ज़रूरी है: किसी और की उम्मीदों को पूरा करने से पहले, मैं यह दिन आपके हाथों में सौंपता हूँ। जब आप मेरे विचारों को सही दिशा देते हैं, मेरी भावनाओं को संभालते हैं और मुझे भलाई की राह पर ले चलते हैं, तब मैं आपकी सहायता स्वीकार करता हूँ। आज डरने के बजाय, मेरा पहला कदम विश्वास का हो। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.381": "प्रभु यीशु, आप जानते हैं कि मुझ पर क्या बोझ है और यह मेरे लिए क्यों ज़रूरी है: मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेला हल नहीं कर सकता। मैं आपकी मदद माँगता हूँ क्योंकि आप मेरे भीतर के शोर को शांत करते हैं और मुझे याद दिलाते हैं कि आपकी मौजूदगी किसी भी घबराहट से कहीं बड़ी है। आज मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उस पर चलने का साहस पा सकूँ। आमीन।",
  "p.382": "पवित्र आत्मा, आप जानते हैं कि मुझ पर क्या बोझ है और यह मेरे लिए क्यों ज़रूरी है: मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मैं आपकी सहायता माँगता हूँ ताकि मैं अपना अगला कदम वफ़ादारी से उठा सकूँ और उसके आगे के लिए भी मुझे हिम्मत मिले। आज मुझे मज़बूत बनाइए पर कठोर नहीं। मुझे किसी ऐसे व्यक्ति के लिए आशीष बनाइए जिसे आज आपकी करुणा की ज़रूरत है। आमीन।",
  "p.383": "दयालु परमेश्वर, आप जानते हैं कि मुझ पर क्या बोझ है और यह मेरे लिए क्यों ज़रूरी है: मैं वह चोट आपके पास लाया हूँ जिसे मैं बार-बार मन ही मन याद करता रहता हूँ। मैं आपकी मदद स्वीकार करता हूँ; मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ माफ़ करना सिखाइए। आज उन घावों को भर दीजिए जिन्हें केवल माफ़ी तुरंत नहीं मिटा पाती। जो मैं खुद के लिए नहीं कर सकता, वह आप मुझमें कीजिए। आमीन।",
  "p.384": "दयालु पिता, आप देख रहे हैं कि आज मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि मेरे लिए इनका क्या महत्व है: मैं अपने परिवार और अपने प्रियजनों को आपके चरणों में लाता हूँ। आपकी सहायता मुझ पर बनी रहे और आप हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से ढांप लें। आज हमारे बोलों में मिठास भर दीजिए और हमारे आपसी रिश्तों को मज़बूत कीजिए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.385": "विश्वासयोग्य प्रभु, आप देख रहे हैं कि आज मैं किन बोझों को उठाए हुए हूँ और आप जानते हैं कि वे मेरे लिए क्यों ज़रूरी हैं: मैं अपने हाथों की मेहनत और अपने कंधों पर लदे काम के दबाव को आपको सौंपता हूँ। आपकी सहायता मुझ पर बनी रहे ताकि मैं सफलता के पीछे भागने के बजाय, पूरी ईमानदारी और लगन से सेवा कर सकूँ। आज मेरे लिए लोगों की वाह-वाही से बढ़कर मेरी नेकदिली मायने रखे। आपकी कृपा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.386": "प्यारे उद्धारकर्ता, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। आपकी सहायता मुझ पर बनी रहे; आप मेरे घावों को छुएँ, मेरी कमज़ोरियों को ताकत दें और मेरी देखभाल करने वालों को बुद्धि दें। आज जवाब मिलने से पहले ही मेरे भीतर एक नई उम्मीद जगा दीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.387": "सर्वशक्तिमान परमेश्वर, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मुझे केवल जानकारी की नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। आपकी सहायता मुझ पर बनी रहे ताकि आप मुझे सही चुनाव करने, गलत बातों को नकारने और धीरज से इंतज़ार करना सिखा सकें। आज मुझे ऐसे फैसलों से बचाए रखें जो केवल डर या घमंड में आकर लिए गए हों। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं समझ नहीं पाता। आमीन।",
  "p.388": "शांति के राजकुमार, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं थोड़ी देर रुककर उन आशीषों को याद करना चाहता हूँ जिन्हें मैं अक्सर भागदौड़ में भूल जाता हूँ। आपकी सहायता मुझ पर बनी रहे और आप मेरी आँखों को उन तोहफों के लिए खोल दें जो इन साधारण पलों में छिपे हैं। आज धन्यवाद करना मेरे लिए केवल एक भावना नहीं, बल्कि एक आदत बन जाए। मेरे हृदय को ऐसा रूप दें कि वह मसीह के स्वभाव को दर्शा सके। आमीन।",
  "p.389": "दया के सागर पिता, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं अपने जीवन और अपने हर कदम पर आपकी सुरक्षा चाहता हूँ। आपकी सहायता मुझ पर बनी रहे और आप मुझे हर दिखने वाले खतरे और छिपे हुए फंदों से बचाए रखें। आज मुझे वहीं भेजें जहाँ मुझे जाना चाहिए और मुझे उन रास्तों से रोक लें जो मेरे लिए सही नहीं हैं। मुझे अपने वचनों में थामे रखें, अपनी दया से घेरे रहें और उम्मीद से भर दें। आमीन।",
  "p.390": "स्वर्गीय पिता, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: यह दुनिया मुझे मेरी नाकामियों, मेरे काम या मेरे दुखों से पहचानने की कोशिश करती है। आपकी सहायता मुझ पर बनी रहे और आप मुझे याद दिलाते रहें कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आज आपका सत्य हर झूठी बातों से कहीं ज़्यादा प्रभावशाली हो। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी सामर्थ्य। आमीन।",
  "p.391": "प्रभु यीशु, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मेरे भीतर ऐसा दुख है जिसे शब्दों में बयां करना नामुमकिन है। आपकी सहायता मुझ पर बनी रहे; आप मेरे इस दर्द में मेरे साथ बैठें और चंगाई के लिए मुझ पर दबाव डाले बिना मुझे दिलासा दें। आज मुझे प्यार के साथ यादें संजोना और उम्मीद के साथ जीना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और आपकी आज्ञा मानने का साहस जुटा सकूँ। आमीन।",
  "p.392": "पवित्र आत्मा, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं उन बातों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। आपकी सहायता मुझ पर बनी रहे; मुझे शुद्ध मन दें, बुराई से बचने का रास्ता दिखाएं और जीवन को चुनने की सामर्थ्य दें। आज मेरे लिए आपकी आज्ञा मानना संभव कर दीजिए। मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आज आपकी दया की ज़रूरत है। आमीन।",
  "p.393": "अनुग्रहकारी परमेश्वर, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों के लिए ज़बरदस्ती करने की कोशिश करता हूँ जिनका समय अभी नहीं आया है। आपकी सहायता मुझ पर बनी रहे; मुझे बिना कड़वाहट या आलस्य के आपके सही समय पर भरोसा करना सिखाइए। आज इस देरी के समय में मेरा विश्वास और बढ़ने पाए। वह काम मुझमें कीजिए जो मैं अपने आप से कभी नहीं कर सकता। आमीन।",
  "p.394": "दयालु पिता, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं इस जीवन को बिना किसी मकसद के यूँ ही नहीं गुज़ारना चाहता। आपकी सहायता मुझ पर बनी रहे और आप मुझे वे भले काम दिखाएं जो आपने आज मेरे लिए ठहराए हैं। आज मेरी वफादारी के छोटे-छोटे काम भी आपके राज्य के लिए फलदायी हों। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.395": "विश्वासयोग्य प्रभु, आप देख रहे हैं कि मैं क्या बोझ उठाए हुए हूँ और आप जानते हैं कि यह क्यों मायने रखता है: आज का दिन खत्म होते समय, मैं उन बातों को छोड़ देता हूँ जिन्हें मैं ठीक नहीं कर सकता। आपकी सहायता मुझ पर बनी रहे; मेरे मन को अपनी शांति से धो दें और सोते समय मेरे हृदय की रक्षा करें। आज की रात बीतने पर कल की सुबह मुझे आपकी नई करुणा के साथ मिले। आपका अनुग्रह मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.396": "प्यारे उद्धारकर्ता, आप देखते हैं कि मैं किस बोझ तले दबा हूँ और आप जानते हैं कि मेरे लिए इसका क्या महत्व है: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। आपकी मदद से हमारे उन रिश्तों में फिर से कोमलता भर दीजिए जहाँ तनाव ने कड़वाहट पैदा कर दी है। आज हमें एक-दूसरे की बात सुनना, माफ़ करना और फिर से एक-दूसरे का साथ चुनना सिखाइए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह से आप पर भरोसा करना सिखाइए। आमीन।",
  "p.397": "सर्वशक्तिमान परमेश्वर, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं उन बच्चों और नौजवानों को आपकी वफ़ादार देख-रेख में सौंपता हूँ जिन्हें मैं प्यार करता हूँ। आप उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें समझदार लोगों की संगति में रखिए। आज उन्हें आपकी व्यक्तिगत और गहरी पहचान पाने में मदद कीजिए। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.398": "शांति के राजकुमार, आप देखते हैं कि मैं किन हालातों से गुज़र रहा हूँ और आप जानते हैं कि यह क्यों ज़रूरी है: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। हमें विनम्र, उदार, सच्चा और निडर बनाकर हमारी सहायता कीजिए। आज हमारा जीवन ऐसा हो कि यह देखने वाली दुनिया को प्रभु यीशु की सुंदरता दिखा सके। मेरे हृदय को ऐसा रूप दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.399": "दयालु पिता, आप देखते हैं कि मैं किस दौर से गुज़र रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: कुछ वादे अभी बहुत दूर लगते हैं और कुछ सपने टूटते हुए महसूस होते हैं। जहाँ निराशा ने घर कर लिया है, वहाँ आशा की नई किरण जगाकर मेरी मदद कीजिए। आज मुझमें यह विश्वास जगाइए कि आप अभी भी मेरे जीवन की कहानी में कुछ अच्छा लिख रहे हैं। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेरे रखिए और मुझे अपनी आशा से भर दीजिए। आमीन।",
  "p.400": "स्वर्गीय पिता, आज के दिन को किसी और की उम्मीदों पर छोड़ने से पहले मैं इसे आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मुझे अच्छाई की राह पर ले चलिए। मेरी पहली प्रतिक्रिया डर नहीं, बल्कि आप पर विश्वास हो। जिन बातों को मैं समझता हूँ और जिन्हें नहीं समझता, उन सब में मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.401": "प्रभु यीशु, मेरा मन ऐसी चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति मेरी घबराहट से कहीं बढ़कर है। मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। मेरे हृदय को ऐसा रूप दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.402": "पवित्र आत्मा, मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी लग रहा है। मुझे हर अगले सही कदम के लिए धीरज और हिम्मत दीजिए। मुझे कठोर बनाए बिना मज़बूत बनाइए। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेरे रखिए और मुझे अपनी आशा से भर दीजिए। आमीन।",
  "p.403": "दयालु परमेश्वर, मैं उन चोटों को आपके पास लाता हूँ जिन्हें मैं बार-बार याद करता रहता हूँ। मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई व अनुग्रह के साथ माफ़ करना सिखाइए। जिसे माफ़ी तुरंत नहीं मिटा पाती, उसे आप अपनी चंगाई से भर दीजिए। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.404": "दयालु पिता, मैं अपने परिवार और अपने करीबियों को आपके चरणों में लाता हूँ। हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम की आशीष दीजिए। हमारे शब्द नरम हों और हमारे रिश्ते मज़बूत। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसे मान सकूँ। आमीन।",
  "p.405": "वफ़ादार प्रभु, मैं अपने हाथों के काम और अपने कंधों के बोझ को आपको सौंपता हूँ। सफलता का मोह रखे बिना, पूरी निष्ठा के साथ सेवा करने में मेरी मदद कीजिए। मेरे लिए दुनिया की वाहवाही से ज़्यादा मेरी ईमानदारी मायने रखे। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.406": "प्यारे उद्धारकर्ता, मैं अपने शरीर, मन और आत्मा के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जो घायल है उसे छुएं, जो कमज़ोर है उसे बल दें और मेरी देखभाल करने वालों को बुद्धि दें। मदद मिलने से पहले ही मेरे अंदर आशा की किरण जगा दीजिए। मुझमें वो काम कीजिए जिसे मैं खुद नहीं कर सकता। आमीन।",
  "p.407": "सर्वशक्तिमान परमेश्वर, मुझे सिर्फ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। मुझे केवल डर या घमंड में आकर फैसले लेने से बचाइए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.408": "शान्ति के राजकुमार, मैं उन आशीषों पर ध्यान देने के लिए रुकता हूँ जिन्हें मैं अक्सर भागदौड़ में अनदेखा कर देता हूँ। मेरी आँखें खोलिए ताकि मैं रोज़मर्रा के साधारण पलों में छिपे हुए आपके उपहारों को देख सकूँ। शुक्रगुज़ारी को केवल मेरा स्वभाव नहीं बल्कि मेरी आदत बना दीजिए। आपकी दया मेरी हर कमज़ोरी में मेरा सहारा बने और मुझे शान्ति की राह पर ले चले। आमीन।",
  "p.409": "दया के पिता, मैं अपने जीवन और आज के अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। मुझे दिखने वाले खतरों और छिपे हुए फंदों से बचाकर रखिए। जहाँ मुझे जाना चाहिए, वहाँ मेरी अगुवाई कीजिए और जहाँ नहीं जाना चाहिए, वहाँ मुझे रोक लीजिए। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.410": "स्वर्गीय पिता, यह दुनिया बार-बार मेरी नाकामियों, मेरी खूबियों या मेरे दुखों से मेरी पहचान बनाने की कोशिश करती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपका सत्य हर झूठी बातों से बढ़कर मेरे कानों में गूँजे। मैं उन बातों में भी आप पर भरोसा रखता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.411": "प्रभु यीशु, मेरे भीतर ऐसा दुख है जिसे शब्द बयाँ नहीं कर सकते। इस दर्द में मेरे साथ बैठिए और मेरे घावों को भरने में जल्दबाजी किए बिना मुझे तसल्ली दीजिए। मुझे प्यार के साथ यादें सँजोना और फिर भी उम्मीद के साथ जीना सिखाइए। मेरे हृदय को ऐसा रूप दीजिए कि इसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.412": "पवि़त्र आत्मा, मैं उन बातों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन, बुराई से बचने का साफ रास्ता और जीवन को चुनने की शक्ति दीजिए। मदद कीजिए कि इसी पल मैं आपकी आज्ञा मानना मेरे लिए मुमकिन हो सके। मुझे अपने वचनों में थामे रखिए, अपनी दया से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.413": "दयालु परमेश्वर, मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करने की कोशिश करता हूँ जो अभी तैयार नहीं हैं। मुझे अपने समय पर भरोसा करना सिखाइए ताकि मैं निराश या कड़वाहट से न भरूँ। इस देरी के समय में मेरा विश्वास और बढ़ने पाए। आपकी इच्छा मेरी शान्ति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.414": "दयालु पिता, मैं इस जीवन को यूँ ही आधे-अधूरे मन से नहीं जीना चाहता। मुझे वह भलाई के काम दिखाइए जो आपने आज मेरे लिए ठहराए हैं। मेरी छोटी-छोटी वफादारियों को अनंत काल के लिए फलदायक बनाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाइए कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.415": "विश्वासयोग्य प्रभु, आज का दिन बीतने पर मैं उन बातों को आपके हाथों में सौंपता हूँ जिन्हें मैं सुधार नहीं सकता। मेरे मन को अपनी शान्ति से धो दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। कल का दिन मेरे लिए आपकी नई दया लेकर आए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.416": "प्यारे उद्धारकर्ता, मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव के कारण कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। हमें एक-दूसरे की सुनना, माफ करना और बार-बार एक-दूसरे को अपनाना सिखाइए। वह कार्य मुझमें पूरा कीजिए जो मैं खुद नहीं कर सकता। आमीन।",
  "p.417": "सर्वशक्तिमान परमेश्वर, मैं उन बच्चों और नौजवानों को जिन्हें मैं प्रेम करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। उनके मन की रक्षा कीजिए, उनके चुनाव में उनकी अगुवाई कीजिए और उनके जीवन में समझदार लोगों को भेजिए। उन्हें ऐसा अनुग्रह दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। मेरा आज का जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.418": "शान्ति के राजकुमार, अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। हमें नम्र, उदार, सच्चा और साहसी बनाइए। हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करने पाए। आपकी दया मेरी हर कमज़ोरी में मेरा सहारा बने और मुझे शान्ति की राह पर ले चले। आमीन।",
  "p.419": "दया के पिता, कुछ वायदे अभी बहुत दूर लगते हैं और कुछ सपने अब थका रहे हैं। जहाँ निराशा जम गई है, वहाँ अपनी उम्मीद की फूँक मार दीजिए। मुझे यह विश्वास करने में मदद कीजिए कि आप अभी भी मेरे जीवन की कहानी के अच्छे अध्याय लिख रहे हैं। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.420": "स्वर्गीय पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: इससे पहले कि मैं दुनिया की उम्मीदों को पूरा करने में लग जाऊँ, मैं अपना यह दिन आपके हाथों में सौंपता हूँ। प्रभु, मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और जो भला है, उसकी ओर मेरी अगुवाई कीजिए। यह प्रार्थना केवल शब्दों तक ही सीमित न रहे, बल्कि डर के बजाय मेरा पहला भरोसा आप पर हो। मेरा आज का जीवन आपकी आराधना में एक शांत भेंट की तरह हो। आमीन।",
  "p.421": "प्रभु यीशु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मेरा मन ऐसी चिंताओं से घिरा है जिन्हें मैं अकेले सुलझा नहीं सकता। प्रभु, मेरे अंदर के इस शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति मेरी घबराहट से कहीं बढ़कर है। यह प्रार्थना केवल शब्द बनकर न रह जाए; मेरा हृदय आपकी शांति में सांस लेना सीखे। आपकी दया मेरी हर कमजोरी में मुझे थामे और मुझे उस सुकून की ओर ले चले जो केवल आपसे मिलता है। आमीन।",
  "p.422": "पवित्र आत्मा, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: आगे का यह रास्ता मेरी सोच से कहीं ज्यादा कठिन लग रहा है। प्रभु, मुझे हिम्मत दीजिए कि मैं अपना अगला कदम विश्वास के साथ उठा सकूँ और उसके बाद के कदम के लिए भी मुझे निडर बनाइए। यह प्रार्थना केवल शब्दों तक न रहे; मुझे मज़बूत बनाइए पर कठोर नहीं। मुझे ठहरकर चलना, गहरा प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.423": "दयालु परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं वह चोट आपके पास लाया हूँ जिसे मैं मन ही मन बार-बार महसूस करता हूँ। प्रभु, मुझे कड़वाहट से आज़ाद कीजिए और मुझे बुद्धि, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। यह प्रार्थना केवल शब्द न रहे; उस घाव को भर दीजिए जिसे माफ़ कर देने के बाद भी दिल से मिटाना मुश्किल होता है। मैं उन बातों के लिए भी आप पर भरोसा रखता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.424": "दयालु पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने परिवार और उन लोगों को जो मुझे सबसे प्रिय हैं, आपके सामने लाता हूँ। प्रभु, हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाल लीजिए। यह प्रार्थना शब्दों से बढ़कर हो; हमारी बातचीत में नरमी हो और हमारे आपसी रिश्ते मज़बूत हों। मेरे हृदय को ऐसा रूप दीजिए कि वह मसीह के स्वभाव को झलका सके। आमीन।",
  "p.425": "विश्वासयोग्य प्रभु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने हाथों की मेहनत और अपनी ज़िम्मेदारियों का बोझ आपके चरणों में रखता हूँ। प्रभु, मेरी मदद कीजिए कि मैं दिखावे के लिए नहीं बल्कि पूरी लगन से काम करूँ। यह प्रार्थना केवल शब्दों तक न रहे; मेरे लिए लोगों की वाहवाही से बढ़कर मेरी सच्चाई और ईमानदारी हो। मुझे अपने वचनों में थामे रखिए, अपनी दया से घेरे रखिए और मुझे नई आशा से भर दीजिए। आमीन।",
  "p.426": "प्यारे उद्धारकर्ता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने शरीर, मन और प्राण के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। प्रभु, मेरे ज़ख्मों को छुएँ, मेरी कमज़ोरी को ताकत दें और मेरी देखभाल करने वालों को बुद्धि दें। यह प्रार्थना केवल शब्द न रहे; चंगाई मिलने से पहले ही मेरा दिल उम्मीद से भर जाए। आपकी इच्छा ही मेरा सुकून बन जाए और आपकी मौजूदगी मेरी ताकत। आमीन।",
  "p.427": "सर्वशक्तिमान परमेश्वर, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि की ज़रूरत है। प्रभु, मुझे समझाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। यह प्रार्थना केवल शब्दों तक न रहे; मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाइए। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसका पालन करने की हिम्मत रख सकूँ। आमीन।",
  "p.428": "शांति के राजकुमार, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं उन मेहरबानियों को पहचानने के लिए रुकता हूँ जिन्हें अक्सर मैं भागदौड़ में अनदेखा कर देता हूँ। प्रभु, मेरी आँखें खोलिए ताकि मैं रोज़मर्रा के पलों में छिपी आपकी आशीषों को देख सकूँ। यह प्रार्थना केवल शब्द न रहे; शुक्रगुज़ारी मेरा स्वभाव बन जाए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.429": "दया के पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मैं अपने जीवन और अपने हर कदम के लिए आपकी सुरक्षा माँगता हूँ। प्रभु, मुझे दिखने वाले खतरों और छिपे हुए फंदों से बचाइए। यह प्रार्थना केवल शब्दों तक न रहे; जहाँ मुझे जाना चाहिए वहाँ आप मेरी अगुवाई करें और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक लें। मुझमें वो काम कीजिए जो मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.430": "स्वर्गीय पिता, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: यह दुनिया मुझे मेरी असफलताओं, मेरे कामों या मेरे दुखों से पहचानने की कोशिश करती है। प्रभु, मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से खरीदा गया हूँ और आपके प्रेम में सुरक्षित हूँ। यह प्रार्थना केवल शब्द न रहे; आपकी सच्चाई हर उस झूठी बात से ऊँची हो जो दुनिया मेरे बारे में कहती है। आज मेरा पूरा जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.431": "प्रभु यीशु, आज मैं पूरी सच्चाई के साथ आपके सामने आता हूँ: मेरे अंदर ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। प्रभु, मेरे इस दर्द में मेरे पास बैठिए और मुझे तसल्ली दीजिए, मेरे ज़ख्म भरने में जल्दबाज़ी न करें। यह प्रार्थना केवल शब्दों तक न रहे; मुझे प्रेम के साथ यादों को सँभालना और उम्मीद के साथ जीना सिखाइए। आपकी दया मेरी हर कमजोरी में मुझे थामे और मुझे उस चैन की ओर ले चले जो केवल आपसे मिलता है। आमीन।",
  "p.432": "पवित्र आत्मा, मैं आज पूरी ईमानदारी के साथ आपके पास आता हूँ: मैं उस खिंचाव को महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करता है। कृपया मुझे एक शुद्ध मन, निकलने का साफ़ रास्ता और जीवन को चुनने का बल दीजिए। मेरी यह प्रार्थना केवल शब्दों तक न रहे; मुझे ऐसा बल दें कि इसी पल आपकी आज्ञा मानना मेरे लिए संभव हो सके। मुझे आपके साथ धीरज से चलना, गहराई से प्रेम करना और पूरी तरह भरोसा करना सिखाइए। आमीन।",
  "p.433": "अनुग्रहकारी परमेश्वर, मैं आज सच्चाई के साथ आपके पास आता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन बातों को ज़बरदस्ती पूरा करने की कोशिश कर रहा हूँ जो अभी तैयार नहीं हैं। कृपया मुझे सिखाएं कि कैसे मैं बेचैन या कड़वाहट से भरे बिना आपके समय पर भरोसा करूँ। यह प्रार्थना महज़ शब्द न रह जाए; इंतज़ार के इस समय में मेरा भरोसा बढ़ाइए। मैं उन बातों में भी आप पर यकीन करता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.434": "दयालु पिता, मैं आज सच्चाई के साथ आपके पास आता हूँ: मैं इस जीवन को बिना किसी मकसद के या आधे-अधूरे मन से नहीं जीना चाहता। कृपया मुझे वो भलाई के काम दिखाएँ जो आपने आज मेरे लिए ठहराए हैं। मेरी यह प्रार्थना शब्दों से बढ़कर हो; वफ़ादारी के मेरे छोटे-छोटे कामों का असर अनंत काल तक बना रहे। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.435": "विश्वासयोग्य प्रभु, मैं आज सच्चाई के साथ आपके पास आता हूँ: जैसे यह दिन बीत रहा है, मैं उन बातों को आपके हाथों में सौंप देता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। कृपया मेरे मन को शांति दें और सोते समय मेरे हृदय की रक्षा करें। मेरी यह प्रार्थना महज़ शब्द न रह जाए; कल की सुबह आपकी नई करुणा मेरे साथ हो। मुझे अपने वचन में मज़बूत करें, अपनी दया से घेरे रखें और उम्मीद से भर दें। आमीन।",
  "p.436": "प्यारे उद्धारकर्ता, मैं आज पूरी ईमानदारी से आपके पास आता हूँ: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। यह प्रार्थना शब्दों से बढ़कर हो; हमें एक-दूसरे की सुनना, माफ़ करना और फिर से एक-दूसरे का साथ चुनना सिखाइए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.437": "सर्वशक्तिमान परमेश्वर, मैं आज सच्चाई के साथ आपके पास आता हूँ: मैं इन बच्चों और जवानों को, जिनसे मैं प्रेम करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। कृपया उनके मन की रक्षा करें, उनके फैसलों में उनकी अगुवाई करें और उन्हें सही सलाह देने वाले लोगों के साथ रखें। मेरी यह प्रार्थना शब्दों से बढ़कर हो; उन्हें आपकी व्यक्तिगत और गहरी पहचान मिले। मुझे अपने इतने करीब रखें कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाएँ कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.438": "शांति के राजकुमार, मैं आज सच्चाई के साथ आपके पास आता हूँ: अपने लोगों को आशीष दें और एक-दूसरे के लिए हमारे प्रेम को नया कर दें। कृपया हमें नम्र, उदार, सच्चा और निडर बनाएँ। यह प्रार्थना महज़ शब्द न रह जाए; हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को प्रकट करे। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाएँ जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.439": "दया के पिता, मैं आज पूरी ईमानदारी से आपके सामने आता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। जहाँ निराशा ने घर कर लिया है, वहाँ अपनी आशा की फूँक फूँकिए। यह प्रार्थना महज़ शब्द न रह जाए; मुझे यह यकीन करने में मदद दें कि आप अब भी मेरे जीवन की कहानी में अच्छे अध्याय लिख रहे हैं। मुझमें वो काम कीजिए जो मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.440": "स्वर्गीय पिता, ज़िंदगी की इन असल जद्दोजहद के बीच मुझसे मिलने के लिए आपका धन्यवाद। इससे पहले कि मैं दुनिया की उम्मीदों को पूरा करूँ, मैं इस दिन को आपके हाथों में सौंपता हूँ। मेरे विचारों को सही दिशा दें, मेरी भावनाओं को संभालें और मुझे भलाई की राह पर ले चलें। आपके अनुग्रह से, मेरी पहली प्रतिक्रिया डर नहीं बल्कि विश्वास हो। मुझे अपने इतने करीब रखें कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना साहसी बनाएँ कि मैं उसका पालन कर सकूँ। आमीन।",
  "p.441": "प्रभु यीशु, ज़िंदगी की इन असल मुश्किलों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मेरा मन उन चिंताओं से भरा है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपसे प्रार्थना करता हूँ कि मेरे भीतर के शोर को शांत करें और मुझे याद दिलाएँ कि आपकी उपस्थिति किसी भी घबराहट से कहीं बड़ी है। आपके अनुग्रह से, मेरे हृदय को आपकी शांति में साँस लेना सिखाएं। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाएँ जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.442": "पवित्र आत्मा, ज़िंदगी की इन असल चुनौतियों के बीच मुझसे मिलने के लिए आपका धन्यवाद, जहाँ मेरे सामने का रास्ता उम्मीद से कहीं ज़्यादा कठिन लग रहा है। मैं आपसे अगले कदम के लिए धीरज और उसके बाद के कदम के लिए साहस माँगता हूँ। आपके अनुग्रह से, मुझे मज़बूत बनाएँ पर कठोर नहीं। मुझमें वो काम कीजिए जो मैं अपने आप से नहीं कर सकता। आमीन।",
  "p.443": "अनुग्रहकारी परमेश्वर, ज़िंदगी के इन असल पलों में मुझसे मिलने के लिए धन्यवाद। मैं वो सारे दर्द आपके पास लाता हूँ जिन्हें मैं बार-बार मन ही मन दोहराता रहता हूँ। मुझे कड़वाहट से आज़ाद करें और बुद्धि, सच्चाई और अनुग्रह के साथ माफ़ करना सिखाएं। आपकी दया से उन ज़ख्मों को भर दें जिन्हें केवल माफ़ी तुरंत नहीं मिटा पाती। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.444": "दयालु पिता, मेरी रोज़मर्रा की ज़िन्दगी की भागदौड़ के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने परिवार और उन सभी को जो मेरे दिल के सबसे करीब हैं, आपके हाथों में सौंपता हूँ। मेरी विनती है कि आप हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाले रखें। आपकी कृपा से हमारे बोल मीठे हों और हमारे रिश्ते अटूट बनें। मेरी हर कमज़ोरी में आपका अनुग्रह मेरा सहारा बने और मुझे शांति के मार्ग पर ले चले। आमीन।",
  "p.445": "विश्वासयोग्य प्रभु, मेरी रोज़मर्रा की ज़िन्दगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको सौंपता हूँ। मुझे यह सिखाए कि मैं दुनिया की वाहवाही के पीछे भागे बिना पूरी लगन से आपकी सेवा करूँ। आपकी कृपा से, मेरे लिए सफलता से ज़्यादा मेरी ईमानदारी मायने रखे। मुझे धीरे-धीरे चलना, दिल खोलकर प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.446": "प्यारे उद्धारकर्ता, मेरी ज़िन्दगी की उलझनों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने तन, मन और प्राण की उन सभी बातों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। जो घायल है उसे छुएं, जो कमज़ोर है उसे बल दें, और हर देखभाल करने वाले को बुद्धि और समझ प्रदान करें। आपकी कृपा से, प्रार्थना का उत्तर मिलने से पहले ही मेरे मन में उम्मीद जाग उठे। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझ नहीं पाता। आमीन।",
  "p.447": "सर्वशक्तिमान परमेश्वर, जीवन की व्यस्तता के बीच मुझसे मिलने के लिए आपका धन्यवाद। मुझे सिर्फ जानकारी की नहीं, बल्कि आपके पवित्र ज्ञान की ज़रूरत है। मुझे दिखाइए कि मुझे क्या चुनना है, किसे मना करना है और कब इंतज़ार करना है। आपकी कृपा से, मुझे डर या घमंड में आकर फैसले लेने से बचाइए। मेरे हृदय को ऐसा रूप दीजिए कि मुझमें मसीह की छवि दिखाई दे। आमीन।",
  "p.448": "शांति के राजकुमार, मेरी व्यस्त ज़िन्दगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं उन छोटी-छोटी आशीषों को पहचानने के लिए रुकना चाहता हूँ जिन्हें मैं अक्सर अनदेखा कर देता हूँ। मेरी आँखें खोलिए ताकि मैं रोज़ के साधारण पलों में भी आपके वरदानों को देख सकूँ। आपकी कृपा से, मेरा स्वभाव शिकायत करने वाला नहीं बल्कि हमेशा धन्यवाद देने वाला हो। मुझे अपने वचन में जड़ पकड़ने दीजिए, अपनी दया से घेरे रखिए और आशा से भर दीजिए। आमीन।",
  "p.449": "दयालु पिता, मेरी भागदौड़ भरी ज़िन्दगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने जीवन और अपने हर कदम पर आपकी सुरक्षा माँगता हूँ। मुझे हर दिखने वाले खतरे और शैतान के छिपाये हुए फंदों से बचाइए। आपकी कृपा से, मुझे वहीं ले चलिए जहाँ मुझे जाना चाहिए और वहाँ जाने से रोक लीजिए जहाँ मेरा जाना ठीक नहीं। आपकी इच्छा ही मेरी शांति और आपकी उपस्थिति ही मेरी सामर्थ्य बन जाए। आमीन।",
  "p.450": "स्वर्गीय पिता, ज़िन्दगी की कशमकश के बीच मुझसे मिलने के लिए आपका धन्यवाद। यह दुनिया अक्सर मुझे मेरी नाकामियों और तकलीफों से पहचानना चाहती है। मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आपकी कृपा से, आपका सत्य दुनिया की हर झूठी बात से ज़्यादा गूँजे। मुझे अपने इतना करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उस पर चलने का साहस पा सकूँ। आमीन।",
  "p.451": "प्रभु यीशु, जीवन के संघर्षों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मेरे भीतर ऐसा दुख है जिसे शब्दों में बयान करना मुश्किल है। इस दर्द में मेरे पास बैठिए और मुझे धीरज के साथ दिलासा दीजिए। आपकी कृपा से, मुझे प्रेम के साथ पुरानी यादों को सँजोना और भविष्य के लिए उम्मीद के साथ जीना सिखाइए। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.452": "पवित्र आत्मा, जीवन की उथल-पुथल के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं उन चीज़ों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मुझे एक शुद्ध मन और बुराई से बचने का मार्ग दीजिए, और जीवन की राह चुनने की शक्ति प्रदान कीजिए। आपकी कृपा से, इसी पल आपकी आज्ञा मानना मेरे लिए संभव हो सके। वह काम मुझमें पूरा कीजिए जो मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.453": "अनुग्रहकारी परमेश्वर, जीवन की चुनौतियों के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को ज़बरदस्ती हासिल करने की कोशिश करता हूँ जिनका समय अभी नहीं आया। मुझे अपने समय पर भरोसा करना सिखाइए ताकि मैं निराश या कड़वाहट से न भरूँ। आपकी कृपा से, इस इंतज़ार के समय में मेरा विश्वास और गहरा हो। आज मेरा जीवन आपकी आराधना के लिए एक भेंट बन जाए। आमीन।",
  "p.454": "दयालु पिता, मेरी व्यस्त ज़िन्दगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं इस जीवन को बिना किसी उद्देश्य के यूँ ही नहीं बिताना चाहता। आज आपने मेरे लिए जो भलाई के काम ठहराए हैं, उन्हें मुझ पर प्रगट कीजिए। आपकी कृपा से मेरी वफ़ादारी के छोटे-छोटे काम भी आपके राज्य के लिए फलदायी हों। मेरी हर निर्बलता में आपका अनुग्रह मुझ पर बना रहे और मुझे शांति की ओर ले जाए। आमीन।",
  "p.455": "विश्वासयोग्य प्रभु, दिन भर की इस आपाधापी के बीच मुझसे मिलने के लिए आपका धन्यवाद। अब जबकि यह दिन बीत रहा है, मैं उन सब बातों को आपके चरणों में छोड़ देता हूँ जिन्हें मैं सुधार नहीं सकता। मेरे मन को अपनी शांति से भर दीजिए और सोते समय मेरे हृदय की रक्षा कीजिए। आपकी कृपा से कल का दिन मेरे लिए नई दया लेकर आए। मुझे धीरे-धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.456": "प्यारे उद्धारकर्ता, इस साधारण सी ज़िंदगी के बीच मुझसे मिलने के लिए आपका धन्यवाद। मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। जहाँ तनाव की वजह से हमारे स्वभाव में कड़वाहट आ गई है, वहाँ फिर से कोमलता भर दीजिए। अपनी कृपा से हमें एक-दूसरे की बात सुनना, क्षमा करना और बार-बार एक-दूसरे को अपनाना सिखाइए। जो बातें मैं समझ पाता हूँ और जो नहीं समझ पाता, उन दोनों के लिए मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.457": "सर्वशक्तिमान परमेश्वर, रोज़मर्रा की ज़िंदगी के बीच मेरा साथ देने के लिए धन्यवाद। मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। उनके दिलों की रक्षा कीजिए, उनके चुनाव में उनका मार्गदर्शन कीजिए और उन्हें भले लोगों की संगति दीजिए। अपनी कृपा से उन्हें ऐसा अनुग्रह दीजिए कि वे आपको व्यक्तिगत रूप से और गहराई से जान सकें। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की छवि दिखाई दे। आमीन।",
  "p.458": "शांति के राजकुमार, जीवन की भागदौड़ के बीच मुझसे मिलने के लिए आपका धन्यवाद। आप अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। हमें दीन, उदार, सच्चा और साहसी बनाइए। आपकी कृपा हम पर ऐसी हो कि हमारा जीवन इस दुनिया के सामने प्रभु यीशु की सुंदरता को ज़ाहिर कर सके। मुझे अपने वचन में जड़ पकड़ने में मदद कीजिए, मुझे अपनी दया से घेरे रखिए और उम्मीद से भर दीजिए। आमीन।",
  "p.459": "दया के पिता, इस असल ज़िंदगी के बीच मेरा हाथ थामने के लिए धन्यवाद। कभी-कभी आपके वादे बहुत दूर लगते हैं और सपने थके हुए से महसूस होते हैं। जहाँ निराशा ने घर कर लिया है, वहाँ आशा की नई किरण जगा दीजिए। अपने अनुग्रह से मुझे यह विश्वास दिलाइए कि आप अब भी मेरे जीवन की कहानी में अच्छी बातें लिख रहे हैं। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.460": "स्वर्गीय पिता, मैं अपनी इस ज़रूरत को आपके सामने रखता हूँ: दूसरों की उम्मीदों को पूरा करने से पहले, मैं इस दिन को आपके हाथों में सौंपता हूँ। मेरे करीब रहिए, मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को संभालिए और मुझे भलाई की राह पर ले चलिए। मेरे विचार और काम यह दिखा सकें कि डर के बजाय विश्वास ही मेरा पहला जवाब है। मेरे हृदय को ऐसा बनाइए कि उसमें मसीह का स्वभाव झलके। आमीन।",
  "p.461": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरा मन उन चिंताओं से घिरा है जिन्हें मैं अकेले सुलझा नहीं सकता। मेरे करीब आइए, मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी मौजूदगी हर घबराहट से बड़ी है। मेरे हृदय को आपकी शांति में सुकून पाना सिखाइए। मुझे अपने पवित्र वचन में मज़बूत कीजिए, अपनी दया से ढांप लीजिए और उम्मीद से भर दीजिए। आमीन।",
  "p.462": "पवित्र आत्मा, मैं अपनी इस ज़रूरत को आपके चरणों में लाता हूँ: मेरे सामने का रास्ता मेरी उम्मीद से कहीं ज़्यादा भारी है। मेरे पास रहिए और मुझे हर अगले कदम के लिए धीरज और हिम्मत दीजिए। मुझे कमज़ोर हुए बिना मज़बूत बनाइए ताकि मेरा स्वभाव कठोर न होने पाए। आपकी इच्छा ही मेरा चैन बन जाए और आपकी उपस्थिति मेरा बल। आमीन।",
  "p.463": "दयालु परमेश्वर, मैं अपनी इस ज़रूरत को आपको सौंपता हूँ: मैं उस चोट को आपके पास लाया हूँ जिसे मैं मन ही मन दोहराता रहता हूँ। मेरे करीब रहिए और मुझे कड़वाहट से आज़ाद कीजिए; मुझे बुद्धि और अनुग्रह के साथ दूसरों को माफ करना सिखाइए। उन ज़ख्मों को भर दीजिए जिन्हें माफी तुरंत नहीं मिटा पाती। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और उसका पालन करने का साहस पा सकूँ। आमीन।",
  "p.464": "दयालु पिता, मैं इस ज़रूरत को आपको समर्पित करता हूँ: मैं अपने परिवार और उन लोगों को जिन्हें मैं सबसे ज़्यादा प्यार करता हूँ, आपके सामने लाता हूँ। हमारे घर को अपने धीरज, ईमानदारी, सुरक्षा और प्रेम से भर दीजिए। हमारे बोल मीठे हों और हमारे रिश्ते अटूट बनें। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की तलाश है। आमीन।",
  "p.465": "विश्वासयोग्य प्रभु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने हाथों की मेहनत और अपने कंधों के बोझ को आपको अर्पण करता हूँ। मेरी मदद कीजिए कि मैं सफलता के पीछे भागे बिना पूरी लगन से सेवा कर सकूँ। मेरे लिए लोगों की वाह-वाही से ज़्यादा मेरा चरित्र और सच्चाई मायने रखे। जो मैं अपने दम पर नहीं कर सकता, वह आप मुझमें रहकर पूरा कीजिए। आमीन।",
  "p.466": "प्यारे उद्धारकर्ता, मैं अपनी इस ज़रूरत को आपके पास लाता हूँ: अपने शरीर, मन और आत्मा के उन हिस्सों को आपको सौंपता हूँ जिन्हें चंगाई चाहिए। मेरे ज़ख्मों को छुइए, मेरी कमज़ोरी को दूर कीजिए और मेरा इलाज करने वालों को बुद्धि दीजिए। इससे पहले कि मेरी प्रार्थना का उत्तर दिखे, मेरा भरोसा आप पर बढ़ जाए। आज मेरा जीवन आपकी आराधना में एक शांत भेंट बन जाए। आमीन।",
  "p.467": "सर्वशक्तिमान परमेश्वर, मैं इस ज़रूरत को आपके सामने रखता हूँ: मुझे केवल जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। मुझे दिखाइए कि क्या चुनना है, किसे छोड़ना है और कब इंतज़ार करना है। मुझे डर या घमंड में आकर कोई भी फैसला लेने से बचाइए। हर कमज़ोरी में आपकी कृपा मुझे थामे रखे और शांति के मार्ग पर ले चले। आमीन।",
  "p.468": "शांति के राजकुमार, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन दयाओं पर ध्यान देने के लिए रुकता हूँ जिन्हें अक्सर भाग-दौड़ में भूल जाता हूँ। मेरे करीब रहिए और साधारण पलों में छिपे आशीषों को देखने के लिए मेरी आँखें खोल दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि शुक्रगुज़ारी मेरा स्वभाव बन जाए, न कि केवल एक एहसास। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.469": "दया के पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने जीवन पर और आज मेरे हर कदम पर आपकी सुरक्षा मांगता हूँ। मेरे पास रहिए और मुझे सामने दिखने वाले खतरों और छिपे हुए जालों से बचाए रखिए। मेरे विचार, चुनाव और व्यवहार यह दिखाएं कि आप ही मुझे सही राह पर ले जाते हैं और गलत रास्तों से रोकते हैं। मैं उन बातों में भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.470": "स्वर्गीय पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: यह दुनिया मुझे मेरी नाकामियों, काम के बोझ या दुखों से पहचानने की कोशिश करती है। मेरे पास रहिए और मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से छुड़ाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। मेरे विचार, चुनाव और व्यवहार यह दिखाएं कि आपका सत्य हर झूठी बातों से कहीं बढ़कर है। मेरे हृदय को ऐसा रूप दीजिए कि उसमें मसीह की झलक दिखाई दे। आमीन।",
  "p.471": "प्रभु यीशु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मेरे भीतर ऐसा दुख है जिसे शब्दों में बयान करना मुश्किल है। मेरे पास रहिए, मेरे दर्द में मेरे साथ बैठिए और मुझे चंगा करने में जल्दबाजी किए बिना मुझे तसल्ली दीजिए। मेरे विचार, चुनाव और व्यवहार मुझे यह सिखाएं कि मैं अपनों को प्यार से याद रखूँ और फिर भी उम्मीद के साथ जीता रहूँ। मुझे अपने वचन में स्थिर कीजिए, अपनी दया से घेर लीजिए और आशा से भर दीजिए। आमीन।",
  "p.472": "पवित्र आत्मा, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन बातों का खिंचाव महसूस करता हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मेरे पास रहिए, मुझे एक शुद्ध मन और बुराई से बचने का रास्ता दीजिए, और जीवन को चुनने की ताकत दीजिए। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि इसी पल आपकी आज्ञा मानना मेरे लिए मुमकिन हो जाए। आपकी इच्छा मेरी शांति बन जाए और आपकी उपस्थिति मेरी ताकत। आमीन।",
  "p.473": "दयालु परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं इंतज़ार करते-करते थक गया हूँ और उन बातों को जल्दबाजी में करने की कोशिश कर रहा हूँ जो अभी तैयार नहीं हैं। मेरे पास रहिए और मुझे कड़वाहट या आलस में गिरे बिना आपके सही समय पर भरोसा करना सिखाइए। मेरे विचार, चुनाव और व्यवहार इस देरी के समय में मेरे विश्वास को और गहरा करें। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ सुन सकूँ और इतना निडर बनाइए कि उसका पालन कर सकूँ। आमीन।",
  "p.474": "दयालु पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं इस जीवन को बिना किसी मकसद के बस यूँ ही नहीं बिताना चाहता। मेरे पास रहिए और मुझे वे भले काम दिखाइए जो आपने आज मेरे लिए तैयार किए हैं। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि वफादारी के मेरे छोटे-छोटे काम भी आपके राज्य के लिए मायने रखें। आज मुझे किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी करुणा की ज़रूरत है। आमीन।",
  "p.475": "वफादार प्रभु, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: जैसे यह दिन खत्म हो रहा है, मैं उन बातों को छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मेरे पास रहिए, मेरे मन को अपनी शांति से धो दीजिए और सोते समय मेरे दिल को सुरक्षित रखिए। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि कल की सुबह आपकी नई दया के साथ मेरा स्वागत करे। मुझमें वो काम कीजिए जो मैं खुद नहीं कर सकता। आमीन।",
  "p.476": "प्यारे उद्धारकर्ता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं अपने प्रेम, वादों और हर उस रिश्ते को आपके हाथों में सौंपता हूँ जिसे आपके स्पर्श की ज़रूरत है। मेरे पास रहिए और वहाँ फिर से कोमलता भर दीजिए जहाँ तनाव ने हमारे बीच दूरियाँ पैदा कर दी हैं। मेरे विचार, चुनाव और व्यवहार हमें एक-दूसरे को सुनना, माफ करना और फिर से अपनाना सिखाएं। मेरा आज का जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "p.477": "सर्वशक्तिमान परमेश्वर, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी वफादार देखरेख में सौंपता हूँ। मेरे पास रहिए, उनके दिलों की रक्षा कीजिए, उनके फैसलों में उनकी अगुवाई कीजिए और उन्हें भले लोगों की संगति दीजिए। मेरे विचार, चुनाव और व्यवहार उन्हें आपको व्यक्तिगत और गहरे रूप से जानने में मदद करें। आपकी कृपा मेरी हर कमज़ोरी में मुझे मिले और मुझे शांति की राह पर ले चले। आमीन।",
  "p.478": "शांति के राजकुमार, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कीजिए। मेरे पास रहिए और हमें विनम्र, उदार, सच्चा और साहसी बनाइए। मेरे विचार, चुनाव और व्यवहार ऐसा हो कि हमारा जीवन इस दुनिया के सामने यीशु की सुंदरता को ज़ाहिर करे। मुझे धीरज से चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.479": "दया के पिता, मैं अपनी यह ज़रूरत आपको सौंपता हूँ: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थकने लगे हैं। मेरे पास रहिए और जहाँ निराशा ने घर कर लिया है, वहाँ फिर से उम्मीद की फूंक भर दीजिए। मेरे विचार, चुनाव और व्यवहार मुझे यह विश्वास करने में मदद करें कि आप अब भी मेरे जीवन की कहानी में अच्छी बातें लिख रहे हैं। मैं उन बातों में भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ, और उनमें भी जिन्हें मैं नहीं समझता। आमीन।",
  "p.480": "स्वर्गीय पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: किसी और की उम्मीदों को पूरा करने से पहले, मैं आज के इस दिन को आपके हाथों में सौंपता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—मेरे विचारों को सही दिशा दीजिए, मेरी भावनाओं को सँभालिए, और मुझे अच्छाई की ओर ले चलिए। आज, मेरा पहला कदम डर का नहीं बल्कि विश्वास का हो। आपकी करुणा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.481": "प्रभु यीशु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मेरा मन उन चिंताओं से भरा हुआ है जिन्हें मैं अकेले नहीं सुलझा सकता। मैं आपकी सहायता को स्वीकार करता हूँ—मेरे भीतर के शोर को शांत कीजिए और मुझे याद दिलाइए कि आपकी उपस्थिति मेरी घबराहट से कहीं बढ़कर है। आज मेरे हृदय को आपकी शांति में सांस लेना सिखाइए। मुझे धीरे-धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.482": "पवित्र आत्मा, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मेरे सामने का रास्ता मेरी सोच से कहीं ज़्यादा मुश्किल लग रहा है। मैं आपकी सहायता को स्वीकार करता हूँ—मुझे आज के हर कदम के लिए धीरज और आने वाले कल के लिए साहस दीजिए। आज मुझे मज़बूत बनाइए, पर मेरे मन को कठोर न होने दीजिए। जो बातें मैं समझता हूँ और जो नहीं, उन सबके लिए मैं आप पर भरोसा रखता हूँ। आमीन।",
  "p.483": "दयालु परमेश्वर, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं वो दर्द आपके पास लाता हूँ जिसे मैं बार-बार मन ही मन दोहराता रहता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—मुझे कड़वाहट से आज़ाद कीजिए और समझदारी, सच्चाई और अनुग्रह के साथ दूसरों को माफ़ करना सिखाइए। आज उन घावों को भर दीजिए जो सिर्फ़ माफ़ी माँगने से नहीं भरते। मेरे हृदय को वैसा बना दीजिए जैसा मसीह का हृदय है। आमीन।",
  "p.484": "करुणामय पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं अपने परिवार और अपने प्रियजनों को आपके सामने लाता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—हमारे घर को धीरज, ईमानदारी, सुरक्षा और प्रेम से सँभाले रखिए। आज हमारी बातों में मिठास और हमारे रिश्तों में मज़बूती दीजिए। मुझे अपने वचन में थामे रखिए, मुझे अपनी दया से घेर लीजिए और मुझे उम्मीद से भर दीजिए। आमीन।",
  "p.485": "विश्वासयोग्य प्रभु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं अपने हाथों की मेहनत और अपने कंधों के इस बोझ को आपको सौंपता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—सफलता के पीछे भागने के बजाय, सच्चे मन से काम करने में मेरी मदद कीजिए। आज लोगों की तारीफ़ से ज़्यादा मेरे लिए मेरी ईमानदारी मायने रखे। आपकी इच्छा ही मेरी शांति बने और आपकी उपस्थिति ही मेरी ताकत हो। आमीन।",
  "p.486": "प्यारे उद्धारकर्ता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं अपने शरीर, मन और प्राण के उन हिस्सों को आपके पास लाता हूँ जिन्हें चंगाई की ज़रूरत है। मैं आपकी सहायता को स्वीकार करता हूँ—मेरे घावों को छुइए, मेरी कमज़ोरियों को बल दीजिए, और मेरा इलाज करने वालों को बुद्धि दीजिए। आज जवाब मिलने से पहले ही मेरे भीतर एक नई उम्मीद जगा दीजिए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और आपकी आज्ञा मानने का साहस जुटा सकूँ। आमीन।",
  "p.487": "सर्वशक्तिमान परमेश्वर, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मुझे सिर्फ़ जानकारी नहीं, बल्कि आपकी पवित्र बुद्धि चाहिए। मैं आपकी सहायता को स्वीकार करता हूँ—मुझे दिखाइए कि क्या चुनना है, किसे छोड़ना है और कब इंतज़ार करना है। आज मुझे डर या घमंड में आकर कोई भी निर्णय लेने से बचाइए। मुझे आज किसी ऐसे व्यक्ति के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.488": "शांति के राजकुमार, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं थोड़ी देर रुककर उन नेमतों को देखना चाहता हूँ जिन्हें मैं अक्सर भाग-दौड़ में अनदेखा कर देता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—साधारण पलों में छिपे आपके वरदानों को देखने के लिए मेरी आँखें खोल दीजिए। आज धन्यवाद करना मेरे लिए कोई रस्म नहीं, बल्कि मेरा स्वभाव बन जाए। वह काम मुझमें पूरा कीजिए जिसे मैं अपने बल से नहीं कर सकता। आमीन।",
  "p.489": "दया के पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मैं अपने जीवन और अपने हर कदम पर आपकी सुरक्षा मांगता हूँ। मैं आपकी सहायता को स्वीकार करता हूँ—मुझे दिखने वाले खतरों और छिपे हुए जालों से बचाए रखिए। आज मुझे वहीं ले चलिए जहाँ मुझे जाना चाहिए, और जहाँ नहीं जाना चाहिए वहाँ मुझे रोक लीजिए। मेरा आज का जीवन आपकी सच्ची आराधना बन जाए। आमीन।",
  "p.490": "स्वर्गीय पिता, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: यह दुनिया मुझे मेरी नाकामियों और तकलीफों से तौलती है। मैं आपकी सहायता को स्वीकार करता हूँ—मुझे याद दिलाइए कि मैं आपका हूँ, आपके अनुग्रह से बचाया गया हूँ और आपके प्रेम में सुरक्षित हूँ। आज आपका सच हर झूठ से ज़्यादा ऊँचा सुनाई दे। आपकी करुणा मेरी हर कमज़ोरी में मेरा साथ दे और मुझे शांति की राह पर ले चले। आमीन।",
  "p.491": "प्रभु यीशु, आप देख रहे हैं कि मैं किन बोझों के साथ यहाँ हूँ, और आप जानते हैं कि ये मेरे लिए क्यों मायने रखते हैं: मेरे भीतर एक ऐसा दुख है जिसे शब्द बयां नहीं कर सकते। मैं आपकी सहायता को स्वीकार करता हूँ—इस दर्द में मेरे साथ बैठिए और मुझे बिना किसी जल्दबाज़ी के तसल्ली दीजिए। आज मुझे प्रेम के साथ पुरानी बातों को याद रखना और फिर भी उम्मीद के साथ जीना सिखाइए। मुझे धीरे-धीरे चलना, गहराई से प्रेम करना और पूरी तरह आप पर भरोसा करना सिखाइए। आमीन।",
  "p.492": "पवित्र आत्मा, आप देखते हैं कि मैं किस बोझ से दबा हूँ और आप जानते हैं कि यह मेरे लिए क्यों मायने रखता है: मैं उन चीज़ों का खिंचाव महसूस कर रहा हूँ जो मेरी आत्मा को कमज़ोर करती हैं। मैं आपकी मदद माँगता हूँ क्योंकि आप ही मुझे शुद्ध मन, निकलने का साफ़ रास्ता और जीवन को चुनने की ताकत देते हैं। आज, इसी पल में, आज्ञा मानना मेरे लिए मुमकिन कर दीजिए। मैं उन बातों के लिए भी आप पर भरोसा करता हूँ जिन्हें मैं समझता हूँ और उनके लिए भी जिन्हें मैं नहीं समझ पाता। आमीन।",
  "p.493": "अनुग्रहकारी परमेश्वर, आप देखते हैं कि मैं क्या सह रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं इंतज़ार करते-करते थक गया हूँ और उन चीज़ों को जबरदस्ती हासिल करने की कोशिश कर रहा हूँ जो अभी तैयार नहीं हैं। मैं आपकी मदद माँगता हूँ क्योंकि आप मुझे बिना कड़वाहट या हताशा के आपके सही समय पर भरोसा करना सिखाते हैं। आज, इस देरी के समय में मेरे अंदर एक शांत विश्वास जगाइए। मेरे हृदय को ऐसा रूप दीजिए कि मुझमें मसीह की छवि दिखाई दे। आमीन।",
  "p.494": "दयालु पिता, आप देखते हैं कि मैं किस हाल में हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं इस जीवन को आधे-अधूरे मन से या सोए हुए की तरह नहीं गुज़ारना चाहता। मैं आपकी मदद माँगता हूँ क्योंकि आप मुझे वे भले काम दिखाते हैं जो आपने आज मेरे लिए तैयार किए हैं। आज, मेरी वफ़ादारी के छोटे-छोटे कामों को अनंत काल के लिए फलदायक बना दीजिए। मुझे अपने वचन की बुनियाद पर खड़ा कीजिए, मुझे अपनी दया से घेर लीजिए और मुझे आशा से भर दीजिए। आमीन।",
  "p.495": "विश्वासयोग्य प्रभु, आप देखते हैं कि मैं किस बोझ के साथ दिन बिता रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: जैसे यह दिन ढल रहा है, मैं उन बातों को आपके हाथों में छोड़ता हूँ जिन्हें मैं आज रात ठीक नहीं कर सकता। मैं आपकी मदद माँगता हूँ क्योंकि आप मेरे मन को शांति से धोते हैं और सोते समय मेरे हृदय को सुरक्षित रखते हैं। आज की रात बीतने पर, आने वाली सुबह मेरे लिए नई करुणा लेकर आए। आपकी इच्छा ही मेरी शांति बन जाए और आपकी उपस्थिति ही मेरी ताकत। आमीन।",
  "p.496": "प्रेमी उद्धारकर्ता, आप देखते हैं कि मैं किन हालातों से गुज़र रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं अपने प्रेम, अपनी प्रतिबद्धता और हर उस रिश्ते को आपके सामने लाता हूँ जिसे आपके स्पर्श की ज़रूरत है। मैं आपकी मदद माँगता हूँ क्योंकि जहाँ तनाव ने हमें कठोर बना दिया है, वहाँ आप फिर से कोमलता भर देते हैं। आज, हमें एक-दूसरे की सुनना, माफ़ करना और फिर से एक-दूसरे को अपनाना सिखाइए। मुझे अपने इतने करीब रखिए कि मैं आपकी धीमी आवाज़ को सुन सकूँ और उसका पालन करने की हिम्मत रख सकूँ। आमीन।",
  "p.497": "सर्वशक्तिमान परमेश्वर, आप देखते हैं कि मैं क्या लेकर आया हूँ और आप जानते हैं कि यह क्यों मायने रखता है: मैं उन बच्चों और नौजवानों को जिन्हें मैं प्यार करता हूँ, आपकी विश्वासयोग्य देखरेख में सौंपता हूँ। मैं आपकी मदद माँगता हूँ क्योंकि आप ही उनके मन की रक्षा करते हैं, उनके फ़ैसलों में अगुवाई करते हैं और उन्हें समझदार लोगों का साथ देते हैं। आज, उन्हें आपकी व्यक्तिगत और गहरी पहचान पाने में मदद कीजिए। आज मुझे किसी ऐसे इंसान के लिए आशीष का कारण बनाइए जिसे आपकी दया की ज़रूरत है। आमीन।",
  "p.498": "शांति के राजकुमार, आप देखते हैं कि मैं किस चिंता में हूँ और आप जानते हैं कि यह क्यों मायने रखता है: अपने लोगों को आशीष दीजिए और एक-दूसरे के लिए हमारे प्रेम को नया कर दीजिए। मैं आपकी मदद माँगता हूँ क्योंकि आप ही हमें नम्र, उदार, सच्चा और निडर बनाते हैं। आज, हमारा जीवन देखने वाली दुनिया के सामने यीशु की सुंदरता को प्रकट करे। जो काम मैं खुद नहीं कर सकता, वह आप मुझमें कर दीजिए। आमीन।",
  "p.499": "दया के पिता, आप देखते हैं कि मैं क्या महसूस कर रहा हूँ और आप जानते हैं कि यह क्यों मायने रखता है: कुछ वादे बहुत दूर लगते हैं और कुछ सपने अब थके हुए से लगते हैं। मैं आपकी मदद माँगता हूँ क्योंकि जहाँ निराशा बैठ गई है, वहाँ आप आशा की नई फूँक मारते हैं। आज, मुझे यह विश्वास करने में मदद कीजिए कि आप अब भी मेरी ज़िंदगी के अच्छे अध्याय लिख रहे हैं। आज मेरा जीवन आपकी आराधना के लिए एक शांत भेंट बन जाए। आमीन।",
  "pd.0": "आपकी शांति मेरे विचारों पर शासन करे और मेरे हृदय को सहारा दे।",
  "pd.1": "आज विश्वास में एक-एक कदम बढ़ाने में मेरी मदद कीजिए।",
  "pd.2": "मुझे ऐसी आशा से भर दीजिए जो हर डर पर भारी पड़े।",
  "pd.3": "मुझे अपनी भावनाओं से ज़्यादा आप पर भरोसा करना सिखाइए। आमीन।",
  "pd.4": "प्रभु, आपकी उपस्थिति ही वो सामर्थ्य बने जिसका सहारा मैं आज लूँ। मैं अपनी हर ज़रूरत के लिए बस आप ही पर भरोसा रखता हूँ। आमीन।",
  "pd.5": "प्यारे परमेश्वर, इस घड़ी के लिए मुझे अपना अनुग्रह दीजिए और आने वाले पल के लिए हिम्मत। आप ही मेरा बल हैं। आमीन।",
  "pd.6": "मेरे मन की हर बेचैनी को शांत कर दीजिए और मुझे याद दिलाइए कि आप मेरे पास ही हैं। आपकी शांति मुझ पर बनी रहे। आमीन।",
  "pd.7": "पिता, मेरी सोच, मेरे शब्द और मेरे काम आपकी मर्जी के अनुसार हों। मुझे वैसा ही बनाइए जैसा आप चाहते हैं। आमीन।",
  "pd.8": "मेरे भीतर नई रूह फूँक दीजिए और मेरी मदद कीजिए कि आज मैं आपकी मोहब्बत दूसरों तक पहुँचा सकूँ। आपकी ज्योति मुझमें से चमके। आमीन।",
  "pd.9": "मुझे अपने पास थामे रखिए और बुद्धि और शांति के रास्ते पर मेरी अगुवाई कीजिए। आपके बिना मैं कुछ भी नहीं हूँ। आमीन।",
  "pd.10": "हे प्रभु, आज आप वो रोशनी बनिए जो मेरे हर कदम को राह दिखाए। मुझे अंधेरे से बचाकर अपनी ज्योति में चलाइए। आमीन।",
  "pd.11": "मेरे स्वर्गीय पिता, आज मुझे बार-बार यह याद दिलाइए कि मैं कभी भी अकेला नहीं हूँ। आप हर पल मेरे साथ-साथ चलते हैं। आमीन।",
  "pd.12": "प्रभु, मेरी आत्मा को अपनी उस महान सच्चाई में स्थिर रखिए जिसे कोई हिला नहीं सकता। मेरा भरोसा बस आप पर बना रहे। आमीन।",
  "pd.13": "चाहे घड़ी कितनी भी मुश्किल क्यों न हो, आपकी दी हुई खुशी मेरे दिल में उमड़ती रहे। आपकी खुशी ही मेरी ताकत है। आमीन।",
  "pd.14": "प्यारे पिता, मुझे अपने अनुग्रह का एक ऐसा पात्र बनाइए कि जो कोई भी मुझसे मिले, उसे आप ही का प्यार महसूस हो। आमीन।",
  "pd.15": "सुबह से लेकर रात ढलने तक, मुझे अपनी दया की छाँव में छिपाए रखिए। आपकी करुणा मुझ पर सदा बनी रहे। आमीन।",
  "pd.16": "प्यारे प्रभु, मेरे मन के हर डर और शक के शोर से कहीं ऊँची आपकी आवाज़ हो। आज मुझ से बात कीजिए ताकि मैं सिर्फ आपकी सुनूँ। आमीन।",
  "pd.17": "पिता, उन बोझों को आप थाम लीजिए जिन्हें अकेले उठाना मेरे बस में नहीं है। मेरा सहारा बनिए और मुझे विश्राम दीजिए। आमीन।",
  "pd.18": "प्रभु, आपका प्रेम मेरे ज़रिए दूसरों तक बिना किसी रुकावट और बेहिसाब बहता रहे। मुझे अपने प्यार का एक खुला ज़रिया बना दीजिए। आमीन।",
  "pd.19": "प्रभु, मेरे कदमों की अगुवाई कीजिए और मेरे दिल को हर पल अपनी ओर मोड़कर रखिए। मैं आपकी मरज़ी पर चलना चाहता हूँ। आमीन।",
  "pd.20": "परमेश्वर, मेरी कमज़ोरियों में मुझे अपनी ताकत दीजिए और जो कुछ भी टूट चुका है, उसे फिर से नया कर दीजिए। मुझे संभाल लीजिए। आमीन।",
  "pd.21": "प्रभु, जब मेरे आसपास की दुनिया बहुत शोर मचा रही हो, तब आप ही मेरी सच्ची शांति बन जाइए। मुझे अपने सुकून में रखिए। आमीन।",
  "pd.22": "हे प्रभु, मुझे ऐसी नज़र दीजिए कि मैं आज के दिन की हर बात में आपकी भलाई देख सकूँ और शुक्रगुज़ारी से भर जाऊँ। आमीन।",
  "pd.23": "प्यारे पिता, अपनी वफ़ादारी की चादर में मुझे इस तरह लपेट लीजिए कि मैं हर पल सुरक्षित और बेफ़िक्र रहूँ। आमीन।",
  "pd.24": "प्रभु, आप मुझे सुखदाई जल के सोतों के पास ले चलिए और मेरी थकी हुई आत्मा को नई ताज़गी से भर दीजिए। आमीन।",
  "pd.25": "परमेश्वर, अपना वचन मेरे दिल में इतनी गहराई तक बसा दो कि जीवन का कोई भी तूफ़ान मुझे डगमगा न सके। आमीन।",
  "pd.26": "मेरे प्रभु, मेरी ली हुई हर एक साँस आपकी महिमा करे और आपके लिए एक प्यारी भेंट बन जाए। आमीन।",
  "pd.27": "आज आप मेरे दिल की वह धीमी और मीठी आवाज़ बनिए, जिसे मैं चाहकर भी अनसुना न कर सकूँ। मेरी अगुवाई कीजिए। आमीन।",
  "pd.28": "प्यारे प्रभु, मुझे वो साहस दीजिए जो केवल स्वर्ग से आता है। मुझे निडर बनाइए ताकि मैं हर डर पर जय पा सकूँ और आपकी इच्छा पूरी करूँ। आमीन।",
  "pd.29": "हे स्वर्गीय पिता, मुझे अपने हृदय से लगा लीजिए और मुझे कभी भी अपने से दूर न भटकने दीजिए। हर पल मुझे अपने करीब रखिए। आमीन।",
  "p.amen": "आमीन।",
};
export default dict;
